public static void consumeEntries(ItemStack stack, StackConsumer consumer) {
        var data = getData(stack);

        if (data == null) return;

        data.accessories().forEach(innerStack -> {
            if (!innerStack.isEmpty()) consumer.handle(innerStack);
        });
    }

