        } else if (currentScreen == null) {
            EntityTarget target;

            if (keyMapping == OPEN_OTHERS_SCREEN) {
                target = EntityTarget.LOOKING_ENTITY;
            } else if (!OPEN_SCREEN.same(OPEN_OTHERS_SCREEN)) {
                target = EntityTarget.PLAYER;
