public static <C extends BaseOwoHandledScreen.SlotComponent> io.wispforest.owo.ui.core.Component createCraftingComponent(int start, Function<Integer, C> componentFactory, Consumer<Integer> slotEnabler, boolean isVertical) {
        for (int i = start; i < 5 + start; i++) slotEnabler.accept(i);

        var craftingLayout = isVertical ? verticalFlow(Sizing.fixed(18 * 2), Sizing.content()) : horizontalFlow(Sizing.content(), Sizing.fixed(18 * 2));

        craftingLayout.child(
                (!isVertical ? verticalFlow(Sizing.content(), Sizing.content()) : horizontalFlow(Sizing.content(), Sizing.content()))
                        .child(componentFactory.apply(start + 1).margins(Insets.of(1)))
                        .child(componentFactory.apply(start + 2).margins(Insets.of(1)))
        ).child(
                (!isVertical ? verticalFlow(Sizing.content(), Sizing.content()) : horizontalFlow(Sizing.content(), Sizing.content()))
                        .child(componentFactory.apply(start + 3).margins(Insets.of(1)))
                        .child(componentFactory.apply(start + 4).margins(Insets.of(1)))
        ).child(
                new ArrowComponent((isVertical) ? ArrowComponent.Direction.DOWN : ArrowComponent.Direction.RIGHT)
                        .centered(true)
                        .margins(Insets.of(3, 3, 1, 1))
                        .id("crafting_arrow")
        ).child(
                (!isVertical ? verticalFlow(Sizing.content(), Sizing.expand()) : horizontalFlow(Sizing.expand(), Sizing.content()))
                        .child(componentFactory.apply(start).margins(Insets.of(1)))
                        .horizontalAlignment(HorizontalAlignment.CENTER)
                        .verticalAlignment(VerticalAlignment.CENTER)
        ).allowOverflow(true)
                .horizontalAlignment(HorizontalAlignment.CENTER)
                .verticalAlignment(VerticalAlignment.CENTER);

        return Containers.verticalFlow(Sizing.content(), Sizing.content())
                .child(craftingLayout)
                .padding(Insets.of(7, 7, 4, 7));
    }

public static <C extends BaseOwoHandledScreen.SlotComponent> io.wispforest.owo.ui.core.Component createPlayerInv(int start, int end, Function<Integer, C> componentFactory, Consumer<Integer> slotEnabler) {
        var playerLayout = verticalFlow(Sizing.content(), Sizing.content());

        int row = 0;

        var rowLayout = horizontalFlow(Sizing.content(), Sizing.content())
                .configure((FlowLayout layout) -> layout.allowOverflow(true));

        int rowCount = 0;

        for (int i = start; i < end; i++) {
            var slotComponent = componentFactory.apply(i);

            slotEnabler.accept(i);

            rowLayout.child(slotComponent.margins(Insets.of(1)));

            if(row >= 8) {
                playerLayout.child(rowLayout);

                rowLayout = horizontalFlow(Sizing.content(), Sizing.content())
                        .configure((FlowLayout layout) -> layout.allowOverflow(true));

                rowCount++;

                if(rowCount == 3) rowLayout.margins(Insets.top(4));

                row = 0;
            } else {
                row++;
            }
        }

        return playerLayout.allowOverflow(true);
    }

public ExtendedCollapsibleContainer(Sizing horizontalSizing, Sizing verticalSizing, boolean expanded) {
        super(horizontalSizing, verticalSizing, Component.empty(), expanded);
        this.margins(Insets.top(0));

        this.configure((CollapsibleContainer component) -> {
            component.horizontalAlignment(HorizontalAlignment.CENTER);

            var titleLayout = component.titleLayout();

            titleLayout.padding(Insets.of(0));

            var spinyThing = titleLayout.children().get(1);

            spinyThing.sizing(Sizing.fixed(9));

            var contentLayout = component.children().get(1);

            if (expanded) {
                contentLayout.margins(Insets.top(-2));

                spinyThing.margins(Insets.of(0,1,2,0));
            } else {
                contentLayout.margins(Insets.top(0));

                spinyThing.margins(Insets.of(0,2,2,0));
            }

            if(contentLayout instanceof FlowLayout contentFlow) {
                contentFlow.surface(Surface.BLANK)
                        .padding(Insets.of(0))
                        .horizontalAlignment(HorizontalAlignment.CENTER);
                        //.margins(Insets.top(-2));
            }
        });

        this.onToggled().subscribe(nowExpanded -> {
            var contentLayout = this.children().get(1);

            if(contentLayout instanceof FlowLayout contentFlow) {
                var spinyThing = titleLayout.children().get(1);

                if (nowExpanded) {
                    contentFlow.margins(Insets.top(-2));

                    spinyThing.margins(Insets.of(0,1,2,0));
                } else {
                    contentFlow.margins(Insets.top(0));

                    spinyThing.margins(Insets.of(0,2,2,0));
                }
            }
        });
    }

public ExtendedScrollContainer(ScrollDirection direction, Sizing horizontalSizing, Sizing verticalSizing, C child) {
        super(direction, horizontalSizing, verticalSizing, child);
    }

public double getProgress() {
        return this.scrollOffset / this.maxScroll;
    }

public ExtendedScrollContainer<C> scrollToAfterLayout(double progress) {
        this.scrollToAfterLayout = () -> this.scrollOffset = (double)this.maxScroll * Math.clamp(progress, 0, 1);

        return this;
    }

@Override
    public void layout(Size space) {
        super.layout(space);

        if (this.scrollToAfterLayout != null) {
            this.scrollToAfterLayout.run();
            this.scrollToAfterLayout = null;
        }
    }

public ExtendedScrollContainer<C> customClippingInsets(Insets insets) {
        this.customClippingInsets = insets;

        return this;
    }

public ExtendedScrollContainer<C> oppositeScrollbar(boolean value) {
        this.oppositeScrollbar = value;

        return this;
    }

public boolean oppositeScrollbar() {
        return this.oppositeScrollbar;
    }

public ExtendedScrollContainer<C> strictMouseScrolling(boolean value){
        this.strictMouseScrolling = value;

        return this;
    }

@Override
    protected boolean isInScrollbar(double mouseX, double mouseY) {
        if(this.oppositeScrollbar) {
            return this.isInBoundingBox(mouseX, mouseY) && this.direction.choose(mouseY, mouseX) <= (this.x + scrollbarThiccness);
        } else {
            return super.isInScrollbar(mouseX, mouseY);
        }
    }

@Override
    protected Size calculateChildSpace(Size thisSpace) {
        final var padding = this.padding.get();

        return Size.of(
                Mth.lerpInt(this.horizontalSizing.get().contentFactor(), this.width - padding.horizontal() - horizontalScrollbarOffset(), thisSpace.width() - padding.horizontal()),
                Mth.lerpInt(this.verticalSizing.get().contentFactor(), this.height - padding.vertical() - verticalScrollbarOffset(), thisSpace.height() - padding.vertical())
        );
    }

@Override
    protected int childMountX() {
        return (int) super.childMountX() + horizontalScrollbarOffset();
    }

@Override
    protected int childMountY() {
        return (int) super.childMountY() + verticalScrollbarOffset();
    }

private int horizontalScrollbarOffset() {
        return (oppositeScrollbar && this.direction == ScrollDirection.VERTICAL) ? scrollbarThiccness : 0;
    }

private int verticalScrollbarOffset() {
        return (oppositeScrollbar && this.direction == ScrollDirection.HORIZONTAL) ? scrollbarThiccness : 0;
    }

public double currentScrollOffset() {
        return this.scrollOffset;
    }

public ExtendedScrollContainer<C> scrollTo(double scrollOffset) {
        this.scrollOffset = Mth.clamp(scrollOffset, 0, this.maxScroll);

        return this;
    }

public ExtendedScrollContainer<C> scrolledToCallback(TriConsumer<ExtendedScrollContainer<?>, Double, Double> consumer) {
        this.scrolledTo = consumer;

        return this;
    }

@Override
    protected void scrollBy(double offset, boolean instant, boolean showScrollbar) {
        var prevOffset = this.scrollOffset;

        super.scrollBy(offset, instant, showScrollbar);

        scrolledTo.accept(this, prevOffset, this.scrollOffset);
    }

@Override
    public boolean onMouseScroll(double mouseX, double mouseY, double amount) {
        if(this.strictMouseScrolling && !this.isInScrollbar(this.x + mouseX, this.y + mouseY)) return false;

        return super.onMouseScroll(mouseX, mouseY, amount);
    }

@Override
    protected void drawChildren(OwoUIDrawContext context, int mouseX, int mouseY, float partialTicks, float delta, List<? extends Component> children) {
        if (this.customClippingInsets != Insets.none()) {
            context.enableScissor(this.x + customClippingInsets.left(),
                this.y + customClippingInsets.top(),
                this.width - customClippingInsets.horizontal(),
                this.height - customClippingInsets.vertical());
        }

        super.drawChildren(context, mouseX, mouseY, partialTicks, delta, children);

        if (this.customClippingInsets != Insets.none()) {
            context.disableScissor();
        }
    }

