        } else {
            holder.child(currentPage.getLayout(screen.showCosmeticState()));
        }

        var accessoriesMainLayout = (FlowLayout) Containers.verticalFlow(Sizing.content(), Sizing.content())
                .gap(2)
                .child(holder)
