@Override
    protected void renderBg(GuiGraphics guiGraphics, float partialTick, int mouseX, int mouseY) {
        Integer minX = null, minY = null, maxX = null, maxY = null;

        for (Slot slot : this.menu.slots) {
            if(minX == null || slot.x < minX){
                minX = slot.x;
            } else if(maxX == null || slot.x > maxX){
                maxX = slot.x;
            }

            if(minY == null || slot.y < minY){
                minY = slot.y;
            } else if(maxY == null || slot.y > maxY){
                maxY = slot.y;
            }
        }

        var titleOffset = 12;

        var padding = 6;

        var width = (maxX - minX) + 18 + (padding * 2);
        var height = (maxY - minY) + 18 + (padding * 2) + titleOffset;

        var startX = minX - padding;
        var startY = minY - titleOffset - padding;

        guiGraphics.push().translate((float)leftPos, (float)topPos);

        DrawUtils.blitSprite(guiGraphics, BACKGROUND_PATCH, startX - 1, startY - 1, width + 1, height + 1);

        for (Slot slot : this.menu.slots) {
            DrawUtils.blit(guiGraphics, SLOT_FRAME, slot.x - 1, slot.y - 1, 18, 18);
        }

        guiGraphics.pop();
    }

