		} catch (IOException e) {
			PatchouliAPI.LOGGER.warn("Failed to load {}.", file, e);
			return null;
		}

		return null;
	}

static JsonElement streamToJson(InputStream stream) throws IOException {
		try (Reader reader = new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8))) {
			return GsonHelper.fromJson(BookRegistry.GSON, reader, JsonElement.class);
		}
	}

@Override
	public void findFiles(Book book, String dir, List<Identifier> list) {
		String prefix = String.format("%s/%s/%s/%s", BookRegistry.BOOKS_LOCATION, book.id.getPath(), BookContentsBuilder.DEFAULT_LANG, dir);
		Collection<Identifier> files = Minecraft.getInstance().getResourceManager().listResources(prefix, p -> p.getPath().endsWith(".json")).keySet();

		files.stream()
				.distinct()
				.filter(file -> file.getNamespace().equals(book.id.getNamespace()))
				.map(file -> {
					// caller expects list to contain logical id's, not file paths.
					// we end up going from path -> id -> back to path, but it's okay as a transitional measure
					Preconditions.checkArgument(file.getPath().startsWith(prefix));
					Preconditions.checkArgument(file.getPath().endsWith(".json"));
					String newPath = file.getPath().substring(prefix.length(), file.getPath().length() - ".json".length());
					// Vanilla expects `prefix` above to not have a trailing slash, so we
					// have to remove it ourselves from the path
					if (newPath.startsWith("/")) {
						newPath = newPath.substring(1);
					}
					return Identifier.fromNamespaceAndPath(file.getNamespace(), newPath);
				})
				.forEach(list::add);
	}

@Nullable
	@Override
	public LoadResult loadJson(Book book, Identifier file) {
		PatchouliAPI.LOGGER.debug("Loading {}", file);
		ResourceManager manager = Minecraft.getInstance().getResourceManager();
		try {
			var resourceOpt = manager.getResource(file);
			if (resourceOpt.isPresent()) {
				Resource resource = resourceOpt.get();
				return new LoadResult(
						BookContentLoader.streamToJson(resource.open()),
						computeAddedByText(resource.sourcePackId(), book)
				);
			} else {
				return null;
			}
		} catch (IOException ex) {
			throw new UncheckedIOException(ex);
		}
	}

@Nullable
	private static String computeAddedByText(String sourcePackId, Book book) {
		// Resource packs are named by "file/<packname>"
		if (sourcePackId.startsWith("file/")) {
			sourcePackId = sourcePackId.substring(5);
		}

		// Forge and Fabric lump all mod resources into one dummy pack.
		// Unsure how to handle them for now. TODO: Fix this
		// We'd like to show only those packs that are not in the one that originally
		// declared the book.
		if (sourcePackId.equals("mod_resources") || sourcePackId.equals("fabric")) {
			return null;
		}

		return sourcePackId;
	}

private BookContentResourceListenerLoader() {
		super(ExtraCodecs.JSON, FileToIdConverter.json("patchouli_books"));
	}

@Override
	protected void apply(Map<Identifier, JsonElement> map, ResourceManager manager, ProfilerFiller profiler) {
		Map<Identifier, Map<Identifier, JsonElement>> data = new HashMap<>();
		for (var entry : map.entrySet()) {
			// namespace:book_name/en_us/entries/entry
			var key = entry.getKey();
			var matcher = ID_READER.matcher(key.getPath());
			if (!matcher.matches()) {
				PatchouliAPI.LOGGER.trace("Ignored file {}", key);
				continue;
			}
			var bookId = Identifier.fromNamespaceAndPath(key.getNamespace(), matcher.group("bookId"));

			data.computeIfAbsent(bookId, id -> new HashMap<>()).put(entry.getKey(), entry.getValue());
		}

		int count = data.values().stream().mapToInt(Map::size).sum();
		PatchouliAPI.LOGGER.info("{} preloaded {} jsons", getClass().getSimpleName(), count);
		this.data = data;
	}

@Override
	public void findFiles(Book book, String dir, List<Identifier> list) {
		var stopwatch = Stopwatch.createStarted();

		var map = data.get(book.id);
		if (map == null) {
			return;
		}
		for (Identifier id : map.keySet()) {
			var matcher = ID_READER.matcher(id.getPath());
			if (!matcher.matches()) {
				continue;
			}
			if (dir.equals(matcher.group("folder"))
					&& BookContentsBuilder.DEFAULT_LANG.equals(matcher.group("lang"))) {
				list.add(Identifier.fromNamespaceAndPath(id.getNamespace(), matcher.group("entryId")));
			}
		}

		PatchouliAPI.LOGGER.info("{}: Files found in {}", getClass().getSimpleName(), stopwatch.stop());
	}

@Nullable
	@Override
	public LoadResult loadJson(Book book, Identifier file) {
		PatchouliAPI.LOGGER.trace("Loading {}", file);
		var map = data.get(book.id);
		if (map == null) {
			return null;
		}
		String path = file.getPath();
		// Drop patchouli_books/ and json suffix
		String relativizedPath = path.substring(0, path.length() - 5).split("/", 2)[1];

		JsonElement json = map.get(Identifier.fromNamespaceAndPath(file.getNamespace(), relativizedPath));
		if (json != null) {
			return new LoadResult(
					json,
					// todo implement this
					null
			);
		}

		return null;
	}

