@Nullable
	private T getRecipe(Identifier id) {
		var recipeHolder = ClientRecipes.INSTANCE.<T>getRecipeById(id);
		return recipeHolder != null && recipeHolder.value().getType() == recipeType ? recipeHolder.value() : null;
