public ItemStackArrayVariableSerializer() {
		super(new ItemStackVariableSerializer(), ItemStack.class);
	}

@Override
	public ItemStack[] fromJson(JsonElement json, HolderLookup.Provider registries) {
		if (json.isJsonArray()) {
			JsonArray array = json.getAsJsonArray();
			List<ItemStack> stacks = new ArrayList<>();
			for (JsonElement e : array) {
				stacks.addAll(Arrays.asList(fromNonArray(e, registries)));
			}
			return stacks.toArray(empty);
		}
		return fromNonArray(json, registries);
	}

public ItemStack[] fromNonArray(JsonElement json, HolderLookup.Provider registries) {
		if (json.isJsonNull()) {
			return empty;
		}
		if (json.isJsonPrimitive()) {
			return ItemStackUtil.loadStackListFromString(json.getAsString(), registries).stream().flatMap(e -> e.map(Stream::of, t -> t.stream().map(ItemStack::new))).toArray(ItemStack[]::new);
		}
		if (json.isJsonObject()) {
			return new ItemStack[] { ItemStackUtil.loadStackFromJson(json.getAsJsonObject(), registries) };
		}
		throw new IllegalArgumentException("Can't make an ItemStack from an array!");
	}

@Override
	public ItemStack fromJson(JsonElement json, HolderLookup.Provider registries) {
		if (json.isJsonNull()) {
			return ItemStack.EMPTY;
		}
		if (json.isJsonPrimitive()) {
			return ItemStackUtil.loadStackFromString(json.getAsString(), registries);
		}
		if (json.isJsonObject()) {
			return ItemStackUtil.loadStackFromJson(json.getAsJsonObject(), registries);
		}
		throw new IllegalArgumentException("Can't make an ItemStack from an array!");
	}

@Override
	public JsonElement toJson(ItemStack stack, HolderLookup.Provider registries) {
		// Adapted from net.minecraftforge.common.crafting.StackList::toJson
		JsonObject ret = new JsonObject();
		ret.addProperty("item", BuiltInRegistries.ITEM.getKey(stack.getItem()).toString());
		if (stack.getCount() != 1) {
			ret.addProperty("count", stack.getCount());
		}
		if (!stack.getComponents().isEmpty()) {
			DataComponentMap data = stack.getComponents();
			DataComponentMap.CODEC.encodeStart(registries.createSerializationContext(JsonOps.INSTANCE), data).result().ifPresent(e -> ret.add("components", e));
		}
		return ret;
	}

@Override
	public Component fromJson(JsonElement json, HolderLookup.Provider registries) {
		if (json.isJsonNull()) {
			return Component.literal("");
		}
		if (json.isJsonPrimitive()) {
			return Component.literal(json.getAsString());
		}
		return ComponentSerialization.CODEC.parse(registries.createSerializationContext(JsonOps.INSTANCE), json).getOrThrow();
	}

@Override
	public JsonElement toJson(Component stack, HolderLookup.Provider registries) {
		return ComponentSerialization.CODEC.encodeStart(registries.createSerializationContext(JsonOps.INSTANCE), stack).getOrThrow(JsonParseException::new);
	}

