private static void setup() {
		loadDir = new File(BookRegistry.BOOKS_LOCATION);
		if (!loadDir.exists()) {
			loadDir.mkdir();
		} else if (!loadDir.isDirectory()) {
			throw new RuntimeException(loadDir.getAbsolutePath() + " is a file, not a folder, aborting. Please delete this file or move it elsewhere if it has important contents.");
		}
	}

public static void findBooks() {
		if (loadDir == null) {
			setup();
		}

		XplatModContainer self = IXplatAbstractions.INSTANCE.getModContainer(PatchouliAPI.MOD_ID);
		File[] subdirs = loadDir.listFiles(File::isDirectory);
		if (subdirs == null) {
			PatchouliAPI.LOGGER.warn("Failed to list external books in {}, not loading external books",
					loadDir.getAbsolutePath());
			return;
		}

		for (File dir : subdirs) {
			Identifier res;
			try {
				res = Identifier.fromNamespaceAndPath(PatchouliAPI.MOD_ID, dir.getName());
			} catch (IdentifierException ex) {
				PatchouliAPI.LOGGER.error("Invalid external book folder name {}, skipping", dir.getName(), ex);
				continue;
			}

			File bookJson = new File(dir, "book.json");
			try (FileInputStream stream = new FileInputStream(bookJson)) {
				BookRegistry.INSTANCE.loadBook(self, res, stream, true);
			} catch (Exception e) {
				PatchouliAPI.LOGGER.error("Failed to load external book json from {}, skipping", bookJson, e);
			}
		}
	}

public void init() {
		Collection<XplatModContainer> mods = IXplatAbstractions.INSTANCE.getAllMods();

		for (XplatModContainer mod : mods) {
			String id = mod.getId();
			if (mod.getId().equals("minecraft")) {
				continue;
			}

			mod.visit(String.format("data/%s/%s", id, BOOKS_LOCATION), (path, file) -> {
				if (!path.getFileName().toString().equals("book.json")) {
					return;
				}

				String fileStr = path.toString().replaceAll("\\\\", "/");
				String relPath = fileStr.substring(fileStr.indexOf(BOOKS_LOCATION) + BOOKS_LOCATION.length() + 1);
				String bookName = relPath.substring(0, relPath.indexOf("/"));

				if (bookName.contains("/")) {
					PatchouliAPI.LOGGER.warn("Ignored book.json @ {}", path);
					return;
				}

				Identifier bookId = Identifier.fromNamespaceAndPath(id, bookName);
				try (InputStream stream = file.get()) {
					loadBook(mod, bookId, stream, false);
				} catch (Exception e) {
					PatchouliAPI.LOGGER.error("Failed to load book {} defined by mod {}, skipping", bookId, mod.getId(), e);
				}
			});
		}

		BookFolderLoader.findBooks();
		IXplatAbstractions.INSTANCE.signalBooksLoaded();
	}

public void loadBook(XplatModContainer mod, Identifier res, InputStream stream, boolean external) {
		Reader reader = new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8));
		var tree = GSON.fromJson(reader, JsonObject.class);
		books.put(res, new Book(tree, mod, res, external));
	}

