public static IStateMatcher fromString(String s) throws CommandSyntaxException {
		s = s.trim();
		if (s.equals("ANY")) {
			return StateMatcher.ANY;
		}
		if (s.equals("AIR")) {
			return StateMatcher.AIR;
		}

		// c.f. BlockPredicateArgument. Similar, but doesn't use vanilla's weird caching class.
		return BlockStateParser.parseForTesting(BuiltInRegistries.BLOCK, s, true).map(
				blockResult -> new ExactMatcher(blockResult.blockState(), blockResult.properties()),
				tagResult -> new TagMatcher(tagResult.tag(), tagResult.vagueProperties())
		);
	}

private ExactMatcher(BlockState state, Map<Property<?>, Comparable<?>> props) {
			this.state = state;
			this.props = props;
		}

@Override
		public BlockState getDisplayedState(long ticks) {
			return state;
		}

@Override
		public TriPredicate<BlockGetter, BlockPos, BlockState> getStatePredicate() {
			return (w, p, s) -> state.getBlock() == s.getBlock() && checkProps(s);
		}

private boolean checkProps(BlockState state) {
			for (Entry<Property<?>, Comparable<?>> e : props.entrySet()) {
				if (!state.getValue(e.getKey()).equals(e.getValue())) {
					return false;
				}
			}
			return true;
		}

@Override
		public boolean equals(Object o) {
			if (this == o) {
				return true;
			}
			if (o == null || getClass() != o.getClass()) {
				return false;
			}
			ExactMatcher that = (ExactMatcher) o;
			return Objects.equals(state, that.state) &&
					Objects.equals(props, that.props);
		}

@Override
		public int hashCode() {
			return Objects.hash(state, props);
		}

private TagMatcher(HolderSet<Block> tag, Map<String, String> props) {
			this.tag = tag;
			this.props = props;
		}

@Override
		public BlockState getDisplayedState(long ticks) {
			if (this.tag.size() == 0) {
				return Blocks.BEDROCK.defaultBlockState(); // show something impossible
			} else {
				int idx = (int) ((ticks / 20) % this.tag.size());
				return this.tag.get(idx).value().defaultBlockState();
			}
		}

@Override
		public TriPredicate<BlockGetter, BlockPos, BlockState> getStatePredicate() {
			return (w, p, s) -> s.is(tag) && checkProps(s);
		}

private boolean checkProps(BlockState state) {
			for (Entry<String, String> entry : props.entrySet()) {
				Property<?> prop = state.getBlock().getStateDefinition().getProperty(entry.getKey());
				if (prop == null) {
					return false;
				}

				Comparable<?> value = prop.getValue(entry.getValue()).orElse(null);
				if (value == null) {
					return false;
				}

				if (!state.getValue(prop).equals(value)) {
					return false;
				}
			}
			return true;
		}

@Override
		public boolean equals(Object o) {
			if (this == o) {
				return true;
			}
			if (o == null || getClass() != o.getClass()) {
				return false;
			}
			TagMatcher that = (TagMatcher) o;
			return Objects.equals(tag, that.tag) && Objects.equals(props, that.props);
		}

@Override
		public int hashCode() {
			return Objects.hash(tag, props);
		}

public static String getEntityName(String entityId) {
		Pair<String, String> nameAndNbt = splitNameAndNBT(entityId);
		EntityType<?> type = BuiltInRegistries.ENTITY_TYPE.getValue(Identifier.tryParse(nameAndNbt.getLeft()));

		return type.getDescriptionId();
	}

public static Function<Level, Entity> loadEntity(String entityId) {
		Pair<String, String> nameAndNbt = splitNameAndNBT(entityId);
		entityId = nameAndNbt.getLeft();
		String nbtStr = nameAndNbt.getRight();
		CompoundTag nbt = null;

		if (!nbtStr.isEmpty()) {
			try {
				nbt = TagParser.parseCompoundFully(nbtStr);
			} catch (CommandSyntaxException e) {
				PatchouliAPI.LOGGER.error("Failed to load entity data", e);
			}
		}

		Identifier key = Identifier.tryParse(entityId);
		Optional<EntityType<?>> maybeType = BuiltInRegistries.ENTITY_TYPE.getOptional(key);
		if (maybeType.isEmpty()) {
			throw new RuntimeException("Unknown entity id: " + entityId);
		}
		EntityType<?> type = maybeType.get();
		final CompoundTag useNbt = nbt;
		final String useId = entityId;
		return (world) -> {
			Entity entity;
			ProblemReporter.Collector problemReporter = new ProblemReporter.Collector();
			try {
				entity = type.create(world, EntitySpawnReason.LOAD);
			} catch (Exception e) {
				throw new IllegalArgumentException("Can't load entity " + useId, e);
			}

			if (entity == null) {
				throw new IllegalArgumentException("Can't create entity " + useId);
			}

			if (useNbt != null) {
				entity.load(TagValueInput.create(problemReporter, world.registryAccess(), useNbt));
			}

			String report = problemReporter.getTreeReport();
			if (!report.isEmpty()) {
				throw new IllegalArgumentException("Invalid entity data for " + useId + ": " + report);
			}

			return entity;
		};
	}

private static Pair<String, String> splitNameAndNBT(String entityId) {
		int nbtStart = entityId.indexOf("{");
		String nbtStr = "";
		if (nbtStart > 0) {
			nbtStr = entityId.substring(nbtStart).replaceAll("([^\\\\])'", "$1\"").replaceAll("\\\\'", "'");
			entityId = entityId.substring(0, nbtStart);
		}

		return Pair.of(entityId, nbtStr);
	}

public static ItemStackTemplate deserializeStack(String string, HolderLookup.Provider registries) {
		StringReader reader = new StringReader(string.trim());
		ItemParser itemParser = new ItemParser(registries);
		try {
			ItemInput result = itemParser.parse(reader);
			int count = 1;
			if (reader.canRead()) {
				reader.expect('#');
				count = reader.readInt();
			}
			return new ItemStackTemplate(result.item(), count, result.components());
		} catch (CommandSyntaxException e) {
			throw new RuntimeException(e);
		}
	}

public static ItemStack loadStackFromString(String res, HolderLookup.Provider registries) {
		return deserializeStack(res, registries).create();
	}

public static Ingredient loadIngredientFromString(String ingredientString, HolderLookup.Provider registries) {
		List<Either<ItemStack, HolderSet<Item>>> stacksOrTags = loadStackListFromString(ingredientString, registries);
		List<Ingredient> ingredients = new ArrayList<>();
		for (Either<ItemStack, HolderSet<Item>> stackOrTag : stacksOrTags) {
			ingredients.add(stackOrTag.map(IXplatAbstractions.INSTANCE::createComponentIngredient, Ingredient::of));
		}
		return switch (ingredients.size()) {
		case 0 -> throw new UnsupportedOperationException("Ingredients can't be empty");
		case 1 -> ingredients.getFirst();
		default -> IXplatAbstractions.INSTANCE.createCompoundIngredient(ingredients.toArray(new Ingredient[0]));
		};
	}

public static List<Either<ItemStack, HolderSet<Item>>> loadStackListFromString(String ingredientString, HolderLookup.Provider registries) {
		String[] stacksSerialized = splitStacksFromSerializedIngredient(ingredientString);
		List<Either<ItemStack, HolderSet<Item>>> stacks = new ArrayList<>();
		for (String s : stacksSerialized) {
			if (s.isEmpty())
				continue;
			if (s.startsWith("tag:")) {
				var key = TagKey.create(Registries.ITEM, Identifier.parse(s.substring(4)));
				registries.lookupOrThrow(Registries.ITEM).get(key).ifPresent(holders -> stacks.add(Either.right(holders)));
			} else {
				stacks.add(Either.left(loadStackFromString(s, registries)));
			}
		}
		return stacks;
	}

