        Identifier applicatorModel = ModelLocationUtils.getModelLocation(FBContent.ITEM_CAMO_APPLICATOR.value());
        itemModels.itemModelOutput.accept(
                FBContent.ITEM_CAMO_APPLICATOR.value(),
                ItemModelUtils.composite(
