        if (mode.applySecond()) {
            SoundType soundTwo = be.getCamoTwo().getContent().getSoundType();
            if (soundOne == null || !SoundUtils.isSameSound(soundOne, soundTwo, SoundEventType.STEP)) {
                SoundUtils.playStepSound(entity, soundTwo, volumeMult, pitchMult);
