        Direction face = ctx.getClickedFace();
        if (DirUtils.isY(face)) {
            state = null;
            return self();
        }

        if (!opposite) {
            face = face.getOpposite();
        }
        state = state.setValue(FramedProperties.FACING_HOR, face);
        return self();
    }

