@Override
    public final boolean supportsSolidOverlay(Direction side, boolean secondPart) {
        return secondPart ? (solidOverlay & (1 << side.ordinal())) != 0 : super.supportsSolidOverlay(side, false);
    }

@Override
    public final boolean supportsEdgeOverlay(Direction side, Direction edge, boolean secondPart, boolean nullCullFace, boolean unaligned) {
        if (secondPart) {
            return edgeOverlay.isSet(side, edge, nullCullFace, unaligned);
        }
        return super.supportsEdgeOverlay(side, edge, false, nullCullFace, unaligned);
    }

public final boolean mayCullNullFace(boolean secondPart) {
        return secondPart ? mayCullNullFacePartTwo : mayCullNullFacePartOne;
    }

@Override
    public boolean equals(@Nullable Object other) {
        if (!super.equals(other)) {
            return false;
        }
        DoubleBlockStateCache that = (DoubleBlockStateCache) other;
        return topInteractionMode == that.topInteractionMode &&
                parts.stateOne() == that.parts.stateOne() &&
                parts.stateTwo() == that.parts.stateTwo() &&
                Arrays.equals(solidityChecks, that.solidityChecks) &&
                Arrays.equals(camoGetters, that.camoGetters) &&
                solidOverlay == that.solidOverlay &&
                edgeOverlay.equals(that.edgeOverlay) &&
                mayCullNullFacePartOne == that.mayCullNullFacePartOne &&
                mayCullNullFacePartTwo == that.mayCullNullFacePartTwo;
    }

@Override
    public int hashCode() {
        int result = super.hashCode();
        result = 31 * result + Objects.hashCode(topInteractionMode);
        result = 31 * result + Objects.hashCode(parts.stateOne());
        result = 31 * result + Objects.hashCode(parts.stateTwo());
        result = 31 * result + Arrays.hashCode(solidityChecks);
        result = 31 * result + Arrays.hashCode(camoGetters);
        result = 31 * result + Byte.hashCode(solidOverlay);
        result = 31 * result + edgeOverlay.hashCode();
        result = 31 * result + Boolean.hashCode(mayCullNullFacePartOne);
        result = 31 * result + Boolean.hashCode(mayCullNullFacePartTwo);
        return result;
    }

boolean isSet(Direction side, Direction edge, boolean nullCullFace, boolean unaligned) {
        int mask = nullCullFace ? (unaligned ? maskBoth : maskNullCullFace) : maskUnaligned;
        return (mask & getBitMask(side, edge)) != 0;
    }

private static int getBitMask(Direction side, Direction edge) {
        return 1 << (side.ordinal() << 2 | DirUtils.get2dValueAround(side.getAxis(), edge));
    }

static EdgeOverlayMask compute(BlockState state, BlockOverlayPredicate predicate, boolean secondPart) {
        int maskNullCullFace = 0;
        int maskUnaligned = 0;
        int maskBoth = 0;
        for (Direction side : DIRECTIONS) {
            for (Direction edge : DIRECTIONS) {
                if (side.getAxis() == edge.getAxis()) {
                    continue;
                }

                for (EdgeOverlayCondition condition : EdgeOverlayCondition.VALUES) {
                    if (!predicate.supportsEdge(state, side, edge, secondPart, condition.nullCullFace, condition.unaligned)) {
                        continue;
                    }

                    int bitMask = getBitMask(side, edge);
                    switch (condition) {
                        case NULL_CULL -> maskNullCullFace |= bitMask;
                        case UNALIGNED -> maskUnaligned |= bitMask;
                        case BOTH -> maskBoth |= bitMask;
                    }
                }
            }
        }
        return intern(new EdgeOverlayMask(maskNullCullFace, maskUnaligned, maskBoth));
    }

private static EdgeOverlayMask intern(EdgeOverlayMask mask) {
        return MASK_INTERNER.addOrGet(mask);
    }

EdgeOverlayCondition(boolean nullCullFace, boolean unaligned) {
            this.nullCullFace = nullCullFace;
            this.unaligned = unaligned;
        }

public StateCache(BlockState state, IBlockType type) {
        byte fullFace = 0;
        byte mayConnect = 0;
        long conFullEdge = 0;
        long conDetailed = 0;
        byte solidOverlay = 0;

        FullFacePredicate facePred = type.getFullFacePredicate();
        ConnectionPredicate conPred = type.getConnectionPredicate();
        BlockOverlayPredicate overlayPredicate = type.getBlockOverlayPredicate();
        boolean supportsCt = type.supportsConnectedTextures();
        boolean supportsOverlay = type.supportsBlockOverlays();

        for (Direction side : DIRECTIONS) {
            byte sideBit = (byte) (1 << side.ordinal());
            if (facePred.test(state, side)) {
                fullFace |= sideBit;
            }
            if (supportsOverlay && overlayPredicate.supportsSolid(state, side, false)) {
                solidOverlay |= sideBit;
            }

            if (!supportsCt) {
                continue;
            }

            boolean fullEdgeNull = conPred.canConnectFullEdge(state, side, null);
            if (fullEdgeNull) {
                conFullEdge |= getSideEdgeNullableMask(side, null);
                mayConnect |= sideBit;
            }

            for (Direction edge : DIRECTIONS) {
                long feMask = getSideEdgeNullableMask(side, edge);
                if (edge.getAxis() == side.getAxis()) {
                    if (fullEdgeNull) {
                        conFullEdge |= feMask;
                    }
                    continue;
                }

                if (conPred.canConnectFullEdge(state, side, edge)) {
                    conFullEdge |= feMask;
                    mayConnect |= sideBit;
                }

                if (conPred.canConnectDetailed(state, side, edge)) {
                    conDetailed |= getSideEdgeMask(side, edge);
                    mayConnect |= sideBit;
                }
            }
        }

        this.fullFace = fullFace;
        this.mayConnect = mayConnect;
        this.conFullEdge = conFullEdge;
        this.conDetailed = conDetailed;
        this.solidOverlay = solidOverlay;
        this.edgeOverlay = supportsOverlay ? EdgeOverlayMask.compute(state, overlayPredicate, false) : EdgeOverlayMask.NEVER;
    }

private StateCache() {
        this.fullFace = 0;
        this.mayConnect = 0;
        this.conFullEdge = 0;
        this.conDetailed = 0;
        this.solidOverlay = 0;
        this.edgeOverlay = EdgeOverlayMask.NEVER;
    }

