@Override
    public boolean equals(@Nullable Object other) {
        if (this == other) {
            return true;
        }
        if (other == null || getClass() != other.getClass()) {
            return false;
        }
        StateCache that = (StateCache) other;
        return fullFace == that.fullFace &&
               conFullEdge == that.conFullEdge &&
               conDetailed == that.conDetailed &&
