        int result = Byte.hashCode(fullFace);
        result = 31 * result + Long.hashCode(conFullEdge);
        result = 31 * result + Long.hashCode(conDetailed);
        result = 31 * result + Byte.hashCode(solidOverlay);
        result = 31 * result + edgeOverlay.hashCode();
        return result;
