    public final boolean validateCamo(T container) {
        if (container.getState().getBlock() instanceof IFramedBlock) {
            return false;
        }
        return isValidBlock(container.getState(), EmptyBlockGetter.INSTANCE, BlockPos.ZERO, null);
    }

