@Override
    public boolean supportsSolid(BlockState state, Direction side, boolean secondPart) {
        Direction facing = state.getValue(FramedProperties.FACING_HOR);
        if (side == facing) {
            return !secondPart;
        }
        if (side == facing.getOpposite()) {
            return secondPart;
        }
        return true;
    }

@Override
    public boolean supportsEdge(BlockState state, Direction side, Direction edge, boolean secondPart, boolean nullCullFace, boolean unaligned) {
        Direction facing = state.getValue(FramedProperties.FACING_HOR);
        if (side.getAxis() != facing.getAxis()) {
            if (edge == facing) {
                return !secondPart;
            }
            if (edge == facing.getOpposite()) {
                return secondPart;
            }
            return true;
        }
        return true;
    }

@Override
    public boolean supportsSolid(BlockState state, Direction side, boolean secondPart) {
        return switch (side) {
            case UP -> secondPart;
            case DOWN -> !secondPart;
            default -> true;
        };
    }

@Override
    public boolean supportsEdge(BlockState state, Direction side, Direction edge, boolean secondPart, boolean nullCullFace, boolean unaligned) {
        if (!DirUtils.isY(side)) {
            return switch (edge) {
                case UP -> secondPart;
                case DOWN -> !secondPart;
                default -> true;
            };
        }
        return true;
    }

