public static boolean extractOneFromItemAccess(ItemAccess access, boolean commit) {
        try (Transaction tx = Transaction.openRoot()) {
            if (access.extract(access.getResource(), 1, tx) == 1) {
                if (commit) {
                    tx.commit();
                }
                return true;
            }
            return false;
        }
    }

