        return stack.canPerformAction(FramedConstants.ItemAbilities.ACTION_WRENCH_ROTATE) || (stack.is(FramedConstants.Tags.TOOL_WRENCH) && !stack.is(FramedConstants.Tags.COMPLEX_WRENCH));
