public FramedBarsGeometry(GeometryFactory.Context ctx) {
        super(ctx);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        Direction face = quad.direction();
        if (DirUtils.isY(face)) {
            createTopBottomCenterQuad(quadMap, quad, false);
            createTopBottomCenterQuad(quadMap, quad, true);

            if (north) {
                createTopBottomEdgeQuad(quadMap, quad, Direction.NORTH, false);
                createTopBottomEdgeQuad(quadMap, quad, Direction.NORTH, true);
            }
            if (east) {
                createTopBottomEdgeQuad(quadMap, quad, Direction.EAST, false);
                createTopBottomEdgeQuad(quadMap, quad, Direction.EAST, true);
            }
            if (south) {
                createTopBottomEdgeQuad(quadMap, quad, Direction.SOUTH, false);
                createTopBottomEdgeQuad(quadMap, quad, Direction.SOUTH, true);
            }
            if (west) {
                createTopBottomEdgeQuad(quadMap, quad, Direction.WEST, false);
                createTopBottomEdgeQuad(quadMap, quad, Direction.WEST, true);
            }
        } else {
            if (!isSideInset(face)) {
                createSideEdgeQuad(quadMap, quad, false, false);
            }
            if (!isSideInset(face.getOpposite())) {
                createSideEdgeQuad(quadMap, quad, false, true);
            }

            if (DirUtils.isX(face)) {
                createCenterPillarQuad(quadMap, quad, east, west, south, north);

                if (north) {
                    createPillarQuad(quadMap, quad, Direction.NORTH);
                    createBarQuads(quadMap, quad, Direction.NORTH);
                }
                if (south) {
                    createPillarQuad(quadMap, quad, Direction.SOUTH);
                    createBarQuads(quadMap, quad, Direction.SOUTH);
                }
            }

            if (DirUtils.isZ(face)) {
                createCenterPillarQuad(quadMap, quad, south, north, east, west);

                if (east) {
                    createPillarQuad(quadMap, quad, Direction.EAST);
                    createBarQuads(quadMap, quad, Direction.EAST);
                }
                if (west) {
                    createPillarQuad(quadMap, quad, Direction.WEST);
                    createBarQuads(quadMap, quad, Direction.WEST);
                }
            }
        }
    }

@Override
    public boolean useSolidNoCamoModel() {
        return true;
    }

private static void createCenterPillarQuad(QuadMapBuilder quadMap, BakedQuad quad, boolean perpNeg, boolean perpPos, boolean parNeg, boolean parPos) {
        if (perpNeg && perpPos && !parNeg && !parPos) {
            return;
        }

        boolean perpendicular = perpNeg || perpPos;
        boolean oneParallel = parNeg ^ parPos;

        float minXZ = perpendicular && oneParallel && !parPos ? 8F/16F : 7F/16F;
        float maxXZ = perpendicular && oneParallel && !parNeg ? 8F/16F : 9F/16F;

        float offset;
        if (parNeg || parPos) {
            offset = .5F;
        } else {
            offset = perpNeg ? 9F/16F : (perpPos ? 7F/16F : .5F);

            if (DirUtils.isPositive(quad.direction())) {
                offset = 1F - offset;
            }
        }

        QuadModifier.of(quad)
                .apply(Modifiers.cutSide(minXZ, 0, maxXZ, 1))
                .apply(Modifiers.setPosition(offset))
                .export(quadMap, null);
    }

private static void createPillarQuad(QuadMapBuilder quadMap, BakedQuad quad, Direction dir) {
        if (DirUtils.isY(dir)) {
            throw new IllegalArgumentException(String.format("Invalid direction: %s!", dir));
        }

        boolean positive = DirUtils.isPositive(dir);
        float minXZ = positive ? 12F/16F : 2F/16F;
        float maxXZ = positive ? 14F/16F : 4F/16F;

        QuadModifier.of(quad)
                .apply(Modifiers.cutSide(minXZ, 0, maxXZ, 1))
                .apply(Modifiers.setPosition(.5F))
                .export(quadMap, null);
    }

private static void createBarQuads(QuadMapBuilder quadMap, BakedQuad quad, Direction dir) {
        if (DirUtils.isY(dir)) {
            throw new IllegalArgumentException(String.format("Invalid direction: %s!", dir));
        }

        boolean positive = DirUtils.isPositive(dir);
        boolean northeast = dir == Direction.NORTH || dir == Direction.EAST;

        float minXZ = positive ?  9F/16F : 4F/16F;
        float maxXZ = positive ? 12F/16F : 7F/16F;
        float minY = northeast ? 2F/16F : 12F/16F;
        float maxY = northeast ? 4F/16F : 14F/16F;

        QuadModifier.of(quad)
                .apply(Modifiers.cutSide(minXZ, minY, maxXZ, maxY))
                .apply(Modifiers.setPosition(.5F))
                .export(quadMap, null);

        minXZ = positive ? 14F/16F : 0;
        maxXZ = positive ? 1 :  2F/16F;

        QuadModifier.of(quad)
                .apply(Modifiers.cutSide(minXZ, 7F/16F, maxXZ, 9F/16F))
                .apply(Modifiers.setPosition(.5F))
                .export(quadMap, null);
    }

public FramedBoardGeometry(GeometryFactory.Context ctx) {
        this.faces = ctx.state().getValue(PropertyHolder.FACES);
        this.allFaces = faces == 0b00111111;
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        Direction quadDir = quad.direction();
        if (hasFace(quadDir.getOpposite()) && !canCullInner(blockData)) {
            QuadModifier modifier = QuadModifier.of(quad)
                    .apply(Modifiers.setPosition(DEPTH));
            for (Direction edge : EDGES[quadDir.getAxis().ordinal()]) {
                if (hasFace(edge)) {
                    modifier.apply(Modifiers.cut(edge, 1F - DEPTH));
                }
            }
            modifier.export(quadMap, null);
        }
        if (!hasFace(quadDir)) {
            Direction[] edges = EDGES[quadDir.getAxis().ordinal()];
            for (int i = 0; i < edges.length; i++) {
                Direction edge = edges[i];
                if (!hasFace(edge)) {
                    continue;
                }

                QuadModifier modifier = QuadModifier.of(quad)
                        .apply(Modifiers.cut(edge.getOpposite(), DEPTH));
                if (i % 2 != 0) {
                    Direction cornerOne = edges[i - 1];
                    Direction cornerTwo = edges[(i + 1) % 4];
                    if (hasFace(cornerOne)) {
                        modifier.apply(Modifiers.cut(cornerOne, 1F - DEPTH));
                    }
                    if (hasFace(cornerTwo)) {
                        modifier.apply(Modifiers.cut(cornerTwo, 1F - DEPTH));
                    }
                }
                modifier.export(quadMap, quadDir);
            }
        }
    }

private boolean hasFace(Direction side) {
        return (faces & (1 << side.ordinal())) != 0;
    }

private boolean canCullInner(FramedBlockData blockData) {
        return allFaces && blockData.getCamoContent().isSolid();
    }

@Override
    public boolean transformAllQuads() {
        return true;
    }

public FramedPaneGeometry(GeometryFactory.Context ctx) {
        this.north = ctx.state().getValue(BlockStateProperties.NORTH);
        this.east = ctx.state().getValue(BlockStateProperties.EAST);
        this.south = ctx.state().getValue(BlockStateProperties.SOUTH);
        this.west = ctx.state().getValue(BlockStateProperties.WEST);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        Direction face = quad.direction();
        if (DirUtils.isY(face)) {
            if (isPillarVisible()) {
                createTopBottomCenterQuad(quadMap, quad, false);
            }

            if (north) {
                createTopBottomEdgeQuad(quadMap, quad, Direction.NORTH, false);
            }
            if (east) {
                createTopBottomEdgeQuad(quadMap, quad, Direction.EAST, false);
            }
            if (south) {
                createTopBottomEdgeQuad(quadMap, quad, Direction.SOUTH, false);
            }
            if (west) {
                createTopBottomEdgeQuad(quadMap, quad, Direction.WEST, false);
            }
        } else {
            boolean inset = isSideInset(face);
            if (!inset || isPillarVisible()) {
                createSideEdgeQuad(quadMap, quad, inset, false);
            }

            if (DirUtils.isX(face)) {
                if (north) {
                    createSideQuad(quadMap, quad, Direction.NORTH);
                }
                if (south) {
                    createSideQuad(quadMap, quad, Direction.SOUTH);
                }
            }

            if (DirUtils.isZ(face)) {
                if (east) {
                    createSideQuad(quadMap, quad, Direction.EAST);
                }
                if (west) {
                    createSideQuad(quadMap, quad, Direction.WEST);
                }
            }
        }
    }

protected boolean isPillarVisible() {
        return true;
    }

protected static void createTopBottomCenterQuad(QuadMapBuilder quadMap, BakedQuad quad, boolean mirrored) {
        QuadModifier.of(quad)
                .apply(Modifiers.cutTopBottom(7F/16F, 7F/16F, 9F/16F, 9F/16F))
                .applyIf(Modifiers.setPosition(.001F), mirrored)
                .export(quadMap, mirrored ? null : quad.direction());
    }

protected static void createTopBottomEdgeQuad(QuadMapBuilder quadMap, BakedQuad quad, Direction dir, boolean mirrored) {
        Preconditions.checkArgument(!DirUtils.isY(dir), String.format("Invalid direction: %s!", dir));

        QuadModifier.of(quad)
                .apply(Modifiers.cut(dir.getOpposite(), 7F/16F))
                .apply(Modifiers.cut(dir.getClockWise().getAxis(), 9F/16F))
                .applyIf(Modifiers.setPosition(.001F), mirrored)
                .export(quadMap, mirrored ? null : quad.direction());
    }

protected static void createSideEdgeQuad(QuadMapBuilder quadMap, BakedQuad quad, boolean inset, boolean mirrored) {
        Preconditions.checkArgument(!inset || !mirrored, "Quad can't be mirrored and inset!");

        Direction quadDir = quad.direction();
        Direction exportSide = inset ? null : (mirrored ? quadDir.getOpposite() : quadDir);

        QuadModifier.of(quad)
                .apply(Modifiers.cut(quadDir.getClockWise().getAxis(), 9F/16F))
                .applyIf(Modifiers.setPosition(9F/16F), inset)
                .applyIf(Modifiers.setPosition(.001F), !inset && mirrored)
                .export(quadMap, exportSide);
    }

private static void createSideQuad(QuadMapBuilder quadMap, BakedQuad quad, Direction dir) {
        QuadModifier.of(quad)
                .apply(Modifiers.cut(dir.getOpposite(), 7F/16F))
                .apply(Modifiers.setPosition(9F/16F))
                .export(quadMap, null);
    }

protected boolean isSideInset(Direction face) {
        return switch (face) {
            case NORTH -> !north;
            case EAST -> !east;
            case SOUTH -> !south;
            case WEST -> !west;
            default -> throw new IllegalArgumentException(String.format("Invalid face: %s!", face));
        };
    }

public FramedChainGeometry(GeometryFactory.Context ctx) {
        this.axis = ctx.state().getValue(FramedChainBlock.AXIS);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        Direction quadDir = quad.direction();
        if (quadDir.getAxis() == axis) {
            return;
        }

        Direction.Axis quadPerpAxis = DirUtils.getPerpendicularAxis(quadDir.getAxis(), axis);
        if (axis == Direction.Axis.Y) {
            createChainEdgeParts(quadMap, quad, quadDir, quadPerpAxis, DirUtils::isX, Modifiers::cut, Modifiers::cut);
            createChainCenterParts(quadMap, quad, Modifiers::cut, length -> Modifiers.cut(quadPerpAxis, length));
        } else {
            if (DirUtils.isY(quadDir)) {
                Direction.Axis perpAxis = axis == Direction.Axis.X ? Direction.Axis.Z : Direction.Axis.X;

                createChainEdgeParts(quadMap, quad, quadDir, quadPerpAxis, _ -> axis == Direction.Axis.Z, Modifiers::cut, Modifiers::cut);
                createChainCenterParts(quadMap, quad, Modifiers::cut, len -> Modifiers.cut(perpAxis, len));
            } else {
                createChainEdgeParts(quadMap, quad, quadDir, quadPerpAxis, _ -> axis == Direction.Axis.X, Modifiers::cut, Modifiers::cut);
                createChainCenterParts(quadMap, quad, Modifiers::cut, length -> Modifiers.cut(Direction.Axis.Y, length));
            }
        }
    }

private void createChainEdgeParts(
            QuadMapBuilder quadMap,
            BakedQuad quad,
            Direction quadDir,
            Direction.Axis quadPerpAxis,
            Predicate<Direction> fourSectionPred,
            CutterFactory vertCutterFactory,
            CutterFactory horCutterFactory
    ) {
        Direction dirUp = Direction.fromAxisAndDirection(axis, Direction.AxisDirection.POSITIVE);
        Direction dirDown = Direction.fromAxisAndDirection(axis, Direction.AxisDirection.NEGATIVE);
        Direction dirNeg = Direction.fromAxisAndDirection(quadPerpAxis, Direction.AxisDirection.NEGATIVE);
        Direction dirPos = Direction.fromAxisAndDirection(quadPerpAxis, Direction.AxisDirection.POSITIVE);

        List<MultiQuadModifier> modifiers = new ArrayList<>();

        MultiQuadModifier baseMod = new MultiQuadModifier(
                QuadModifier.of(quad)
                        .apply(horCutterFactory.create(dirNeg, 10F/16F))
                        .apply(horCutterFactory.create(dirPos,  7F/16F))
                        .apply(Modifiers.offset(dirPos, .5F/16F)),
                QuadModifier.of(quad)
                        .apply(horCutterFactory.create(dirNeg,  7F/16F))
                        .apply(horCutterFactory.create(dirPos, 10F/16F))
                        .apply(Modifiers.offset(dirNeg, .5F/16F))
        );

        if (fourSectionPred.test(quadDir)) {
            modifiers.add(baseMod.derive()
                    .apply(vertCutterFactory.create(dirUp, 2F/16F))
            );
            modifiers.add(baseMod.derive()
                    .apply(vertCutterFactory.create(dirUp, 7F/16F))
                    .apply(vertCutterFactory.create(dirDown, 13F/16F))
            );
            modifiers.add(baseMod.derive()
                    .apply(vertCutterFactory.create(dirDown, 7F/16F))
                    .apply(vertCutterFactory.create(dirUp, 13F/16F))
            );
            modifiers.add(baseMod.derive()
                    .apply(vertCutterFactory.create(dirDown, 2F/16F))
            );
        } else {
            modifiers.add(baseMod.derive()
                    .apply(vertCutterFactory.create(dirDown, 4F/16F))
                    .apply(vertCutterFactory.create(dirUp, 15F/16F))
            );
            modifiers.add(baseMod.derive()
                    .apply(vertCutterFactory.create(dirDown, 10F/16F))
                    .apply(vertCutterFactory.create(dirUp, 10F/16F))
            );
            modifiers.add(baseMod.derive()
                    .apply(vertCutterFactory.create(dirUp, 4F/16F))
                    .apply(vertCutterFactory.create(dirDown, 15F/16F))
            );
        }

        for (MultiQuadModifier mod : modifiers) {
            mod.apply(Modifiers.setPosition(.5F))
                    .apply(Modifiers.rotate(axis, ROT_ORIGIN, 45, false))
                    .export(quadMap, null);
        }

        baseMod.discard();
    }

private void createChainCenterParts(
            QuadMapBuilder quadMap,
            BakedQuad quad,
            CutterFactory vertCutterFactory,
            BidirectionalCutterFactory horCutterFactory
    ) {
        Direction dirUp = Direction.fromAxisAndDirection(axis, Direction.AxisDirection.POSITIVE);
        Direction dirDown = Direction.fromAxisAndDirection(axis, Direction.AxisDirection.NEGATIVE);

        for (int i = 0; i < 6; i++) {
            float height = switch (i) {
                case 0 -> 2F;
                case 5 -> 15F;
                default -> 3F * i + 1F;
            };
            QuadModifier.of(quad)
                    .apply(horCutterFactory.create(8.5F/16F))
                    .apply(vertCutterFactory.create(dirDown, height / 16F))
                    .apply(vertCutterFactory.create(dirUp, (16F - height + 1F) / 16F))
                    .apply(Modifiers.setPosition(.5F))
                    .apply(Modifiers.rotate(axis, ROT_ORIGIN, 45, false))
                    .export(quadMap, null);
        }
    }

@Override
    public boolean useSolidNoCamoModel() {
        return true;
    }

public FramedLightningRodGeometry(GeometryFactory.Context ctx) {
        this.facing = ctx.state().getValue(BlockStateProperties.FACING);
        this.copycatHead = ctx.state().getValue(FramedProperties.COPYCAT_STYLE);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object cacheKeyUserData) {
        Direction quadDir = quad.direction();
        boolean vertical = DirUtils.isY(quadDir);
        boolean front = quadDir == facing;
        boolean back = quadDir == facing.getOpposite();

        if (copycatHead) {
            for (Direction dir : DIRECTIONS) {
                if (dir.getAxis() == quadDir.getAxis()) {
                    continue;
                }

                Direction dirCw = dir.getClockWise(quadDir.getAxis());
                float dirOff = getOffset(dir);
                float dirCwOff = getOffset(dirCw);
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir, 2F / 16F))
                        .apply(Modifiers.cut(dirCw, 2F / 16F))
                        .apply(Modifiers.offset(dir, dirOff))
                        .apply(Modifiers.offset(dirCw, dirCwOff))
                        .applyIf(Modifiers.setPosition(back ? 4F / 16F : 10F / 16F), !front)
                        .export(quadMap, front ? quadDir : null);
            }
        } else if (front || back) {
            QuadModifier.of(quad)
                    .apply(vertical ? MOD_HEAD_VERT : MOD_HEAD_HOR)
                    .applyIf(Modifiers.setPosition(4F/16F), back)
                    .export(quadMap, front ? quadDir : null);
        } else {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(facing.getOpposite(), 4F/16F))
                    .apply(Modifiers.cut(facing.getClockWise(quadDir.getAxis()), 10F/16F))
                    .apply(Modifiers.cut(facing.getCounterClockWise(quadDir.getAxis()), 10F/16F))
                    .apply(Modifiers.setPosition(10F/16F))
                    .export(quadMap, null);
        }

        if (back) {
            QuadModifier.of(quad)
                    .apply(vertical ? MOD_TAIL_VERT : MOD_TAIL_HOR)
                    .export(quadMap, quadDir);
        } else if (!front) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(facing, 12F/16F))
                    .apply(Modifiers.cut(facing.getClockWise(quadDir.getAxis()), 9F/16F))
                    .apply(Modifiers.cut(facing.getCounterClockWise(quadDir.getAxis()), 9F/16F))
                    .apply(Modifiers.setPosition(9F/16F))
                    .export(quadMap, null);
        }
    }

private float getOffset(Direction offsetDir) {
        if (offsetDir == facing) {
            return 12F / 16F;
        }
        if (offsetDir == facing.getOpposite()) {
            return 0F;
        }
        return 6F/16F;
    }

@Override
    public boolean useSolidNoCamoModel() {
        return true;
    }

public FramedWallGeometry(GeometryFactory.Context ctx) {
        this.center = ctx.state().getValue(BlockStateProperties.UP);
        this.north = ctx.state().getValue(BlockStateProperties.NORTH_WALL);
        this.east =  ctx.state().getValue(BlockStateProperties.EAST_WALL);
        this.south = ctx.state().getValue(BlockStateProperties.SOUTH_WALL);
        this.west =  ctx.state().getValue(BlockStateProperties.WEST_WALL);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        if (north != WallSide.NONE) {
            buildWallHalfSegment(quadMap, quad, Direction.NORTH, north);
        }
        if (south != WallSide.NONE) {
            buildWallHalfSegment(quadMap, quad, Direction.SOUTH, south);
        }

        if (east != WallSide.NONE) {
            buildWallHalfSegment(quadMap, quad, Direction.EAST, east);
        }
        if (west != WallSide.NONE) {
            buildWallHalfSegment(quadMap, quad, Direction.WEST, west);
        }

        buildWallEndCap(quadMap, quad, Direction.NORTH, north);
        buildWallEndCap(quadMap, quad, Direction.EAST, east);
        buildWallEndCap(quadMap, quad, Direction.SOUTH, south);
        buildWallEndCap(quadMap, quad, Direction.WEST, west);

        buildCenterPillar(quadMap, quad);
    }

private void buildWallHalfSegment(QuadMapBuilder quadMap, BakedQuad quad, Direction dir, WallSide height) {
        if (height != WallSide.NONE) {
            Direction quadDir = quad.direction();
            if (DirUtils.isY(quadDir)) {
                Vector4f rect = rects[dir.ordinal() - 2 + (center ? 4 : 0)];
                boolean inset = height != WallSide.TALL && quadDir != Direction.DOWN;
                QuadModifier.of(quad)
                        .apply(Modifiers.cutTopBottom(rect.x(), rect.y(), rect.z(), rect.w()))
                        .applyIf(Modifiers.setPosition(LOW_HEIGHT), inset)
                        .export(quadMap, inset ? null : quadDir);
            } else if (quadDir.getAxis() != dir.getAxis()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getOpposite(), center ? LARGE_MIN : SMALL_MIN))
                        .applyIf(Modifiers.cut(Direction.UP, LOW_HEIGHT), height != WallSide.TALL)
                        .apply(Modifiers.setPosition(SMALL_MAX))
                        .export(quadMap, null);
            }
        }
    }

private static void buildWallEndCap(QuadMapBuilder quadMap, BakedQuad quad, Direction dir, WallSide height) {
        if (quad.direction() == dir && height != WallSide.NONE) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cutSide(SMALL_MIN, 0, SMALL_MAX, height == WallSide.TALL ? 1F : LOW_HEIGHT))
                    .export(quadMap, dir);
        }
    }

private void buildCenterPillar(QuadMapBuilder quadMap, BakedQuad quad) {
        Direction quadDir = quad.direction();
        if (center) {
            if (DirUtils.isY(quadDir)) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cutTopBottom(LARGE_MIN, LARGE_MIN, LARGE_MAX, LARGE_MAX))
                        .export(quadMap, quadDir);
            } else {
                QuadModifier.of(quad)
                        .apply(Modifiers.cutSide(LARGE_MIN, 0, LARGE_MAX, 1))
                        .apply(Modifiers.setPosition(LARGE_MAX))
                        .export(quadMap, null);
            }
        } else {
            boolean tall = north == WallSide.TALL || east == WallSide.TALL || south == WallSide.TALL || west == WallSide.TALL;

            switch (quadDir) {
                case UP, DOWN -> {
                    boolean inset = !tall && quadDir == Direction.UP;
                    QuadModifier.of(quad)
                            .apply(Modifiers.cutTopBottom(SMALL_MIN, SMALL_MIN, SMALL_MAX, SMALL_MAX))
                            .applyIf(Modifiers.setPosition(LOW_HEIGHT), inset)
                            .export(quadMap, inset ? null : quadDir);
                }
                case NORTH -> buildSmallCenterSide(quadMap, quad, north, tall);
                case EAST -> buildSmallCenterSide(quadMap, quad, east , tall);
                case SOUTH -> buildSmallCenterSide(quadMap, quad, south, tall);
                case WEST -> buildSmallCenterSide(quadMap, quad, west , tall);
            }
        }
    }

private static void buildSmallCenterSide(QuadMapBuilder quadMap, BakedQuad quad, WallSide height, boolean tall) {
        if (height == WallSide.NONE) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cutSide(SMALL_MIN, 0, SMALL_MAX, tall ? 1 : LOW_HEIGHT))
                    .apply(Modifiers.setPosition(SMALL_MAX))
                    .export(quadMap, null);
        } else if (tall && height == WallSide.LOW) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cutSide(SMALL_MIN, LOW_HEIGHT, SMALL_MAX, 1))
                    .apply(Modifiers.setPosition(SMALL_MAX))
                    .export(quadMap, null);
        }
    }

public FramedElevatedInnerPrismGeometry(GeometryFactory.Context ctx) {
        DirectionAxis dirAxis = ctx.state().getValue(PropertyHolder.FACING_AXIS);
        this.facing = dirAxis.direction();
        this.axis = dirAxis.axis();
        this.altSlope = ctx.state().getValue(FramedProperties.ALT_SLOPE);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        boolean yFacing = DirUtils.isY(facing);
        boolean yAxis = axis == Direction.Axis.Y;
        Direction quadFace = quad.direction();
        boolean quadOnFacingAxis = quadFace.getAxis() == facing.getAxis();
        boolean quadOnAxis = quadFace.getAxis() == axis;

        if (!altSlope && yFacing && !quadOnAxis && !quadOnFacingAxis) { // Slopes for Y facing without Y_SLOPE
            boolean up = facing == Direction.UP;
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(facing.getOpposite(), .5F))
                    .apply(Modifiers.makeVerticalSlope(up, 45))
                    .export(quadMap, null);
        } else if (altSlope && yFacing && quadFace == facing) { // Slopes for Y facing with Y_SLOPE
            Direction onAxis = Direction.fromAxisAndDirection(axis, Direction.AxisDirection.POSITIVE);

            Direction offAxisCW = onAxis.getClockWise();
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(offAxisCW, .5F))
                    .apply(Modifiers.makeVerticalSlope(offAxisCW, 45))
                    .export(quadMap, null);

            Direction offAxisCCW = onAxis.getCounterClockWise();
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(offAxisCCW, .5F))
                    .apply(Modifiers.makeVerticalSlope(offAxisCCW, 45))
                    .export(quadMap, null);
        } else if (!yFacing && yAxis && !quadOnAxis && quadOnFacingAxis) { // Slopes for horizontal facing and Y axis without Y_SLOPE
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(facing.getClockWise(), .5F))
                    .apply(Modifiers.makeHorizontalSlope(true, 45))
                    .export(quadMap, null);

            QuadModifier.of(quad)
                    .apply(Modifiers.cut(facing.getCounterClockWise(), .5F))
                    .apply(Modifiers.makeHorizontalSlope(false, 45))
                    .export(quadMap, null);
        } else if (!altSlope && !yFacing && !yAxis && quadFace == facing) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(Direction.UP, .5F))
                    .apply(Modifiers.makeVerticalSlope(true, 45))
                    .export(quadMap, null);

            QuadModifier.of(quad)
                    .apply(Modifiers.cut(Direction.DOWN, .5F))
                    .apply(Modifiers.makeVerticalSlope(false, 45))
                    .export(quadMap, null);
        } else if (altSlope && !yFacing && !yAxis && DirUtils.isY(quadFace)) { // Slopes for horizontal facing and Y axis with Y_SLOPE
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(facing.getOpposite(), .5F))
                    .apply(Modifiers.makeVerticalSlope(facing, 45))
                    .export(quadMap, null);
        } else if (quadOnAxis) {
            if (yAxis) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(facing.getClockWise(), .5F))
                        .apply(Modifiers.cut(facing, 0F, 1F))
                        .export(quadMap, quadFace);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(facing.getCounterClockWise(), .5F))
                        .apply(Modifiers.cut(facing, 1F, 0F))
                        .export(quadMap, quadFace);
            } else if (yFacing) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(quadFace.getClockWise(), .5F))
                        .apply(Modifiers.cut(facing, 0F, 1F))
                        .export(quadMap, quadFace);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(quadFace.getCounterClockWise(), .5F))
                        .apply(Modifiers.cut(facing, 1F, 0F))
                        .export(quadMap, quadFace);
            } else { //!yAxis && !yFacing
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(Direction.DOWN, .5F))
                        .apply(Modifiers.cut(facing, 1F, 0F))
                        .export(quadMap, quadFace);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(Direction.UP, .5F))
                        .apply(Modifiers.cut(facing, 0F, 1F))
                        .export(quadMap, quadFace);
            }
        }
    }

@Override
    public boolean transformAllQuads() {
        return altSlope || DirUtils.isY(facing) || axis == Direction.Axis.Y;
    }

public FramedElevatedInnerSlopedPrismGeometry(GeometryFactory.Context ctx) {
        CompoundDirection cmpDir = ctx.state().getValue(PropertyHolder.FACING_DIR);
        this.facing = cmpDir.direction();
        this.orientation = cmpDir.orientation();
        this.altSlope = ctx.state().getValue(FramedProperties.ALT_SLOPE);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        boolean yFacing = DirUtils.isY(facing);
        boolean yOrient = DirUtils.isY(orientation);
        Direction quadFace = quad.direction();

        if (quadFace == facing) {
            if (altSlope && yFacing) {
                boolean up = orientation == Direction.UP;

                // Tilted triangle for vertical facing with Y_SLOPE
                QuadModifier.of(quad)
                        .apply(Modifiers.cutSmallTriangle(orientation))
                        .apply(Modifiers.makeVerticalSlope(orientation, up ? -45 : 45))
                        .export(quadMap, null);

                // Side slope for vertical facing with Y_SLOPE
                Direction oriCW = orientation.getClockWise();
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(oriCW, .5F))
                        .apply(Modifiers.cut(orientation.getOpposite(), 1, 0))
                        .apply(Modifiers.makeVerticalSlope(oriCW, up ? -45 : 45))
                        .export(quadMap, null);

                // Side slope for vertical facing with Y_SLOPE
                Direction oriCCW = orientation.getCounterClockWise();
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(oriCCW, .5F))
                        .apply(Modifiers.cut(orientation.getOpposite(), 0, 1))
                        .apply(Modifiers.makeVerticalSlope(oriCCW, up ? -45 : 45))
                        .export(quadMap, null);
            } else if (!altSlope && !yFacing && yOrient) {
                // Tilted triangle for horizontal facing and vertical orientation without Y_SLOPE
                boolean up = orientation == Direction.UP;
                QuadModifier.of(quad)
                        .apply(Modifiers.cutSmallTriangle(orientation))
                        .apply(Modifiers.makeVerticalSlope(up, 45))
                        .export(quadMap, null);
            }

            if (!yFacing && !yOrient) {
                // Tilted triangle for horizontal facing and horizontal orientation
                boolean right = orientation == facing.getClockWise();
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(orientation, .5F))
                        .apply(Modifiers.cutSmallTriangle(orientation))
                        .apply(Modifiers.makeHorizontalSlope(right, 45))
                        .export(quadMap, null);

                if (!altSlope) {
                    // Side slope for horizontal facing and horizontal orientation without Y_SLOPE
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(Direction.DOWN, .5F))
                            .apply(Modifiers.cut(orientation.getOpposite(), 1, 0))
                            .apply(Modifiers.makeVerticalSlope(false, 45))
                            .export(quadMap, null);

                    // Side slope for horizontal facing and horizontal orientation without Y_SLOPE
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(Direction.UP, .5F))
                            .apply(Modifiers.cut(orientation.getOpposite(), 0, 1))
                            .apply(Modifiers.makeVerticalSlope(true, 45))
                            .export(quadMap, null);
                }
            } else if (!yFacing/* && yOrient*/) {
                // Side slope for horizontal facing and vertical orientation
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(quadFace.getClockWise(), .5F))
                        .apply(Modifiers.cut(orientation.getOpposite(), 0, 1))
                        .apply(Modifiers.makeHorizontalSlope(true, 45))
                        .export(quadMap, null);

                // Side slope for horizontal facing and vertical orientation
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(quadFace.getCounterClockWise(), .5F))
                        .apply(Modifiers.cut(orientation.getOpposite(), 1, 0))
                        .apply(Modifiers.makeHorizontalSlope(false, 45))
                        .export(quadMap, null);
            }
        } else if (quadFace == orientation) {
            if (yOrient) {
                // Front face for horizontal facing and vertical orientation
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(facing.getClockWise(), .5F))
                        .apply(Modifiers.cut(facing, 0F, 1F))
                        .export(quadMap, quadFace);

                // Front face for horizontal facing and vertical orientation
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(facing.getCounterClockWise(), .5F))
                        .apply(Modifiers.cut(facing, 1F, 0F))
                        .export(quadMap, quadFace);

                if (altSlope) {
                    // Tilted triangle for horizontal facing and vertical orientation with Y_SLOPE
                    QuadModifier.of(quad)
                            .apply(Modifiers.cutSmallTriangle(facing.getOpposite()))
                            .apply(Modifiers.makeVerticalSlope(facing, 45))
                            .export(quadMap, null);
                }
            } else if (yFacing) {
                // Front face for vertical facing
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(quadFace.getClockWise(), .5F))
                        .apply(Modifiers.cut(facing, 0F, 1F))
                        .export(quadMap, quadFace);

                // Front face for vertical facing
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(quadFace.getCounterClockWise(), .5F))
                        .apply(Modifiers.cut(facing, 1F, 0F))
                        .export(quadMap, quadFace);

                if (!altSlope) {
                    // Tilted triangle for vertical facing without Y_SLOPE
                    boolean up = facing == Direction.UP;
                    QuadModifier.of(quad)
                            .apply(Modifiers.cutSmallTriangle(facing.getOpposite()))
                            .apply(Modifiers.makeVerticalSlope(up, 45))
                            .export(quadMap, null);
                }
            } else { //!yOrient && !yFacing
                // Front face for horizontal facing and horizontal orientation
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(Direction.DOWN, .5F))
                        .apply(Modifiers.cut(facing, 1F, 0F))
                        .export(quadMap, quadFace);

                // Front face for horizontal facing and horizontal orientation
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(Direction.UP, .5F))
                        .apply(Modifiers.cut(facing, 0F, 1F))
                        .export(quadMap, quadFace);
            }
        } else if (quadFace.getAxis() != orientation.getAxis() && quadFace.getAxis() != facing.getAxis()) {
            if (altSlope && !yFacing && !yOrient) {
                // Side slope for horizontal facing and horizontal orientation with Y_SLOPE
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(facing.getOpposite(), .5F))
                        .apply(Modifiers.cut(orientation.getOpposite(), 1, 0))
                        .apply(Modifiers.makeVerticalSlope(facing, 45))
                        .export(quadMap, null);

                // Side slope for horizontal facing and horizontal orientation with Y_SLOPE
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(facing.getOpposite(), .5F))
                        .apply(Modifiers.cut(orientation.getOpposite(), 0, 1))
                        .apply(Modifiers.makeVerticalSlope(facing, 45))
                        .export(quadMap, null);
            } else if (!altSlope && yFacing) {
                // Side slope for vertical facing without Y_SLOPE
                boolean up = facing == Direction.UP;
                float top = up ? 1 : 0;
                float bottom = up ? 0 : 1;
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(facing.getOpposite(), .5F))
                        .apply(Modifiers.cut(orientation.getOpposite(), top, bottom))
                        .apply(Modifiers.makeVerticalSlope(up, 45))
                        .export(quadMap, null);
            }
        }
    }

@Override
    public boolean transformAllQuads() {
        return altSlope || DirUtils.isY(facing) || DirUtils.isY(orientation);
    }

public FramedPrismGeometry(GeometryFactory.Context ctx) {
        DirectionAxis dirAxis = ctx.state().getValue(PropertyHolder.FACING_AXIS);
        this.facing = dirAxis.direction();
        this.axis = dirAxis.axis();
        this.altSlope = ctx.state().getValue(FramedProperties.ALT_SLOPE);
    }

@Override public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        boolean yFacing = DirUtils.isY(facing);
        boolean yAxis = axis == Direction.Axis.Y;
        Direction quadFace = quad.direction();
        boolean quadOnAxis = quadFace.getAxis() == axis;
        boolean quadOnFacingAxis = quadFace.getAxis() == facing.getAxis();

        if (!altSlope && yFacing && !quadOnAxis && !quadOnFacingAxis) { // Slopes for Y facing without Y_SLOPE
            boolean up = facing == Direction.UP;
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(facing, .5F))
                    .apply(Modifiers.makeVerticalSlope(up, 45))
                    .export(quadMap, null);
        } else if (altSlope && yFacing && DirUtils.isY(quadFace)) { // Slopes for Y facing with Y_SLOPE
            Direction onAxis = Direction.fromAxisAndDirection(axis, Direction.AxisDirection.POSITIVE);
            Direction offAxisCW = onAxis.getClockWise();
            Direction offAxisCCW = onAxis.getCounterClockWise();

            QuadModifier.of(quad)
                    .apply(Modifiers.cut(offAxisCW, .5F))
                    .apply(Modifiers.makeVerticalSlope(offAxisCCW, 45))
                    .export(quadMap, null);

            QuadModifier.of(quad)
                    .apply(Modifiers.cut(offAxisCCW, .5F))
                    .apply(Modifiers.makeVerticalSlope(offAxisCW, 45))
                    .export(quadMap, null);
        } else if (!yFacing && yAxis && !quadOnAxis && !quadOnFacingAxis) { // Slopes for horizontal facing and vertical axis
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(facing, .5F))
                    .apply(Modifiers.makeHorizontalSlope(quadFace == facing.getCounterClockWise(), 45))
                    .export(quadMap, null);
        } else if (!altSlope && !yFacing && !yAxis && quadFace == facing) { // Slopes for horizontal facing and horizontal axis without Y_SLOPE
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(Direction.UP, .5F))
                    .apply(Modifiers.makeVerticalSlope(false, 45))
                    .export(quadMap, null);

            QuadModifier.of(quad)
                    .apply(Modifiers.cut(Direction.DOWN, .5F))
                    .apply(Modifiers.makeVerticalSlope(true, 45))
                    .export(quadMap, null);
        } else if (altSlope && !yFacing && !yAxis && DirUtils.isY(quadFace)) { // Slopes for horizontal facing and horizontal axis with Y_SLOPE
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(facing, .5F))
                    .apply(Modifiers.makeVerticalSlope(facing, 45))
                    .export(quadMap, null);
        } else if (quadFace.getAxis() == axis) { // Triangles
            QuadModifier.of(quad)
                    .apply(Modifiers.cutSmallTriangle(facing))
                    .export(quadMap, quadFace);
        }
    }

public FramedSlopedPrismGeometry(GeometryFactory.Context ctx) {
        CompoundDirection cmpDir = ctx.state().getValue(PropertyHolder.FACING_DIR);
        this.facing = cmpDir.direction();
        this.orientation = cmpDir.orientation();
        this.altSlope = ctx.state().getValue(FramedProperties.ALT_SLOPE);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        boolean yFacing = DirUtils.isY(facing);
        boolean yOrient = DirUtils.isY(orientation);
        Direction orientOpp = orientation.getOpposite();
        Direction quadFace = quad.direction();

        if (quadFace == orientOpp && !yOrient) {
            if (!yFacing) { // Triangle for horizontal facing and horizontal orientation
                QuadModifier.of(quad)
                        .apply(Modifiers.cutSmallTriangle(facing))
                        .apply(Modifiers.makeHorizontalSlope(orientation == facing.getClockWise(), 45))
                        .export(quadMap, null);
            } else if (!altSlope) { // Triangle for horizontal facing and vertical orientation without Y_SLOPE
                QuadModifier.of(quad)
                        .apply(Modifiers.cutSmallTriangle(facing))
                        .apply(Modifiers.makeVerticalSlope(facing == Direction.UP, 45))
                        .export(quadMap, null);
            }
        } else if (altSlope && yFacing && DirUtils.isY(quadFace)) { // Triangle and slopes for vertical facing with Y_SLOPE
            QuadModifier.of(quad)
                    .apply(Modifiers.cutSmallTriangle(orientation))
                    .apply(Modifiers.makeVerticalSlope(orientOpp, 45))
                    .export(quadMap, null);

            Direction offAxisCW = orientation.getClockWise();
            Direction offAxisCCW = orientation.getCounterClockWise();

            QuadModifier.of(quad)
                    .apply(Modifiers.cut(offAxisCW, .5F))
                    .apply(Modifiers.cut(orientOpp, 1, 0))
                    .apply(Modifiers.makeVerticalSlope(offAxisCCW, 45))
                    .export(quadMap, null);

            QuadModifier.of(quad)
                    .apply(Modifiers.cut(offAxisCCW, .5F))
                    .apply(Modifiers.cut(orientOpp, 0, 1))
                    .apply(Modifiers.makeVerticalSlope(offAxisCW, 45))
                    .export(quadMap, null);
        } else if (!altSlope && yOrient && quadFace == facing) { // Tilted triangle for horizontal facing and vertical orientation without Y_SLOPE
            QuadModifier.of(quad)
                    .apply(Modifiers.cutSmallTriangle(orientation))
                    .apply(Modifiers.makeVerticalSlope(orientation == Direction.DOWN, 45))
                    .export(quadMap, null);
        } else if (altSlope && yOrient && quadFace == orientOpp) { // Tilted triangle for horizontal facing and vertical orientation with Y_SLOPE
            QuadModifier.of(quad)
                    .apply(Modifiers.cutSmallTriangle(facing))
                    .apply(Modifiers.makeVerticalSlope(facing, 45))
                    .export(quadMap, null);
        } else if (quadFace == orientation) { // Triangle
            QuadModifier.of(quad)
                    .apply(Modifiers.cutSmallTriangle(facing))
                    .export(quadMap, quadFace);
        } else if (!altSlope && yFacing && quadFace.getAxis() == orientation.getClockWise().getAxis()) { // Slopes for Y facing without Y_SLOPE
            boolean up = facing == Direction.UP;
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(facing, .5F))
                    .apply(Modifiers.cut(orientation.getOpposite(), up ? 0 : 1, up ? 1 : 0))
                    .apply(Modifiers.makeVerticalSlope(up, 45))
                    .export(quadMap, null);
        } else if (yOrient && quadFace.getAxis() == facing.getClockWise().getAxis()) { // Slopes for horizontal facing and vertical orientation
            boolean right = quadFace == facing.getClockWise();
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(facing, .5F))
                    .apply(Modifiers.cut(orientation.getOpposite(), right ? 1 : 0, right ? 0 : 1))
                    .apply(Modifiers.makeHorizontalSlope(quadFace == facing.getCounterClockWise(), 45))
                    .export(quadMap, null);
        } else if (!altSlope && !yOrient && !yFacing && quadFace == facing) { // Slopes for horizontal facing and horizontal orientation without Y_SLOPE
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(Direction.UP, .5F))
                    .apply(Modifiers.cut(orientation.getOpposite(), 0, 1))
                    .apply(Modifiers.makeVerticalSlope(false, 45))
                    .export(quadMap, null);

            QuadModifier.of(quad)
                    .apply(Modifiers.cut(Direction.DOWN, .5F))
                    .apply(Modifiers.cut(orientation.getOpposite(), 1, 0))
                    .apply(Modifiers.makeVerticalSlope(true, 45))
                    .export(quadMap, null);
        } else if (altSlope && !yOrient && !yFacing && DirUtils.isY(quadFace)) { // Slopes for horizontal facing and horizontal orientation with Y_SLOPE
            boolean right = orientation == facing.getClockWise();
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(facing, .5F))
                    .apply(Modifiers.cut(orientOpp, right ? 0 : 1, right ? 1 : 0))
                    .apply(Modifiers.makeVerticalSlope(facing, 45))
                    .export(quadMap, null);
        }
    }

private FramedFancyRailGeometry(GeometryFactory.Context ctx, Property<RailShape> shapeProperty, BlockState auxShaderState) {
        this.state = ctx.state();
        this.baseModel = ctx.baseModel();
        this.auxShaderState = auxShaderState;
        this.shape = ctx.state().getValue(shapeProperty);
        this.mainDir = getDirectionFromRailShape(shape);
        this.secDir = getSecondaryDirectionFromRailShape(shape);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        if (shape.isSlope()) {
            makeAscendingRailSleepers(quadMap, quad, mainDir);
        } else if (shape == RailShape.NORTH_SOUTH || shape == RailShape.EAST_WEST) {
            makeStraightRailSleepers(quadMap, quad, mainDir, Modifiers.noop(), UnaryOperator.identity());
        } else {
            makeCurvedRailSleepers(quadMap, quad, mainDir, Objects.requireNonNull(secDir));
        }
    }

private static void makeStraightRailSleepers(QuadMapBuilder quadMap, BakedQuad quad, Direction dir, QuadModifier.Modifier lastMod, UnaryOperator<@Nullable Direction> cullFaceMod) {
        Direction quadDir = quad.direction();
        if (DirUtils.isY(quadDir)) {
            Direction targetDir = cullFaceMod.apply(quadDir == Direction.UP ? null : quadDir);
            forAllSleepers((_, distDir, distOpp) ->
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir, distDir))
                            .apply(Modifiers.cut(dir.getOpposite(), distOpp))
                            .applyIf(Modifiers.setPosition(SLEEPER_HEIGHT), quadDir == Direction.UP)
                            .apply(lastMod)
                            .export(quadMap, targetDir)
            );
        } else if (quadDir.getAxis() == dir.getAxis()) {
            forAllSleepers((_, distDir, _) ->
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(Direction.UP, SLEEPER_HEIGHT))
                            .apply(Modifiers.setPosition(distDir))
                            .apply(lastMod)
                            .export(quadMap, null)
            );
        } else {
            Direction targetDir = cullFaceMod.apply(quadDir);
            forAllSleepers((_, distDir, distOpp) ->
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(Direction.UP, SLEEPER_HEIGHT))
                            .apply(Modifiers.cut(dir, distDir))
                            .apply(Modifiers.cut(dir.getOpposite(), distOpp))
                            .apply(lastMod)
                            .export(quadMap, targetDir)
            );
        }
    }

private static void makeAscendingRailSleepers(QuadMapBuilder quadMap, BakedQuad quad, Direction dir) {
        Direction.Axis axis = dir.getClockWise().getAxis();
        Vector3f origin = SLOPE_ORIGINS[dir.get2DDataValue()];
        float angle = DirUtils.isPositive(dir) == DirUtils.isX(dir) ? 45F : -45F;
        Vector3f scaleVec = DirUtils.isX(dir) ? SCALE_X : SCALE_Z;

        makeStraightRailSleepers(quadMap, quad, dir, Modifiers.rotate(axis, origin, angle, true, scaleVec), cullFace -> cullFace == Direction.DOWN ? null : cullFace);
    }

private static void makeCurvedRailSleepers(QuadMapBuilder quadMap, BakedQuad quad, Direction dir, Direction secDir) {
        Direction quadDir = quad.direction();
        if (DirUtils.isY(quadDir)) {
            Direction targetDir = quadDir == Direction.UP ? null : quadDir;
            forAllSleepersCurve((i, distDir, distOpp) -> {
                boolean nonDiagUp = quadDir == Direction.UP && i != 1;
                float height = nonDiagUp ? (SLEEPER_HEIGHT - .001F) : SLEEPER_HEIGHT;
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir, distDir))
                        .apply(Modifiers.cut(dir.getOpposite(), distOpp))
                        .applyIf(Modifiers.setPosition(height), quadDir == Direction.UP)
                        .applyIf(rotateCurveSleeper(dir, secDir, i), i < 2)
                        .applyIf(Modifiers.offset(dir, SLEEPER_DIAGONAL_OFFSET), i == 1)
                        .applyIf(Modifiers.offset(secDir, SLEEPER_DIAGONAL_OFFSET), i == 1)
                        .export(quadMap, targetDir);
            });
        } else if (quadDir.getAxis() == dir.getAxis()) {
            boolean inDir = quadDir == dir;
            forAllSleepersCurve((i, distDir, distOpp) ->
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(Direction.UP, SLEEPER_HEIGHT))
                            .apply(Modifiers.setPosition(inDir ? distDir : distOpp))
                            .applyIf(rotateCurveSleeper(dir, secDir, i), i < 2)
                            .applyIf(Modifiers.offset(dir, SLEEPER_DIAGONAL_OFFSET), i == 1)
                            .applyIf(Modifiers.offset(secDir, SLEEPER_DIAGONAL_OFFSET), i == 1)
                            .export(quadMap, null)
            );
        } else {
            forAllSleepersCurve((i, distDir, distOpp) ->
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(Direction.UP, SLEEPER_HEIGHT))
                            .apply(Modifiers.cut(dir, distDir))
                            .apply(Modifiers.cut(dir.getOpposite(), distOpp))
                            .applyIf(rotateCurveSleeper(dir, secDir, i), i < 2)
                            .applyIf(Modifiers.offset(dir, SLEEPER_DIAGONAL_OFFSET), i == 1)
                            .applyIf(Modifiers.offset(secDir, SLEEPER_DIAGONAL_OFFSET), i == 1)
                            .export(quadMap, quadDir)
            );
        }
    }

private static QuadModifier.Modifier rotateCurveSleeper(Direction dir, Direction secDir, int i) {
        float angle = 45F * (SLEEPER_COUNT_CURVE - 1 - i);
        if (secDir == dir.getCounterClockWise()) {
            angle *= -1F;
        }
        return Modifiers.rotateCentered(Direction.Axis.Y, angle, false);
    }

private static void forAllSleepers(SleeperConsumer consumer) {
        for (int i = 0; i < SLEEPER_COUNT; i++) {
            float distDir = SLEEPER_BASE_OFFSET + (i * SLEEPER_DIST) + SLEEPER_WIDTH;
            float distOpp = 1F - distDir + SLEEPER_WIDTH;
            consumer.accept(i, distDir, distOpp);
        }
    }

private static void forAllSleepersCurve(SleeperConsumer consumer) {
        for (int i = 0; i < SLEEPER_COUNT_CURVE; i++) {
            float distDir = SLEEPER_BASE_OFFSET + (i * SLEEPER_DIST_CURVE) + SLEEPER_WIDTH;
            float distOpp = 1F - distDir + SLEEPER_WIDTH;
            consumer.accept(i, distDir, distOpp);
        }
    }

