private static @Nullable Direction getSecondaryDirectionFromRailShape(RailShape shape) {
        return switch (shape) {
            case NORTH_EAST, SOUTH_EAST -> Direction.EAST;
            case NORTH_WEST, SOUTH_WEST -> Direction.WEST;
