    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        if (type.isHorizontal()) {
            createHorizontalCornerSlope(quadMap, quad);
        } else {
            createVerticalCornerSlope(quadMap, quad);
        }
    }

private void createHorizontalCornerSlope(QuadMapBuilder quadMap, BakedQuad quad) {
        Direction quadDir = quad.direction();
        boolean top = type.isTop();
        boolean right = type.isRight();

        if ((quadDir == dir.getClockWise() && right) || (quadDir == dir.getCounterClockWise() && !right)) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir.getOpposite(), top ? 1 : 0, top ? 0 : 1))
                    .export(quadMap, quadDir);
        } else if ((quadDir == Direction.UP && top) || (quadDir == Direction.DOWN && !top)) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir.getOpposite(), right ? 0 : 1, right ? 1 : 0))
                    .export(quadMap, quadDir);
        } else if ((quadDir == dir.getCounterClockWise() && right) || (quadDir == dir.getClockWise() && !right)) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir.getOpposite(), top ? 1 : 0, top ? 0 : 1))
                    .apply(Modifiers.makeHorizontalSlope(!right, 45))
                    .export(quadMap, null);
        } else if (!altSlope && quadDir == dir.getOpposite()) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(top ? Direction.UP : Direction.DOWN, right ? 0 : 1, right ? 1 : 0))
                    .apply(Modifiers.makeVerticalSlope(!top, 45))
                    .export(quadMap, null);
        } else if (altSlope && ((!top && quadDir == Direction.UP) || (top && quadDir == Direction.DOWN))) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir.getOpposite(), right ? 0 : 1, right ? 1 : 0))
                    .apply(Modifiers.makeVerticalSlope(dir.getOpposite(), 45))
                    .export(quadMap, null);
        }
    }

private void createVerticalCornerSlope(QuadMapBuilder quadMap, BakedQuad quad) {
        Direction quadDir = quad.direction();
        boolean yQuad = DirUtils.isY(quadDir);
        if (!altSlope && yQuad) {
            return;
        }

        boolean top = type.isTop();
        Direction cutDir = quadDir.getAxis() == dir.getAxis() ? dir.getClockWise() : dir.getOpposite();
        boolean slope = quadDir == dir.getOpposite() || quadDir == dir.getClockWise();

        if ((!slope && !yQuad) || !altSlope) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(cutDir, top ? 1 : 0, top ? 0 : 1))
                    .applyIf(Modifiers.makeVerticalSlope(!top, 45), slope)
                    .export(quadMap, slope ? null : quadDir);
        } else if (yQuad) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir.getOpposite(), 0, 1))
                    .apply(Modifiers.makeVerticalSlope(dir.getClockWise(), 45))
                    .export(quadMap, null);

            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir.getClockWise(), 1, 0))
                    .apply(Modifiers.makeVerticalSlope(dir.getOpposite(), 45))
                    .export(quadMap, null);
        }
    }

public FramedElevatedPyramidSlabGeometry(GeometryFactory.Context ctx) {
        super(ctx);
    }

@Override
    protected void buildBody(QuadMapBuilder quadMap, BakedQuad quad, Direction quadDir) {
        if (DirUtils.isY(facing)) {
            boolean up = facing == Direction.UP;
            if (!altSlope && quadDir.getAxis() != facing.getAxis()) {
                QuadModifier.of(quad)
                        .applyIf(Modifiers.cut(facing, slopeHeight), hasPillar)
                        .apply(Modifiers.cut(facing.getOpposite(), .5F))
                        .apply(Modifiers.cut(quadDir.getCounterClockWise(), up ? .5F : 1.5F, up ? 1.5F : .5F))
                        .apply(Modifiers.cut(quadDir.getClockWise(), up ? .5F : 1.5F, up ? 1.5F : .5F))
                        .apply(Modifiers.makeVerticalSlope(up, 45))
                        .apply(Modifiers.offset(quadDir, .5F))
                        .export(quadMap, null);
            } else if (altSlope && quadDir == facing) {
                for (Direction dir : Direction.Plane.HORIZONTAL) {
                    boolean northeast = dir == Direction.NORTH || dir == Direction.EAST;
                    float angle = up ? -45 : 45;
                    if (northeast) {
                        angle *= -1F;
                    }
                    QuadModifier.of(quad)
                            .applyIf(Modifiers.cut(dir, slopeHeight), hasPillar)
                            .apply(Modifiers.cut(dir.getOpposite(), .5F))
                            .apply(Modifiers.cut(dir.getCounterClockWise(), .5F, 1.5F))
                            .apply(Modifiers.cut(dir.getClockWise(), 1.5F, .5F))
                            .apply(Modifiers.rotateCentered(dir.getClockWise().getAxis(), angle, true))
                            .apply(Modifiers.offset(facing.getOpposite(), .5F))
                            .export(quadMap, null);
                }
            }
            if (quadDir.getAxis() != facing.getAxis()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(facing, .5F))
                        .export(quadMap, quadDir);
            }
        } else {
            if (!altSlope && quadDir.getAxis() == facing.getAxis()) {
                QuadModifier.of(quad)
                        .applyIf(Modifiers.cut(Direction.DOWN, slopeHeight), hasPillar)
                        .apply(Modifiers.cut(Direction.UP, .5F))
                        .apply(Modifiers.cut(facing.getClockWise(), 1.5F, .5F))
                        .apply(Modifiers.cut(facing.getCounterClockWise(), 1.5F, .5F))
                        .apply(Modifiers.makeVerticalSlope(true, 45))
                        .apply(Modifiers.offset(Direction.UP, .5F))
                        .export(quadMap, null);

                QuadModifier.of(quad)
                        .applyIf(Modifiers.cut(Direction.UP, slopeHeight), hasPillar)
                        .apply(Modifiers.cut(Direction.DOWN, .5F))
                        .apply(Modifiers.cut(facing.getClockWise(), .5F, 1.5F))
                        .apply(Modifiers.cut(facing.getCounterClockWise(), .5F, 1.5F))
                        .apply(Modifiers.makeVerticalSlope(false, 45))
                        .apply(Modifiers.offset(Direction.DOWN, .5F))
                        .export(quadMap, null);
            } else if (altSlope && DirUtils.isY(quadDir)) {
                boolean up = quadDir == Direction.UP;

                float angle = up ? 45 : -45;
                if (facing == Direction.NORTH || facing == Direction.EAST) {
                    angle *= -1F;
                }

                Vector3f origin = facing.getOpposite().step().max(ZERO);
                if (up) {
                    origin.add(0, 1, 0);
                }

                QuadModifier.of(quad)
                        .applyIf(Modifiers.cut(facing, slopeHeight), hasPillar)
                        .apply(Modifiers.cut(facing.getOpposite(), .5F))
                        .apply(Modifiers.cut(facing.getCounterClockWise(), .5F, 1.5F))
                        .apply(Modifiers.cut(facing.getClockWise(), 1.5F, .5F))
                        .apply(Modifiers.rotate(facing.getClockWise().getAxis(), origin, angle, true))
                        .apply(Modifiers.offset(quadDir, .5F))
                        .export(quadMap, null);
            } else if (quadDir.getAxis() == facing.getClockWise().getAxis()) {
                boolean right = quadDir == facing.getClockWise();
                QuadModifier.of(quad)
                        .applyIf(Modifiers.cut(facing, slopeHeight), hasPillar)
                        .apply(Modifiers.cut(facing.getOpposite(), .5F))
                        .apply(Modifiers.cut(Direction.DOWN, right ? 1.5F : .5F, right ? .5F : 1.5F))
                        .apply(Modifiers.cut(Direction.UP, right ? 1.5F : .5F, right ? .5F : 1.5F))
                        .apply(Modifiers.makeHorizontalSlope(!right, 45))
                        .apply(Modifiers.offset(quadDir, .5F))
                        .export(quadMap, null);
            }
            if (DirUtils.isY(quadDir)) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(facing, .5F))
                        .export(quadMap, quadDir);
            } else if (quadDir.getAxis() != facing.getAxis()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(facing, .5F))
                        .export(quadMap, quadDir);
            }
        }
    }

@Override
    protected float computeSlopeHeight(PillarConnection pillar) {
        return switch (pillar) {
            case NONE -> 1F;
            case POST -> 14F/16F;
            case PILLAR -> 12F/16F;
        };
    }

@Override
    protected float computePillarHeight(PillarConnection pillar) {
        return switch (pillar) {
            case NONE -> 0F;
            case POST -> 2F/16F;
            case PILLAR -> 4F/16F;
        };
    }

public FramedHalfSlopeGeometry(GeometryFactory.Context ctx) {
        this.dir = ctx.state().getValue(FramedProperties.FACING_HOR);
        this.top = ctx.state().getValue(FramedProperties.TOP);
        this.right = ctx.state().getValue(PropertyHolder.RIGHT);
        this.altSlope = ctx.state().getValue(FramedProperties.ALT_SLOPE);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        Direction quadDir = quad.direction();

        Direction cutDir = right ? dir.getCounterClockWise() : dir.getClockWise();

        if (!altSlope && quadDir == dir.getOpposite()) {
            QuadModifier.of(quad)
                    .apply(Modifiers.makeVerticalSlope(!top, 45))
                    .apply(Modifiers.cut(cutDir, .5F))
                    .export(quadMap, null);
        } else if (altSlope && ((!top && quadDir == Direction.UP) || (top && quadDir == Direction.DOWN))) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(cutDir, .5F))
                    .apply(Modifiers.makeVerticalSlope(dir.getOpposite(), 45))
                    .export(quadMap, null);
        } else if (quadDir == dir.getClockWise() || quadDir == dir.getCounterClockWise()) {
            boolean needOffset = right == (quadDir == dir.getCounterClockWise());

            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir.getOpposite(), top ? 1 : 0, top ? 0 : 1))
                    .applyIf(Modifiers.setPosition(.5F), needOffset)
                    .export(quadMap, needOffset ? null : quadDir);
        } else if ((!top && quadDir == Direction.DOWN) || (top && quadDir == Direction.UP)) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(cutDir, .5F))
                    .export(quadMap, quadDir);
        } else if (quadDir == dir) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(cutDir, .5F))
                    .export(quadMap, quadDir);
        }
    }

public FramedInnerCornerSlopeGeometry(GeometryFactory.Context ctx) {
        this.dir = ctx.state().getValue(FramedProperties.FACING_HOR);
        this.type = ctx.state().getValue(PropertyHolder.CORNER_TYPE);
        this.altSlope = ctx.state().getValue(FramedProperties.ALT_SLOPE);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        if (type.isHorizontal()) {
            createHorizontalCorner(quadMap, quad);
        } else {
            createVerticalCorner(quadMap, quad);
        }
    }

private void createHorizontalCorner(QuadMapBuilder quadMap, BakedQuad quad) {
        Direction quadDir = quad.direction();
        boolean top = type.isTop();
        boolean right = type.isRight();

        if ((quadDir == Direction.UP && !top) || (quadDir == Direction.DOWN && top)) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir.getOpposite(), right ? 0 : 1, right ? 1 : 0))
                    .export(quadMap, quadDir);

            if (altSlope) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir, right ? 0 : 1, right ? 1 : 0))
                        .apply(Modifiers.makeVerticalSlope(dir.getOpposite(), 45))
                        .export(quadMap, null);
            }
        } else if (quadDir == dir.getOpposite()) {
            Direction cutDir = right ? dir.getCounterClockWise() : dir.getClockWise();
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(cutDir, top ? 0 : 1, top ? 1 : 0))
                    .apply(Modifiers.makeHorizontalSlope(right, 45))
                    .export(quadMap, null);

            if (!altSlope) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(top ? Direction.DOWN : Direction.UP, right ? 1 : 0, right ? 0 : 1))
                        .apply(Modifiers.makeVerticalSlope(!top, 45))
                        .export(quadMap, null);
            }
        } else if ((quadDir == dir.getClockWise() && !right) || (quadDir == dir.getCounterClockWise() && right)) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir.getOpposite(), top ? 1 : 0, top ? 0 : 1))
                    .export(quadMap, quadDir);
        }
    }

private void createVerticalCorner(QuadMapBuilder quadMap, BakedQuad quad) {
        Direction quadDir = quad.direction();
        boolean top = type.isTop();

        if (quadDir == dir.getClockWise()) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir.getOpposite(), top ? 1 : 0, top ? 0 : 1))
                    .export(quadMap, quadDir);

            if (!altSlope) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir, top ? 0 : 1, top ? 1 : 0))
                        .apply(Modifiers.makeVerticalSlope(!top, 45))
                        .export(quadMap, null);
            }
        } else if (quadDir == dir.getOpposite()) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir.getClockWise(), top ? 1 : 0, top ? 0 : 1))
                    .export(quadMap, quadDir);

            if (!altSlope) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getCounterClockWise(), top ? 0 : 1, top ? 1 : 0))
                        .apply(Modifiers.makeVerticalSlope(!top, 45))
                        .export(quadMap, null);
            }
        } else if (altSlope && ((!top && quadDir == Direction.UP) || (top && quadDir == Direction.DOWN))) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir.getClockWise(), 1, 0))
                    .apply(Modifiers.makeVerticalSlope(dir.getClockWise(), 45))
                    .export(quadMap, null);

            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir.getOpposite(), 0, 1))
                    .apply(Modifiers.makeVerticalSlope(dir.getOpposite(), 45))
                    .export(quadMap, null);
        }
    }

public FramedInnerPrismCornerGeometry(GeometryFactory.Context ctx) {
        this.dir = ctx.state().getValue(FramedProperties.FACING_HOR);
        this.top = ctx.state().getValue(FramedProperties.TOP);
        this.offset = ctx.state().getValue(FramedProperties.OFFSET);
        this.altSlope = ctx.state().getValue(FramedProperties.ALT_SLOPE);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        Direction quadDir = quad.direction();
        if ((quadDir == Direction.DOWN && top) || (quadDir == Direction.UP && !top)) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir.getOpposite(), 1, 0))
                    .export(quadMap, quadDir);
        } else if (quadDir == dir.getOpposite() || quadDir == dir.getClockWise()) {
            Direction cutDir = quadDir == dir.getOpposite() ? dir.getClockWise() : dir.getOpposite();
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(cutDir, top ? 1 : 0, top ? 0 : 1))
                    .export(quadMap, quadDir);
        }

        if (!altSlope && quadDir == dir.getOpposite())  {
            if (offset) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getClockWise(), .5F))
                        .apply(Modifiers.offset(dir.getClockWise(), .5F))
                        .apply(Modifiers.cutPrismTriangle(top, false))
                        .export(quadMap, null);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                        .apply(Modifiers.offset(dir.getCounterClockWise(), .5F))
                        .apply(Modifiers.cutPrismTriangle(top, false))
                        .export(quadMap, null);
            } else {
                QuadModifier.of(quad)
                        .apply(Modifiers.cutPrismTriangle(top, false))
                        .export(quadMap, null);
            }
        } else if (altSlope && ((!top && quadDir == Direction.UP) || (top && quadDir == Direction.DOWN))) {
            if (offset) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getClockWise(), .5F))
                        .apply(Modifiers.offset(dir.getClockWise(), .5F))
                        .apply(Modifiers.cutPrismTriangle(dir.getOpposite(), false))
                        .export(quadMap, null);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                        .apply(Modifiers.offset(dir.getCounterClockWise(), .5F))
                        .apply(Modifiers.cutPrismTriangle(dir.getOpposite(), false))
                        .export(quadMap, null);
            } else {
                QuadModifier.of(quad)
                        .apply(Modifiers.cutPrismTriangle(dir.getOpposite(), false))
                        .export(quadMap, null);
            }
        }
    }

public FramedInnerThreewayCornerGeometry(GeometryFactory.Context ctx) {
        this.dir = ctx.state().getValue(FramedProperties.FACING_HOR);
        this.top = ctx.state().getValue(FramedProperties.TOP);
        this.altSlope = ctx.state().getValue(FramedProperties.ALT_SLOPE);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        Direction quadDir = quad.direction();
        if ((quadDir == Direction.DOWN && top) || (quadDir == Direction.UP && !top)) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir.getOpposite(), 1, 0))
                    .export(quadMap, quadDir);
        } else if (quadDir == dir.getClockWise() || quadDir == dir.getOpposite()) {
            Direction cutDir = quadDir == dir.getOpposite() ? dir.getClockWise() : dir.getOpposite();
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(cutDir, top ? 1 : 0, top ? 0 : 1))
                    .export(quadMap, quadDir);
        }

        if (quadDir == dir.getClockWise()) {
            if (!altSlope) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cutSmallTriangle(dir))
                        .apply(Modifiers.makeVerticalSlope(!top, 45))
                        .export(quadMap, null);
            }

            QuadModifier.of(quad)
                    .apply(Modifiers.cutSmallTriangle(top ? Direction.UP : Direction.DOWN))
                    .apply(Modifiers.makeHorizontalSlope(true, 45))
                    .export(quadMap, null);
        } else if (!altSlope && quadDir == dir.getOpposite()) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cutSmallTriangle(dir.getCounterClockWise()))
                    .apply(Modifiers.makeVerticalSlope(!top, 45))
                    .export(quadMap, null);
        } else if (altSlope && ((!top && quadDir == Direction.UP) || (top && quadDir == Direction.DOWN))) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cutSmallTriangle(dir))
                    .apply(Modifiers.makeVerticalSlope(dir.getClockWise(), 45))
                    .export(quadMap, null);

            QuadModifier.of(quad)
                    .apply(Modifiers.cutSmallTriangle(dir.getCounterClockWise()))
                    .apply(Modifiers.makeVerticalSlope(dir.getOpposite(), 45))
                    .export(quadMap, null);
        }
    }

public FramedPrismCornerGeometry(GeometryFactory.Context ctx) {
        this.dir = ctx.state().getValue(FramedProperties.FACING_HOR);
        this.top = ctx.state().getValue(FramedProperties.TOP);
        this.offset = ctx.state().getValue(FramedProperties.OFFSET);
        this.altSlope = ctx.state().getValue(FramedProperties.ALT_SLOPE);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        Direction quadDir = quad.direction();
        if ((quadDir == Direction.UP && top) || (quadDir == Direction.DOWN && !top)) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir.getOpposite(), 1, 0))
                    .export(quadMap, quadDir);
        } else if (quadDir == dir || quadDir == dir.getCounterClockWise()) {
            Direction cutDir = quadDir == dir ? dir.getClockWise() : dir.getOpposite();
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(cutDir, top ? 1 : 0, top ? 0 : 1))
                    .export(quadMap, quadDir);
        } else if (!altSlope && quadDir == dir.getOpposite()) {
            if (offset) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getClockWise(), .5F))
                        .apply(Modifiers.offset(dir.getClockWise(), .5F))
                        .apply(Modifiers.cutPrismTriangle(!top, true))
                        .export(quadMap, null);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                        .apply(Modifiers.offset(dir.getCounterClockWise(), .5F))
                        .apply(Modifiers.cutPrismTriangle(!top, true))
                        .export(quadMap, null);
            } else {
                QuadModifier.of(quad)
                        .apply(Modifiers.cutPrismTriangle(!top, true))
                        .export(quadMap, null);
            }
        } else if (altSlope && ((!top && quadDir == Direction.UP) || (top && quadDir == Direction.DOWN))) {
            if (offset) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getClockWise(), .5F))
                        .apply(Modifiers.offset(dir.getClockWise(), .5F))
                        .apply(Modifiers.cutPrismTriangle(dir, true))
                        .export(quadMap, null);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                        .apply(Modifiers.offset(dir.getCounterClockWise(), .5F))
                        .apply(Modifiers.cutPrismTriangle(dir, true))
                        .export(quadMap, null);
            } else {
                QuadModifier.of(quad)
                        .apply(Modifiers.cutPrismTriangle(dir, true))
                        .export(quadMap, null);
            }
        }
    }

public FramedPyramidGeometry(GeometryFactory.Context ctx) {
        this.facing = ctx.state().getValue(BlockStateProperties.FACING);
        this.altSlope = ctx.state().getValue(FramedProperties.ALT_SLOPE);
        PillarConnection pillar = ctx.state().getValue(PropertyHolder.PILLAR_CONNECTION);
        this.hasPillar = pillar != PillarConnection.NONE;
        this.slopeHeight = computeSlopeHeight(pillar);
        this.pillarHeight = computePillarHeight(pillar);
        this.pillarWidth = switch (pillar) {
            case NONE -> 0F;
            case POST -> 10F/16F;
            case PILLAR -> 12F/16F;
        };
        float pillarFaceRadius = switch (pillar) {
            case NONE -> 0F;
            case POST -> 2F/16F;
            case PILLAR -> 4F/16F;
        };
        this.pillarFaceMin = .5F - pillarFaceRadius;
        this.pillarFaceMax = .5F + pillarFaceRadius;
    }

@Override
    public final void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        Direction quadDir = quad.direction();
        buildBody(quadMap, quad, quadDir);
        if (hasPillar) {
            buildPillar(quadMap, quad, quadDir);
        }
    }

protected void buildBody(QuadMapBuilder quadMap, BakedQuad quad, Direction quadDir) {
        if (DirUtils.isY(facing)) {
            boolean up = facing == Direction.UP;
            if (!altSlope && quadDir.getAxis() != facing.getAxis()) {
                QuadModifier.of(quad)
                        .applyIf(Modifiers.cut(facing, slopeHeight), hasPillar)
                        .apply(Modifiers.cut(quadDir.getCounterClockWise(), up ? .5F : 1, up ? 1 : .5F))
                        .apply(Modifiers.cut(quadDir.getClockWise(), up ? .5F : 1, up ? 1 : .5F))
                        .apply(Modifiers.makeVerticalSlope(up, FramedSlopePanelGeometry.SLOPE_ANGLE))
                        .export(quadMap, null);
            } else if (altSlope && quadDir == facing) {
                for (Direction dir : Direction.Plane.HORIZONTAL) {
                    float angle = up ? -FramedSlopePanelGeometry.SLOPE_ANGLE : FramedSlopePanelGeometry.SLOPE_ANGLE;
                    angle = (up ? -90F : 90F) - angle;
                    if (dir == Direction.NORTH || dir == Direction.EAST) {
                        angle *= -1F;
                    }

                    Vector3f origin = up ? TOP_CENTER : BOTTOM_CENTER;

                    QuadModifier.of(quad)
                            .applyIf(Modifiers.cut(dir, slopeHeight), hasPillar)
                            .apply(Modifiers.cut(dir.getCounterClockWise(), .5F, 1))
                            .apply(Modifiers.cut(dir.getClockWise(), 1, .5F))
                            .apply(Modifiers.offset(dir.getOpposite(), .5F))
                            .apply(Modifiers.rotate(dir.getClockWise().getAxis(), origin, angle, true))
                            .export(quadMap, null);
                }
            }
        } else {
            if (!altSlope && quadDir.getAxis() == facing.getAxis()) {
                QuadModifier.of(quad)
                        .applyIf(Modifiers.cut(Direction.DOWN, slopeHeight), hasPillar)
                        .apply(Modifiers.cut(facing.getClockWise(), 1, .5F))
                        .apply(Modifiers.cut(facing.getCounterClockWise(), 1, .5F))
                        .apply(Modifiers.makeVerticalSlope(true, FramedSlopeSlabGeometry.SLOPE_ANGLE))
                        .apply(Modifiers.offset(Direction.UP, .5F))
                        .export(quadMap, null);

                QuadModifier.of(quad)
                        .applyIf(Modifiers.cut(Direction.UP, slopeHeight), hasPillar)
                        .apply(Modifiers.cut(facing.getClockWise(), .5F, 1))
                        .apply(Modifiers.cut(facing.getCounterClockWise(), .5F, 1))
                        .apply(Modifiers.makeVerticalSlope(false, FramedSlopeSlabGeometry.SLOPE_ANGLE))
                        .apply(Modifiers.offset(Direction.DOWN, .5F))
                        .export(quadMap, null);
            } else if (altSlope && DirUtils.isY(quadDir)) {
                boolean up = quadDir == Direction.UP;

                float angle = up ? FramedSlopePanelGeometry.SLOPE_ANGLE : -FramedSlopePanelGeometry.SLOPE_ANGLE;
                if (facing == Direction.NORTH || facing == Direction.EAST) {
                    angle *= -1F;
                }

                Vector3f origin = facing.getOpposite().step().max(ZERO);
                if (up) {
                    origin.add(0, 1, 0);
                }

                QuadModifier.of(quad)
                        .applyIf(Modifiers.cut(facing, slopeHeight), hasPillar)
                        .apply(Modifiers.cut(facing.getCounterClockWise(), .5F, 1))
                        .apply(Modifiers.cut(facing.getClockWise(), 1, .5F))
                        .apply(Modifiers.rotate(facing.getClockWise().getAxis(), origin, angle, true))
                        .export(quadMap, null);
            } else if (quadDir.getAxis() == facing.getClockWise().getAxis()) {
                boolean right = quadDir == facing.getClockWise();
                QuadModifier.of(quad)
                        .applyIf(Modifiers.cut(facing, slopeHeight), hasPillar)
                        .apply(Modifiers.cut(Direction.DOWN, right ? 1 : .5F, right ? .5F : 1))
                        .apply(Modifiers.cut(Direction.UP, right ? 1 : .5F, right ? .5F : 1))
                        .apply(Modifiers.makeHorizontalSlope(!right, FramedSlopePanelGeometry.SLOPE_ANGLE))
                        .export(quadMap, null);
            }
        }
    }

private void buildPillar(QuadMapBuilder quadMap, BakedQuad quad, Direction quadDir) {
        if (DirUtils.isY(facing)) {
            if (quadDir == facing) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cutTopBottom(pillarFaceMin, pillarFaceMin, pillarFaceMax, pillarFaceMax))
                        .export(quadMap, quadDir);
            } else if (quadDir != facing.getOpposite()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(facing.getOpposite(), pillarHeight))
                        .apply(Modifiers.cut(quadDir.getClockWise().getAxis(), pillarWidth))
                        .apply(Modifiers.setPosition(pillarWidth))
                        .export(quadMap, null);
            }
        } else {
            if (DirUtils.isY(quadDir)) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(facing.getOpposite(), pillarHeight))
                        .apply(Modifiers.cut(facing.getClockWise().getAxis(), pillarWidth))
                        .apply(Modifiers.setPosition(pillarWidth))
                        .export(quadMap, null);
            } else if (quadDir == facing) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cutSide(pillarFaceMin, pillarFaceMin, pillarFaceMax, pillarFaceMax))
                        .export(quadMap, quadDir);
            } else if (quadDir != facing.getOpposite()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(facing.getOpposite(), pillarHeight))
                        .apply(Modifiers.cut(Direction.Axis.Y, pillarWidth))
                        .apply(Modifiers.setPosition(pillarWidth))
                        .export(quadMap, null);
            }
        }
    }

protected float computeSlopeHeight(PillarConnection pillar) {
        return switch (pillar) {
            case NONE -> 1F;
            case POST -> 12F/16F;
            case PILLAR -> 8F/16F;
        };
    }

protected float computePillarHeight(PillarConnection pillar) {
        return switch (pillar) {
            case NONE -> 0F;
            case POST -> 4F/16F;
            case PILLAR -> 8F/16F;
        };
    }

public FramedPyramidSlabGeometry(GeometryFactory.Context ctx) {
        this.facing = ctx.state().getValue(BlockStateProperties.FACING);
        this.altSlope = ctx.state().getValue(FramedProperties.ALT_SLOPE);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        Direction quadDir = quad.direction();
        if (DirUtils.isY(facing)) {
            boolean up = facing == Direction.UP;
            if (!altSlope && quadDir.getAxis() != facing.getAxis()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(facing, .5F))
                        .apply(Modifiers.cut(quadDir.getCounterClockWise(), up ? 0 : 1, up ? 1 : 0))
                        .apply(Modifiers.cut(quadDir.getClockWise(), up ? 0 : 1, up ? 1 : 0))
                        .apply(Modifiers.makeVerticalSlope(up, 45))
                        .export(quadMap, null);
            } else if (altSlope && quadDir == facing) {
                for (Direction dir : Direction.Plane.HORIZONTAL) {
                    boolean northeast = dir == Direction.NORTH || dir == Direction.EAST;
                    float angle = up ? -45 : 45;
                    if (northeast) {
                        angle *= -1F;
                    }
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir, .5F))
                            .apply(Modifiers.cut(dir.getCounterClockWise(), 0, 1))
                            .apply(Modifiers.cut(dir.getClockWise(), 1, 0))
                            .apply(Modifiers.setPosition(.5F))
                            .apply(Modifiers.rotateCentered(dir.getClockWise().getAxis(), angle, true))
                            .export(quadMap, null);
                }
            }
        } else {
            if (!altSlope && quadDir.getAxis() == facing.getAxis()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(Direction.DOWN, .5F))
                        .apply(Modifiers.cut(facing.getClockWise(), 1, 0))
                        .apply(Modifiers.cut(facing.getCounterClockWise(), 1, 0))
                        .apply(Modifiers.makeVerticalSlope(true, 45))
                        .export(quadMap, null);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(Direction.UP, .5F))
                        .apply(Modifiers.cut(facing.getClockWise(), 0, 1))
                        .apply(Modifiers.cut(facing.getCounterClockWise(), 0, 1))
                        .apply(Modifiers.makeVerticalSlope(false, 45))
                        .export(quadMap, null);
            } else if (altSlope && DirUtils.isY(quadDir)) {
                boolean up = quadDir == Direction.UP;

                float angle = up ? 45 : -45;
                if (facing == Direction.NORTH || facing == Direction.EAST) {
                    angle *= -1F;
                }

                Vector3f origin = facing.getOpposite().step().max(ZERO);
                if (up) {
                    origin.add(0, 1, 0);
                }

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(facing, .5F))
                        .apply(Modifiers.cut(facing.getCounterClockWise(), 0, 1))
                        .apply(Modifiers.cut(facing.getClockWise(), 1, 0))
                        .apply(Modifiers.rotate(facing.getClockWise().getAxis(), origin, angle, true))
                        .export(quadMap, null);
            } else if (quadDir.getAxis() == facing.getClockWise().getAxis()) {
                boolean right = quadDir == facing.getClockWise();
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(facing, .5F))
                        .apply(Modifiers.cut(Direction.DOWN, right ? 1 : 0, right ? 0 : 1))
                        .apply(Modifiers.cut(Direction.UP, right ? 1 : 0, right ? 0 : 1))
                        .apply(Modifiers.makeHorizontalSlope(!right, 45))
                        .export(quadMap, null);
            }
        }
    }

public FramedSlopeGeometry(GeometryFactory.Context ctx) {
        this.dir = ctx.state().getValue(FramedProperties.FACING_HOR);
        this.type = ctx.state().getValue(PropertyHolder.SLOPE_TYPE);
        this.altSlope = ctx.state().getValue(FramedProperties.ALT_SLOPE);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        Direction quadDir = quad.direction();
        if (type == SlopeType.HORIZONTAL) {
            if (!altSlope && quad.direction() == dir.getOpposite()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.makeHorizontalSlope(false, 45))
                        .export(quadMap, null);
            } else if (altSlope && quadDir == dir.getClockWise()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.makeHorizontalSlope(true, 45))
                        .export(quadMap, null);
            } else if (DirUtils.isY(quadDir)) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getOpposite(), 1, 0))
                        .export(quadMap, quadDir);
            }
        } else {
            boolean top = type == SlopeType.TOP;
            if (!altSlope && quadDir == dir.getOpposite()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.makeVerticalSlope(!top, 45))
                        .export(quadMap, null);
            } else if (altSlope && DirUtils.isY(quadDir)) {
                QuadModifier.of(quad)
                        .apply(Modifiers.makeVerticalSlope(dir.getOpposite(), 45))
                        .export(quadMap, null);
            } else if (quadDir == dir.getClockWise() || quadDir == dir.getCounterClockWise()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getOpposite(), top ? 1 : 0, top ? 0 : 1))
                        .export(quadMap, quadDir);
            }
        }
    }

