                            .apply(Modifiers.cut(topDir.getOpposite(), .5F))
                            .apply(Modifiers.cut(dir.getCounterClockWise(), top ? -.5F : .5F, top ? .5F : -.5F))
                            .apply(Modifiers.makeVerticalSlope(!top, 45))
                            .apply(Modifiers.offset(dir.getOpposite(), .5F))
                            .export(quadMap, null);
                }

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(topDir.getOpposite(), .5F))
                        .apply(Modifiers.cut(dir.getClockWise(), top ? 1.5F : .5F, top ? .5F : 1.5F))
                        .export(quadMap, quadDir);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(topDir, .5F))
                        .export(quadMap, quadDir);
            } else if (quadDir == dir.getClockWise()) {
                if (!altSlope) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(topDir.getOpposite(), .5F))
                            .apply(Modifiers.cut(dir, top ? -.5F : .5F, top ? .5F : -.5F))
                            .apply(Modifiers.makeVerticalSlope(!top, 45))
                            .apply(Modifiers.offset(dir.getClockWise(), .5F))
                            .export(quadMap, null);
                }

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(topDir.getOpposite(), .5F))
                        .apply(Modifiers.cut(dir.getOpposite(), top ? 1.5F : .5F, top ? .5F : 1.5F))
                        .export(quadMap, quadDir);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(topDir, .5F))
                        .export(quadMap, quadDir);
            } else if (quadDir == topDir) {
                if (altSlope) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                            .apply(Modifiers.cut(dir, 0F, 1F))
                            .apply(Modifiers.makeVerticalSlope(dir.getClockWise(), 45))
                            .apply(Modifiers.offset(topDir, .5F))
                            .export(quadMap, null);

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir, .5F))
                            .apply(Modifiers.cut(dir.getCounterClockWise(), 1F, 0F))
                            .apply(Modifiers.makeVerticalSlope(dir.getOpposite(), 45))
                            .apply(Modifiers.offset(topDir, .5F))
                            .export(quadMap, null);
                }

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getOpposite(), .5F))
                        .export(quadMap, quadDir);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir, .5F))
                        .apply(Modifiers.cut(dir.getClockWise(), .5F))
                        .export(quadMap, quadDir);
            }
        }
    }

public FramedElevatedSlopeEdgeGeometry(GeometryFactory.Context ctx) {
        this.dir = ctx.state().getValue(FramedProperties.FACING_HOR);
        this.type = ctx.state().getValue(PropertyHolder.SLOPE_TYPE);
        this.altSlope = ctx.state().getValue(FramedProperties.ALT_SLOPE);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        Direction quadDir = quad.direction();
        if (type == SlopeType.HORIZONTAL) {
            if (quadDir == dir.getOpposite()) {
                if (!altSlope) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                            .apply(Modifiers.makeHorizontalSlope(false, 45))
                            .apply(Modifiers.offset(dir.getOpposite(), .5F))
                            .export(quadMap, null);
                }

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getClockWise(), .5F))
                        .export(quadMap, quadDir);
            } else if (quadDir == dir.getClockWise()) {
                if (altSlope) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir, .5F))
                            .apply(Modifiers.makeHorizontalSlope(true, 45))
                            .apply(Modifiers.offset(dir.getClockWise(), .5F))
                            .export(quadMap, null);
                }

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getOpposite(), .5F))
                        .export(quadMap, quadDir);
            } else if (DirUtils.isY(quadDir)) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                        .apply(Modifiers.cut(dir.getOpposite(), 1.5F, .5F))
                        .export(quadMap, quadDir);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getClockWise(), .5F))
                        .export(quadMap, quadDir);
            }
        } else {
            boolean top = type == SlopeType.TOP;
            Direction vertEdge = top ? Direction.DOWN : Direction.UP;
            if (quadDir == dir.getOpposite()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(vertEdge, .5F))
                        .export(quadMap, quadDir);

                if (!altSlope) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(vertEdge.getOpposite(), .5F))
                            .apply(Modifiers.makeVerticalSlope(!top, 45))
                            .apply(Modifiers.offset(dir.getOpposite(), .5F))
                            .export(quadMap, null);
                }
            } else if ((!top && quadDir == Direction.UP) || (top && quadDir == Direction.DOWN)) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getOpposite(), .5F))
                        .export(quadMap, quadDir);

                if (altSlope) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir, .5F))
                            .apply(Modifiers.makeVerticalSlope(dir.getOpposite(), 45))
                            .apply(Modifiers.offset(top ? Direction.DOWN : Direction.UP, .5F))
                            .export(quadMap, null);
                }
            } else if (quadDir == dir.getClockWise() || quadDir == dir.getCounterClockWise()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(vertEdge.getOpposite(), .5F))
                        .apply(Modifiers.cut(dir.getOpposite(), top ? 1.5F : .5F, top ? .5F : 1.5F))
                        .export(quadMap, quadDir);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(vertEdge, .5F))
                        .export(quadMap, quadDir);
            }
        }
    }

public FramedInnerCornerSlopeEdgeGeometry(GeometryFactory.Context ctx) {
        this.dir = ctx.state().getValue(FramedProperties.FACING_HOR);
        this.type = ctx.state().getValue(PropertyHolder.CORNER_TYPE);
        this.altType = ctx.state().getValue(PropertyHolder.ALT_TYPE);
        this.altSlope = ctx.state().getValue(FramedProperties.ALT_SLOPE);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        Direction quadDir = quad.direction();
        boolean top = type.isTop();
        if (type.isHorizontal()) {
            boolean right = type.isRight();
            Direction xBackFace = right ? dir.getClockWise() : dir.getCounterClockWise();
            Direction yBackFace = top ? Direction.UP : Direction.DOWN;
            if (altType) {
                if (quadDir == dir) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace, .5F))
                            .apply(Modifiers.cut(xBackFace, .5F))
                            .apply(Modifiers.setPosition(.5F))
                            .export(quadMap, null);
                } else if (quadDir == yBackFace) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir, .5F))
                            .apply(Modifiers.cut(xBackFace, .5F))
                            .apply(Modifiers.setPosition(.5F))
                            .export(quadMap, null);
                } else if (quadDir == xBackFace) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir, .5F))
                            .apply(Modifiers.cut(yBackFace, .5F))
                            .apply(Modifiers.setPosition(.5F))
                            .export(quadMap, null);
                } else if (quadDir == yBackFace.getOpposite()) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir, .5F))
                            .apply(Modifiers.cut(xBackFace, .5F))
                            .apply(Modifiers.cut(xBackFace.getOpposite(), right ? 1.5F : .5F, right ? .5F : 1.5F))
                            .export(quadMap, quadDir);

                    if (altSlope) {
                        QuadModifier.of(quad)
                                .apply(Modifiers.cut(dir, .5F))
                                .apply(Modifiers.cut(xBackFace, .5F))
                                .apply(Modifiers.cut(xBackFace, right ? .5F : -.5F, right ? -.5F : .5F))
                                .apply(Modifiers.makeVerticalSlope(dir.getOpposite(), 45))
                                .apply(Modifiers.offset(yBackFace.getOpposite(), .5F))
                                .export(quadMap, null);
                    }
                } else if (quadDir == xBackFace.getOpposite()) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir, .5F))
                            .apply(Modifiers.cut(yBackFace, .5F))
                            .apply(Modifiers.cut(yBackFace.getOpposite(), right ? 1.5F : .5F, right ? .5F : 1.5F))
                            .export(quadMap, quadDir);

                    if (altSlope) {
                        QuadModifier.of(quad)
                                .apply(Modifiers.cut(dir, .5F))
                                .apply(Modifiers.cut(yBackFace, .5F))
                                .apply(Modifiers.cut(yBackFace, right ? -.5F : .5F, right ? .5F : -.5F))
                                .apply(Modifiers.makeHorizontalSlope(!right, 45))
                                .apply(Modifiers.offset(xBackFace.getOpposite(), .5F))
                                .export(quadMap, null);
                    }
                } else if (!altSlope && quadDir == dir.getOpposite()) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(xBackFace, .5F))
                            .apply(Modifiers.cut(yBackFace, .5F))
                            .apply(Modifiers.cut(yBackFace.getOpposite(), right ? 1F : 0F, right ? 0F : 1F))
                            .apply(Modifiers.makeVerticalSlope(!top, 45))
                            .apply(Modifiers.offset(dir.getOpposite(), .5F))
                            .export(quadMap, null);

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace, .5F))
                            .apply(Modifiers.cut(xBackFace, .5F))
                            .apply(Modifiers.cut(xBackFace.getOpposite(), top ? 0F : 1F, top ? 1F : 0F))
                            .apply(Modifiers.makeHorizontalSlope(right, 45))
                            .apply(Modifiers.offset(dir.getOpposite(), .5F))
                            .export(quadMap, null);
                }
            } else {
                if (quadDir == dir) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace.getOpposite(), .5F))
                            .export(quadMap, quadDir);

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(xBackFace.getOpposite(), .5F))
                            .apply(Modifiers.cut(yBackFace, .5F))
                            .export(quadMap, quadDir);
                } else if (quadDir == yBackFace) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir.getOpposite(), .5F))
                            .export(quadMap, quadDir);
                } else if (quadDir == xBackFace) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir.getOpposite(), .5F))
                            .export(quadMap, quadDir);
                } else if (quadDir == yBackFace.getOpposite()) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir.getOpposite(), .5F))
                            .apply(Modifiers.cut(xBackFace.getOpposite(), right ? .5F : -.5F, right ? -.5F : .5F))
                            .export(quadMap, quadDir);

                    if (altSlope) {
                        QuadModifier.of(quad)
                                .apply(Modifiers.cut(dir.getOpposite(), .5F))
                                .apply(Modifiers.cut(xBackFace, right ? 1.5F : .5F, right ? .5F : 1.5F))
                                .apply(Modifiers.makeVerticalSlope(dir.getOpposite(), 45))
                                .apply(Modifiers.offset(yBackFace, .5F))
                                .export(quadMap, null);
                    }
                } else if (quadDir == xBackFace.getOpposite()) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir.getOpposite(), .5F))
                            .apply(Modifiers.cut(yBackFace.getOpposite(), right ? .5F : -.5F, right ? -.5F : .5F))
                            .export(quadMap, quadDir);

                    if (altSlope) {
                        QuadModifier.of(quad)
                                .apply(Modifiers.cut(dir.getOpposite(), .5F))
                                .apply(Modifiers.cut(yBackFace, right ? .5F : 1.5F, right ? 1.5F : .5F))
                                .apply(Modifiers.makeHorizontalSlope(!right, 45))
                                .apply(Modifiers.offset(xBackFace, .5F))
                                .export(quadMap, null);
                    }
                } else if (!altSlope && quadDir == dir.getOpposite()) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(xBackFace.getOpposite(), .5F))
                            .apply(Modifiers.cut(yBackFace, right ? 0F : 1F, right ? 1F : 0F))
                            .apply(Modifiers.makeHorizontalSlope(right, 45))
                            .apply(Modifiers.offset(dir, .5F))
                            .export(quadMap, null);

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace.getOpposite(), .5F))
                            .apply(Modifiers.cut(xBackFace, top ? 1F : 0F, top ? 0F : 1F))
                            .apply(Modifiers.makeVerticalSlope(!top, 45))
                            .apply(Modifiers.offset(dir, .5F))
                            .export(quadMap, null);
                }
            }
        } else {
            Direction bottomFace = top ? Direction.UP : Direction.DOWN;
            if (altType) {
                if (quadDir == dir || quadDir == dir.getCounterClockWise()) {
                    Direction cutDir = quadDir == dir ? dir.getCounterClockWise() : dir;
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(bottomFace, .5F))
                            .apply(Modifiers.cut(cutDir, .5F))
                            .apply(Modifiers.setPosition(.5F))
                            .export(quadMap, null);
                } else if (quadDir == bottomFace) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir, .5F))
                            .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                            .apply(Modifiers.setPosition(.5F))
                            .export(quadMap, null);
                } else if (altSlope && quadDir == bottomFace.getOpposite()) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                            .apply(Modifiers.cut(dir, 0F, 1F))
                            .apply(Modifiers.makeVerticalSlope(dir.getClockWise(), 45))
                            .apply(Modifiers.offset(bottomFace.getOpposite(), .5F))
                            .export(quadMap, null);

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir, .5F))
                            .apply(Modifiers.cut(dir.getCounterClockWise(), 1F, 0F))
                            .apply(Modifiers.makeVerticalSlope(dir.getOpposite(), 45))
                            .apply(Modifiers.offset(bottomFace.getOpposite(), .5F))
                            .export(quadMap, null);
                } else if (quadDir == dir.getOpposite()) {
                    if (!altSlope) {
                        QuadModifier.of(quad)
                                .apply(Modifiers.cut(bottomFace, .5F))
                                .apply(Modifiers.cut(dir.getCounterClockWise(), top ? -.5F : .5F, top ? .5F : -.5F))
                                .apply(Modifiers.makeVerticalSlope(!top, 45))
                                .apply(Modifiers.offset(dir.getOpposite(), .5F))
                                .export(quadMap, null);
                    }

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(bottomFace, .5F))
                            .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                            .apply(Modifiers.cut(dir.getClockWise(), top ? 1.5F : .5F, top ? .5F : 1.5F))
                            .export(quadMap, quadDir);
                } else if (quadDir == dir.getClockWise()) {
                    if (!altSlope) {
                        QuadModifier.of(quad)
                                .apply(Modifiers.cut(bottomFace, .5F))
                                .apply(Modifiers.cut(dir, top ? -.5F : .5F, top ? .5F : -.5F))
                                .apply(Modifiers.makeVerticalSlope(!top, 45))
                                .apply(Modifiers.offset(dir.getClockWise(), .5F))
                                .export(quadMap, null);
                    }

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(bottomFace, .5F))
                            .apply(Modifiers.cut(dir, .5F))
                            .apply(Modifiers.cut(dir.getOpposite(), top ? 1.5F : .5F, top ? .5F : 1.5F))
                            .export(quadMap, quadDir);
                }
            } else {
                if (quadDir == dir || quadDir == dir.getCounterClockWise()) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(bottomFace.getOpposite(), .5F))
                            .export(quadMap, quadDir);
                } else if (quadDir == bottomFace) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir.getOpposite(), .5F))
                            .export(quadMap, quadDir);

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir, .5F))
                            .apply(Modifiers.cut(dir.getClockWise(), .5F))
                            .export(quadMap, quadDir);
                } else if (altSlope && quadDir == bottomFace.getOpposite()) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir.getOpposite(), .5F))
                            .apply(Modifiers.cut(dir.getCounterClockWise(), 1F, 0F))
                            .apply(Modifiers.makeVerticalSlope(dir.getOpposite(), 45))
                            .apply(Modifiers.offset(bottomFace, .5F))
                            .export(quadMap, null);

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir.getClockWise(), .5F))
                            .apply(Modifiers.cut(dir, 0F, 1F))
                            .apply(Modifiers.makeVerticalSlope(dir.getClockWise(), 45))
                            .apply(Modifiers.offset(bottomFace, .5F))
                            .export(quadMap, null);
                } else if (quadDir == dir.getOpposite()) {
                    if (!altSlope) {
                        QuadModifier.of(quad)
                                .apply(Modifiers.cut(bottomFace.getOpposite(), .5F))
                                .apply(Modifiers.cut(dir.getCounterClockWise(), top ? .5F : 1.5F, top ? 1.5F : .5F))
                                .apply(Modifiers.makeVerticalSlope(!top, 45))
                                .apply(Modifiers.offset(dir, .5F))
                                .export(quadMap, null);
                    }

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(bottomFace.getOpposite(), .5F))
                            .apply(Modifiers.cut(dir.getClockWise(), top ? .5F : -.5F, top ? -.5F : .5F))
                            .export(quadMap, quadDir);
                } else if (quadDir == dir.getClockWise()) {
                    if (!altSlope) {
                        QuadModifier.of(quad)
                                .apply(Modifiers.cut(bottomFace.getOpposite(), .5F))
                                .apply(Modifiers.cut(dir, top ? .5F : 1.5F, top ? 1.5F : .5F))
                                .apply(Modifiers.makeVerticalSlope(!top, 45))
                                .apply(Modifiers.offset(dir.getCounterClockWise(), .5F))
                                .export(quadMap, null);
                    }

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(bottomFace.getOpposite(), .5F))
                            .apply(Modifiers.cut(dir.getOpposite(), top ? .5F : -.5F, top ? -.5F : .5F))
                            .export(quadMap, quadDir);
                }
            }
        }
    }

public FramedInnerThreewayCornerSlopeEdgeGeometry(GeometryFactory.Context ctx) {
        Direction dir = ctx.state().getValue(FramedProperties.FACING_HOR);
        this.top = ctx.state().getValue(FramedProperties.TOP);
        this.right = ctx.state().getValue(PropertyHolder.RIGHT);
        this.dir = right ? dir.getClockWise() : dir;
        this.altType = ctx.state().getValue(PropertyHolder.ALT_TYPE);
        this.altSlope = ctx.state().getValue(FramedProperties.ALT_SLOPE);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        Direction quadDir = quad.direction();
        Direction yBackFace = top ? Direction.UP : Direction.DOWN;
        if (altType) {
            if (quadDir == dir || quadDir == dir.getCounterClockWise()) {
                Direction cutDir = quadDir == dir ? dir.getCounterClockWise() : dir;
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(yBackFace, .5F))
                        .apply(Modifiers.cut(cutDir, .5F))
                        .apply(Modifiers.setPosition(.5F))
                        .export(quadMap, null);
            } else if (quadDir == yBackFace) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir, .5F))
                        .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                        .apply(Modifiers.setPosition(.5F))
                        .export(quadMap, null);
            } else if (quadDir == dir.getOpposite()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(yBackFace, .5F))
                        .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                        .apply(Modifiers.cut(dir.getClockWise(), top ? 1.5F : .5F, top ? .5F : 1.5F))
                        .export(quadMap, quadDir);

                if (!right) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace, .25F))
                            .apply(Modifiers.cut(dir.getCounterClockWise(), top ? -.5F : .5F, top ? .5F : -.5F))
                            .apply(Modifiers.cut(dir.getClockWise(), top ? 0F : 1F, top ? 1F : 0F))
                            .apply(Modifiers.makeHorizontalSlope(false, 45))
                            .apply(Modifiers.offset(dir.getOpposite(), .5F))
                            .export(quadMap, null);
                }

                if (!altSlope) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir.getCounterClockWise(), .25F))
                            .apply(Modifiers.cut(Direction.UP, top ? -.5F : 0F, top ? .5F : 1F))
                            .apply(Modifiers.cut(Direction.DOWN, top ? 0F : -.5F, top ? 1F : .5F))
                            .apply(Modifiers.makeVerticalSlope(!top, 45))
                            .apply(Modifiers.offset(dir.getOpposite(), .5F))
                            .export(quadMap, null);
                }
            } else if (quadDir == dir.getClockWise()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(yBackFace, .5F))
                        .apply(Modifiers.cut(dir, .5F))
                        .apply(Modifiers.cut(dir.getOpposite(), top ? 1.5F : .5F, top ? .5F : 1.5F))
                        .export(quadMap, quadDir);

                if (right) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace, .25F))
                            .apply(Modifiers.cut(dir, top ? -.5F : .5F, top ? .5F : -.5F))
                            .apply(Modifiers.cut(dir.getOpposite(), top ? 0F : 1F, top ? 1F : 0F))
                            .apply(Modifiers.makeHorizontalSlope(true, 45))
                            .apply(Modifiers.offset(dir.getClockWise(), .5F))
                            .export(quadMap, null);
                }

                if (!altSlope) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir, .25F))
                            .apply(Modifiers.cut(Direction.UP, top ? .5F : 1F, top ? -.5F : 0F))
                            .apply(Modifiers.cut(Direction.DOWN, top ? 1F : .5F, top ? 0F : -.5F))
                            .apply(Modifiers.makeVerticalSlope(!top, 45))
                            .apply(Modifiers.offset(dir.getClockWise(), .5F))
                            .export(quadMap, null);
                }
            } else if (quadDir == yBackFace.getOpposite()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir, .5F))
                        .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                        .apply(Modifiers.cut(dir.getClockWise(), .5F, 1.5F))
                        .export(quadMap, quadDir);

                if (altSlope) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir, .25F))
                            .apply(Modifiers.cut(dir.getClockWise(), 1F, 0F))
                            .apply(Modifiers.cut(dir.getCounterClockWise(), -.5F, .5F))
                            .apply(Modifiers.makeVerticalSlope(dir.getClockWise(), 45))
                            .apply(Modifiers.offset(yBackFace.getOpposite(), .5F))
                            .export(quadMap, null);

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir.getCounterClockWise(), .25F))
                            .apply(Modifiers.cut(dir, .5F, -.5F))
                            .apply(Modifiers.cut(dir.getOpposite(), 0F, 1F))
                            .apply(Modifiers.makeVerticalSlope(dir.getOpposite(), 45))
                            .apply(Modifiers.offset(yBackFace.getOpposite(), .5F))
                            .export(quadMap, null);
                }
            }
        } else {
            if (quadDir == dir || quadDir == dir.getCounterClockWise()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(yBackFace.getOpposite(), .5F))
                        .export(quadMap, quadDir);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(yBackFace, .5F))
                        .apply(Modifiers.cut(quadDir == dir ? dir.getClockWise() : dir.getOpposite(), .5F))
                        .export(quadMap, quadDir);
            } else if (quadDir == yBackFace) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getOpposite(), .5F))
                        .export(quadMap, quadDir);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir, .5F))
                        .apply(Modifiers.cut(dir.getClockWise(), .5F))
                        .export(quadMap, quadDir);
            } else if (quadDir == dir.getOpposite()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(yBackFace.getOpposite(), .5F))
                        .apply(Modifiers.cut(dir.getClockWise(), top ? .5F : -.5F, top ? -.5F : .5F))
                        .export(quadMap, quadDir);

                if (!right) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace, .5F))
                            .apply(Modifiers.cut(dir.getClockWise(), .5F))
                            .apply(Modifiers.makeHorizontalSlope(false, 45))
                            .apply(Modifiers.offset(dir, .5F))
                            .export(quadMap, null);

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace, .75F))
                            .apply(Modifiers.cut(yBackFace.getOpposite(), .5F))
                            .apply(Modifiers.cut(dir.getCounterClockWise(), top ? .5F : 1.5F, top ? 1.5F : .5F))
                            .apply(Modifiers.cut(dir.getClockWise(), top ? 0F : 1F, top ? 1F : 0F))
                            .apply(Modifiers.makeHorizontalSlope(false, 45))
                            .apply(Modifiers.offset(dir, .5F))
                            .export(quadMap, null);
                }

                if (!altSlope) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace.getOpposite(), .5F))
                            .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                            .apply(Modifiers.makeVerticalSlope(!top, 45))
                            .apply(Modifiers.offset(dir, .5F))
                            .export(quadMap, null);

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir.getCounterClockWise(), .75F))
                            .apply(Modifiers.cut(dir.getClockWise(), .5F))
                            .apply(Modifiers.cut(Direction.UP, top ? .5F : 0F, top ? 1.5F : 1F))
                            .apply(Modifiers.cut(Direction.DOWN, top ? 0F : .5F, top ? 1F : 1.5F))
                            .apply(Modifiers.makeVerticalSlope(!top, 45))
                            .apply(Modifiers.offset(dir, .5F))
                            .export(quadMap, null);
                }
            } else if (quadDir == dir.getClockWise()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(yBackFace.getOpposite(), .5F))
                        .apply(Modifiers.cut(dir.getOpposite(), top ? .5F : -.5F, top ? -.5F : .5F))
                        .export(quadMap, quadDir);

                if (right) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace, .5F))
                            .apply(Modifiers.cut(dir.getOpposite(), .5F))
                            .apply(Modifiers.makeHorizontalSlope(true, 45))
                            .apply(Modifiers.offset(dir.getCounterClockWise(), .5F))
                            .export(quadMap, null);

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace, .75F))
                            .apply(Modifiers.cut(yBackFace.getOpposite(), .5F))
                            .apply(Modifiers.cut(dir, top ? .5F : 1.5F, top ? 1.5F : .5F))
                            .apply(Modifiers.cut(dir.getOpposite(), top ? 0F : 1F, top ? 1F : 0F))
                            .apply(Modifiers.makeHorizontalSlope(true, 45))
                            .apply(Modifiers.offset(dir.getCounterClockWise(), .5F))
                            .export(quadMap, null);
                }

                if (!altSlope) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace.getOpposite(), .5F))
                            .apply(Modifiers.cut(dir, .5F))
                            .apply(Modifiers.makeVerticalSlope(!top, 45))
                            .apply(Modifiers.offset(dir.getCounterClockWise(), .5F))
                            .export(quadMap, null);

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir, .75F))
                            .apply(Modifiers.cut(dir.getOpposite(), .5F))
                            .apply(Modifiers.cut(Direction.UP, top ? 1.5F : 1F, top ? .5F : 0F))
                            .apply(Modifiers.cut(Direction.DOWN, top ? 1F : 1.5F, top ? 0F : .5F))
                            .apply(Modifiers.makeVerticalSlope(!top, 45))
                            .apply(Modifiers.offset(dir.getCounterClockWise(), .5F))
                            .export(quadMap, null);
                }
            } else if (quadDir == yBackFace.getOpposite()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getOpposite(), .5F))
                        .apply(Modifiers.cut(dir.getClockWise(), -.5F, .5F))
                        .export(quadMap, quadDir);

                if (altSlope) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir, .5F))
                            .apply(Modifiers.cut(dir.getClockWise(), .5F))
                            .apply(Modifiers.makeVerticalSlope(dir.getClockWise(), 45))
                            .apply(Modifiers.offset(yBackFace, .5F))
                            .export(quadMap, null);

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                            .apply(Modifiers.cut(dir.getOpposite(), .5F))
                            .apply(Modifiers.makeVerticalSlope(dir.getOpposite(), 45))
                            .apply(Modifiers.offset(yBackFace, .5F))
                            .export(quadMap, null);

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir, .75F))
                            .apply(Modifiers.cut(dir.getOpposite(), .5F))
                            .apply(Modifiers.cut(dir.getClockWise(), 1F, 0F))
                            .apply(Modifiers.cut(dir.getCounterClockWise(), .5F, 1.5F))
                            .apply(Modifiers.makeVerticalSlope(dir.getClockWise(), 45))
                            .apply(Modifiers.offset(yBackFace, .5F))
                            .export(quadMap, null);

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir.getCounterClockWise(), .75F))
                            .apply(Modifiers.cut(dir.getClockWise(), .5F))
                            .apply(Modifiers.cut(dir.getOpposite(), 0F, 1F))
                            .apply(Modifiers.cut(dir, 1.5F, .5F))
                            .apply(Modifiers.makeVerticalSlope(dir.getOpposite(), 45))
                            .apply(Modifiers.offset(yBackFace, .5F))
                            .export(quadMap, null);
                }
            }
        }
    }

public FramedSlopeEdgeGeometry(GeometryFactory.Context ctx) {
        this.dir = ctx.state().getValue(FramedProperties.FACING_HOR);
        this.type = ctx.state().getValue(PropertyHolder.SLOPE_TYPE);
        this.altType = ctx.state().getValue(PropertyHolder.ALT_TYPE);
        this.altSlope = ctx.state().getValue(FramedProperties.ALT_SLOPE);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        Direction quadDir = quad.direction();
        boolean top = type == SlopeType.TOP;
        if (altType) {
            if (type == SlopeType.HORIZONTAL) {
                if (quadDir == dir) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                            .apply(Modifiers.setPosition(.5F))
                            .export(quadMap, null);
                } else if (quadDir == dir.getCounterClockWise()) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir, .5F))
                            .apply(Modifiers.setPosition(.5F))
                            .export(quadMap, null);
                } else if (!altSlope && quadDir == dir.getOpposite()) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                            .apply(Modifiers.makeHorizontalSlope(false, 45))
                            .apply(Modifiers.offset(dir.getOpposite(), .5F))
                            .export(quadMap, null);
                } else if (altSlope && quadDir == dir.getClockWise()) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir, .5F))
                            .apply(Modifiers.makeHorizontalSlope(true, 45))
                            .apply(Modifiers.offset(dir.getClockWise(), .5F))
                            .export(quadMap, null);
                } else if (DirUtils.isY(quadDir)) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                            .apply(Modifiers.cut(dir.getOpposite(), 1.5F, .5F))
                            .apply(Modifiers.cut(dir, .5F))
                            .export(quadMap, quadDir);
                }
            } else {
                if (quadDir == dir) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(top ? Direction.UP : Direction.DOWN, .5F))
                            .apply(Modifiers.setPosition(.5F))
                            .export(quadMap, null);
                } else if ((!top && quadDir == Direction.DOWN) || (top && quadDir == Direction.UP)) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir, .5F))
                            .apply(Modifiers.setPosition(.5F))
                            .export(quadMap, null);
                } else if (!altSlope && quadDir == dir.getOpposite()) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(top ? Direction.UP : Direction.DOWN, .5F))
                            .apply(Modifiers.makeVerticalSlope(!top, 45))
                            .apply(Modifiers.offset(dir.getOpposite(), .5F))
                            .export(quadMap, null);
                } else if (altSlope && ((!top && quadDir == Direction.UP) || (top && quadDir == Direction.DOWN))) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(dir, .5F))
                            .apply(Modifiers.makeVerticalSlope(dir.getOpposite(), 45))
                            .apply(Modifiers.offset(top ? Direction.DOWN : Direction.UP, .5F))
                            .export(quadMap, null);
                } else if (quadDir == dir.getClockWise() || quadDir == dir.getCounterClockWise()) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(top ? Direction.UP : Direction.DOWN, .5F))
                            .apply(Modifiers.cut(dir.getOpposite(), top ? 1.5F : .5F, top ? .5F : 1.5F))
                            .apply(Modifiers.cut(dir, .5F))
                            .export(quadMap, quadDir);
                }
            }
            return;
        }

        if (type == SlopeType.HORIZONTAL) {
            if (!altSlope && quadDir == dir.getOpposite()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getClockWise(), .5F))
                        .apply(Modifiers.makeHorizontalSlope(false, 45))
                        .apply(Modifiers.offset(dir, .5F))
                        .export(quadMap, null);
            } else if (altSlope && quadDir == dir.getClockWise()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getOpposite(), .5F))
                        .apply(Modifiers.makeHorizontalSlope(true, 45))
                        .apply(Modifiers.offset(dir.getCounterClockWise(), .5F))
                        .export(quadMap, null);
            } else if (DirUtils.isY(quadDir)) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getClockWise(), .5F))
                        .apply(Modifiers.cut(dir.getOpposite(), .5F, -.5F))
                        .export(quadMap, quadDir);
            } else if (quadDir == dir) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getClockWise(), .5F))
                        .export(quadMap, quadDir);
            } else if (quadDir == dir.getCounterClockWise()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getOpposite(), .5F))
                        .export(quadMap, quadDir);
            }
        } else {
            if (!altSlope && quadDir == dir.getOpposite()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(top ? Direction.DOWN : Direction.UP, .5F))
                        .apply(Modifiers.makeVerticalSlope(!top, 45))
                        .apply(Modifiers.offset(dir, .5F))
                        .export(quadMap, null);
            } else if (altSlope && ((!top && quadDir == Direction.UP) || (top && quadDir == Direction.DOWN))) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getOpposite(), .5F))
                        .apply(Modifiers.makeVerticalSlope(dir.getOpposite(), 45))
                        .apply(Modifiers.offset(top ? Direction.UP : Direction.DOWN, .5F))
                        .export(quadMap, null);
            } else if (quadDir == dir.getClockWise() || quadDir == dir.getCounterClockWise()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(top ? Direction.DOWN : Direction.UP, .5F))
                        .apply(Modifiers.cut(dir.getOpposite(), top ? .5F : -.5F, top ? -.5F : .5F))
                        .export(quadMap, quadDir);
            } else if (quadDir == dir) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(top ? Direction.DOWN : Direction.UP, .5F))
                        .export(quadMap, quadDir);
            } else if ((!top && quadDir == Direction.DOWN) || (top && quadDir == Direction.UP)) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getOpposite(), .5F))
                        .export(quadMap, quadDir);
            }
        }
    }

public FramedSlopeEdgePanelGeometry(GeometryFactory.Context ctx) {
        this.dir = ctx.state().getValue(FramedProperties.FACING_HOR);
        HorizontalRotation rot = ctx.state().getValue(PropertyHolder.ROTATION);
        this.backEdge = rot.withFacing(dir).getOpposite();
        this.front = ctx.state().getValue(PropertyHolder.FRONT);
        this.altSlope = ctx.state().getValue(FramedProperties.ALT_SLOPE);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object cacheKeyUserData) {
        Direction quadDir = quad.direction();
        if (quadDir == dir) {
            if (front) {
                QuadModifier.of(quad)
                        .apply(Modifiers.setPosition(.5F))
                        .export(quadMap, null);
            }
        } else if (quadDir == dir.getOpposite()) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(backEdge.getOpposite(), .5F))
                    .applyIf(Modifiers.setPosition(.5F), !front)
                    .export(quadMap, front ? quadDir : null);

            if (altSlope) {
                boolean vert = DirUtils.isY(backEdge);
                boolean topEdge = backEdge == Direction.DOWN;
                boolean rightEdge = backEdge == dir.getClockWise();
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(backEdge, .5F))
                        .apply(vert ? Modifiers.makeVerticalSlope(topEdge, 45) : Modifiers.makeHorizontalSlope(rightEdge, 45))
                        .applyIf(Modifiers.offset(dir.getOpposite(), .5F), front)
                        .export(quadMap, null);
            }
        } else if (quadDir == backEdge) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(front ? dir : dir.getOpposite(), .5F))
                    .export(quadMap, quadDir);
        } else if (quadDir == backEdge.getOpposite()) {
            if (!altSlope) {
                boolean vert = DirUtils.isY(backEdge);
                boolean rightEdge = backEdge == dir.getClockWise();
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getOpposite(), .5F))
                        .apply(vert ? Modifiers.makeVerticalSlope(dir, -45) : Modifiers.makeHorizontalSlope(rightEdge, -45))
                        .apply(Modifiers.offset(backEdge, 1F))
                        .applyIf(Modifiers.offset(dir.getOpposite(), .5F), front)
                        .export(quadMap, null);
            }
        } else {
            boolean flip = DirUtils.isY(backEdge) ? quadDir == dir.getClockWise() : backEdge == dir.getCounterClockWise();
            float lenOne = (flip ? 0F : 1F) + (front ? .5F : 0F);
            float lenTwo = (flip ? 1F : 0F) + (front ? .5F : 0F);
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(front ? dir : dir.getOpposite(), .5F))
                    .apply(Modifiers.cut(backEdge.getOpposite(), lenOne, lenTwo))
                    .export(quadMap, quadDir);
        }
    }

public FramedSlopeEdgeSlabGeometry(GeometryFactory.Context ctx) {
        this.dir = ctx.state().getValue(FramedProperties.FACING_HOR);
        this.topHalf = ctx.state().getValue(PropertyHolder.TOP_HALF);
        this.top = ctx.state().getValue(FramedProperties.TOP);
        this.altSlope = ctx.state().getValue(FramedProperties.ALT_SLOPE);
        this.backfaceAligned = top == topHalf;
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object cacheKeyUserData) {
        Direction quadDir = quad.direction();
        Direction backFace = top ? Direction.UP : Direction.DOWN;
        if (quadDir == dir) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(topHalf ? Direction.DOWN : Direction.UP, .5F))
                    .export(quadMap, dir);
        } else if (quadDir == backFace) {
            if (!backfaceAligned) {
                QuadModifier.of(quad)
                        .apply(Modifiers.setPosition(.5F))
                        .export(quadMap, null);
            }
        } else if (quadDir == backFace.getOpposite()) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir.getOpposite(), .5F))
                    .applyIf(Modifiers.setPosition(.5F), backfaceAligned)
                    .export(quadMap, backfaceAligned ? null : quadDir);

            if (altSlope) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir, .5F))
                        .apply(Modifiers.makeVerticalSlope(dir, -45))
                        .apply(Modifiers.offset(backFace, backfaceAligned ? 1F : .5F))
                        .export(quadMap, null);
            }
        } else if (quadDir == dir.getOpposite()) {
            if (!altSlope) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(backFace.getOpposite(), .5F))
                        .apply(Modifiers.makeVerticalSlope(top, -45))
                        .apply(Modifiers.offset(dir, 1F))
                        .applyIf(Modifiers.offset(backFace.getOpposite(), .5F), !backfaceAligned)
                        .export(quadMap, null);
            }
        } else {
            float lenTop = (top ? 1F : 0F) + (backfaceAligned ? 0F : .5F);
            float lenBot = (top ? 0F : 1F) + (backfaceAligned ? 0F : .5F);
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(topHalf ? Direction.DOWN : Direction.UP, .5F))
                    .apply(Modifiers.cut(dir.getOpposite(), lenTop, lenBot))
                    .export(quadMap, quadDir);
        }
    }

public FramedThreewayCornerSlopeEdgeGeometry(GeometryFactory.Context ctx) {
        Direction dir = ctx.state().getValue(FramedProperties.FACING_HOR);
        this.top = ctx.state().getValue(FramedProperties.TOP);
        this.right = ctx.state().getValue(PropertyHolder.RIGHT);
        this.dir = right ? dir.getClockWise() : dir;
        this.altType = ctx.state().getValue(PropertyHolder.ALT_TYPE);
        this.altSlope = ctx.state().getValue(FramedProperties.ALT_SLOPE);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        Direction quadDir = quad.direction();
        Direction yBackFace = top ? Direction.UP : Direction.DOWN;
        if (altType) {
            if (quadDir == dir) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(yBackFace, .5F))
                        .apply(Modifiers.cut(dir.getClockWise(), .5F))
                        .apply(Modifiers.setPosition(.5F))
                        .export(quadMap, null);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(yBackFace.getOpposite(), .5F))
                        .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                        .apply(Modifiers.setPosition(.5F))
                        .export(quadMap, null);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(yBackFace, .5F))
                        .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                        .apply(Modifiers.cut(dir.getClockWise(), top ? 1.5F : .5F, top ? .5F : 1.5F))
                        .export(quadMap, quadDir);
            } else if (quadDir == dir.getCounterClockWise()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(yBackFace, .5F))
                        .apply(Modifiers.cut(dir.getOpposite(), .5F))
                        .apply(Modifiers.setPosition(.5F))
                        .export(quadMap, null);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(yBackFace.getOpposite(), .5F))
                        .apply(Modifiers.cut(dir, .5F))
                        .apply(Modifiers.setPosition(.5F))
                        .export(quadMap, null);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(yBackFace, .5F))
                        .apply(Modifiers.cut(dir, .5F))
                        .apply(Modifiers.cut(dir.getOpposite(), top ? 1.5F : .5F, top ? .5F : 1.5F))
                        .export(quadMap, quadDir);
            } else if (quadDir == yBackFace) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getOpposite(), .5F))
                        .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                        .apply(Modifiers.setPosition(.5F))
                        .export(quadMap, null);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir, .5F))
                        .apply(Modifiers.cut(dir.getClockWise(), .5F))
                        .apply(Modifiers.setPosition(.5F))
                        .export(quadMap, null);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir, .5F))
                        .apply(Modifiers.cut(dir.getClockWise(), .5F, 1.5F))
                        .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                        .export(quadMap, quadDir);
            } else if (quadDir == dir.getOpposite()) {
                if (!right) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace.getOpposite(), .5F))
                            .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                            .apply(Modifiers.makeHorizontalSlope(false, 45))
                            .apply(Modifiers.offset(dir.getOpposite(), .5F))
                            .export(quadMap, null);

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace.getOpposite(), .75F))
                            .apply(Modifiers.cut(yBackFace, .5F))
                            .apply(Modifiers.cut(dir.getClockWise(), top ? 1.5F : .5F, top ? .5F : 1.5F))
                            .apply(Modifiers.cut(dir.getCounterClockWise(), top ? 1F : 0F, top ? 0F : 1F))
                            .apply(Modifiers.makeHorizontalSlope(false, 45))
                            .apply(Modifiers.offset(dir.getOpposite(), .5F))
                            .export(quadMap, null);
                }

                if (!altSlope) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace, .5F))
                            .apply(Modifiers.cut(dir.getClockWise(), .5F))
                            .apply(Modifiers.makeVerticalSlope(!top, 45))
                            .apply(Modifiers.offset(dir.getOpposite(), .5F))
                            .export(quadMap, null);

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace, .5F))
                            .apply(Modifiers.cut(dir.getClockWise(), .75F))
                            .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                            .apply(Modifiers.cut(Direction.UP, top ? 1F : 1.5F, top ? 0F : .5F))
                            .apply(Modifiers.cut(Direction.DOWN, top ? 1.5F : 1F, top ? .5F : 0F))
                            .apply(Modifiers.makeVerticalSlope(!top, 45))
                            .apply(Modifiers.offset(dir.getOpposite(), .5F))
                            .export(quadMap, null);
                }
            } else if (quadDir == dir.getClockWise()) {
                if (right) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace.getOpposite(), .5F))
                            .apply(Modifiers.cut(dir, .5F))
                            .apply(Modifiers.makeHorizontalSlope(true, 45))
                            .apply(Modifiers.offset(dir.getClockWise(), .5F))
                            .export(quadMap, null);

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace.getOpposite(), .75F))
                            .apply(Modifiers.cut(yBackFace, .5F))
                            .apply(Modifiers.cut(dir.getOpposite(), top ? 1.5F : .5F, top ? .5F : 1.5F))
                            .apply(Modifiers.cut(dir, top ? 1F : 0F, top ? 0F : 1F))
                            .apply(Modifiers.makeHorizontalSlope(true, 45))
                            .apply(Modifiers.offset(dir.getClockWise(), .5F))
                            .export(quadMap, null);
                }

                if (!altSlope) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace, .5F))
                            .apply(Modifiers.cut(dir.getOpposite(), .5F))
                            .apply(Modifiers.makeVerticalSlope(!top, 45))
                            .apply(Modifiers.offset(dir.getClockWise(), .5F))
                            .export(quadMap, null);

                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace, .5F))
                            .apply(Modifiers.cut(dir.getOpposite(), .75F))
                            .apply(Modifiers.cut(dir, .5F))
                            .apply(Modifiers.cut(Direction.UP, top ? 0F : .5F, top ? 1F : 1.5F))
                            .apply(Modifiers.cut(Direction.DOWN, top ? .5F : 0F, top ? 1.5F : 1F))
                            .apply(Modifiers.makeVerticalSlope(!top, 45))
                            .apply(Modifiers.offset(dir.getClockWise(), .5F))
                            .export(quadMap, null);
                }
            } else if (altSlope && quadDir == yBackFace.getOpposite()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getOpposite(), .5F))
                        .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                        .apply(Modifiers.makeVerticalSlope(dir.getClockWise(), 45))
                        .apply(Modifiers.offset(yBackFace.getOpposite(), .5F))
                        .export(quadMap, null);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getClockWise(), .5F))
                        .apply(Modifiers.cut(dir, .5F))
                        .apply(Modifiers.makeVerticalSlope(dir.getOpposite(), 45))
                        .apply(Modifiers.offset(yBackFace.getOpposite(), .5F))
                        .export(quadMap, null);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getOpposite(), .75F))
                        .apply(Modifiers.cut(dir, .5F))
                        .apply(Modifiers.cut(dir.getCounterClockWise(), 1F, 0F))
                        .apply(Modifiers.cut(dir.getClockWise(), .5F, 1.5F))
                        .apply(Modifiers.makeVerticalSlope(dir.getClockWise(), 45))
                        .apply(Modifiers.offset(yBackFace.getOpposite(), .5F))
                        .export(quadMap, null);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getClockWise(), .75F))
                        .apply(Modifiers.cut(dir.getCounterClockWise(), .5F))
                        .apply(Modifiers.cut(dir, 0F, 1F))
                        .apply(Modifiers.cut(dir.getOpposite(), 1.5F, .5F))
                        .apply(Modifiers.makeVerticalSlope(dir.getOpposite(), 45))
                        .apply(Modifiers.offset(yBackFace.getOpposite(), .5F))
                        .export(quadMap, null);
            }
        } else {
            if (quadDir == dir) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(yBackFace.getOpposite(), .5F))
                        .apply(Modifiers.cut(dir.getClockWise(), top ? .5F : -.5F, top ? -.5F : .5F))
                        .export(quadMap, quadDir);
            } else if (quadDir == dir.getCounterClockWise()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(yBackFace.getOpposite(), .5F))
                        .apply(Modifiers.cut(dir.getOpposite(), top ? .5F : -.5F, top ? -.5F : .5F))
                        .export(quadMap, quadDir);
            } else if (quadDir == yBackFace) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getOpposite(), .5F))
                        .apply(Modifiers.cut(dir.getClockWise(), -.5F, .5F))
                        .export(quadMap, quadDir);
            } else if (quadDir == dir.getOpposite()) {
                if (!right) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace.getOpposite(), .25F))
                            .apply(Modifiers.cut(dir.getClockWise(), top ? .5F : -.5F, top ? -.5F : .5F))
                            .apply(Modifiers.cut(dir.getCounterClockWise(), top ? 1F : 0F, top ? 0F : 1F))
                            .apply(Modifiers.makeHorizontalSlope(false, 45))
                            .apply(Modifiers.offset(dir, .5F))
                            .export(quadMap, null);
                }

                if (!altSlope) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace.getOpposite(), .5F))
                            .apply(Modifiers.cut(dir.getClockWise(), .25F))
                            .apply(Modifiers.cut(Direction.UP, top ? 1F : .5F, top ? 0F : -.5F))
                            .apply(Modifiers.cut(Direction.DOWN, top ? .5F : 1F, top ? -.5F : 0F))
                            .apply(Modifiers.makeVerticalSlope(!top, 45))
                            .apply(Modifiers.offset(dir, .5F))
                            .export(quadMap, null);
                }
            } else if (quadDir == dir.getClockWise()) {
                if (right) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace.getOpposite(), .25F))
                            .apply(Modifiers.cut(dir.getOpposite(), top ? .5F : -.5F, top ? -.5F : .5F))
                            .apply(Modifiers.cut(dir, top ? 1F : 0F, top ? 0F : 1F))
                            .apply(Modifiers.makeHorizontalSlope(true, 45))
                            .apply(Modifiers.offset(dir.getCounterClockWise(), .5F))
                            .export(quadMap, null);
                }

                if (!altSlope) {
                    QuadModifier.of(quad)
                            .apply(Modifiers.cut(yBackFace.getOpposite(), .5F))
                            .apply(Modifiers.cut(dir.getOpposite(), .25F))
                            .apply(Modifiers.cut(Direction.UP, top ? 0F : -.5F, top ? 1F : .5F))
                            .apply(Modifiers.cut(Direction.DOWN, top ? -.5F : 0F, top ? .5F : 1F))
                            .apply(Modifiers.makeVerticalSlope(!top, 45))
                            .apply(Modifiers.offset(dir.getCounterClockWise(), .5F))
                            .export(quadMap, null);
                }
            } else if (altSlope && quadDir == yBackFace.getOpposite()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getOpposite(), .25F))
                        .apply(Modifiers.cut(dir.getClockWise(), -.5F, .5F))
                        .apply(Modifiers.cut(dir.getCounterClockWise(), 1F, 0F))
                        .apply(Modifiers.makeVerticalSlope(dir.getClockWise(), 45))
                        .apply(Modifiers.offset(yBackFace, .5F))
                        .export(quadMap, null);

                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dir.getClockWise(), .25F))
                        .apply(Modifiers.cut(dir, 0F, 1F))
                        .apply(Modifiers.cut(dir.getOpposite(), .5F, -.5F))
                        .apply(Modifiers.makeVerticalSlope(dir.getOpposite(), 45))
                        .apply(Modifiers.offset(yBackFace, .5F))
                        .export(quadMap, null);
            }
        }
    }

public FramedCompoundSlopePanelGeometry(GeometryFactory.Context ctx) {
        this.dir = ctx.state().getValue(FramedProperties.FACING_HOR);
        this.rot = ctx.state().getValue(PropertyHolder.ROTATION);
        this.orientation = rot.withFacing(dir);
        this.triangleAxis = rot.rotate(Rotation.CLOCKWISE_90).withFacing(dir).getAxis();
        this.altSlope = ctx.state().getValue(FramedProperties.ALT_SLOPE);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        Direction quadDir = quad.direction();
        if (quadDir == orientation) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir.getOpposite(), .5F))
                    .export(quadMap, quadDir);

            if (altSlope && DirUtils.isY(quadDir)) {
                QuadModifier.of(quad)
                        .apply(Modifiers.makeVerticalSlope(dir.getOpposite(), FramedSlopePanelGeometry.SLOPE_ANGLE_VERT))
                        .apply(Modifiers.offset(dir.getOpposite(), .5F))
                        .export(quadMap, null);
            }
        } else if (quadDir == orientation.getOpposite()) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir, .5F))
                    .export(quadMap, quadDir);

            if (altSlope && DirUtils.isY(quadDir)) {
                QuadModifier.of(quad)
                        .apply(Modifiers.makeVerticalSlope(dir, FramedSlopePanelGeometry.SLOPE_ANGLE_VERT))
                        .apply(Modifiers.offset(dir, .5F))
                        .export(quadMap, null);
            }
        } else if (quadDir == dir) {
            if (!DirUtils.isY(orientation)) {
                QuadModifier.of(quad)
                        .apply(Modifiers.makeHorizontalSlope(rot == HorizontalRotation.LEFT, FramedSlopePanelGeometry.SLOPE_ANGLE))
                        .export(quadMap, null);
            } else if (!altSlope) {
                QuadModifier.of(quad)
                        .apply(Modifiers.makeVerticalSlope(rot == HorizontalRotation.DOWN, FramedSlopePanelGeometry.SLOPE_ANGLE))
                        .export(quadMap, null);
            }
        } else if (quadDir == dir.getOpposite()) {
            if (!DirUtils.isY(orientation)) {
                QuadModifier.of(quad)
                        .apply(Modifiers.makeHorizontalSlope(rot == HorizontalRotation.LEFT, FramedSlopePanelGeometry.SLOPE_ANGLE))
                        .export(quadMap, null);
            } else if (!altSlope) {
                QuadModifier.of(quad)
                        .apply(Modifiers.makeVerticalSlope(rot == HorizontalRotation.UP, FramedSlopePanelGeometry.SLOPE_ANGLE))
                        .export(quadMap, null);
            }
        } else if (triangleAxis == Direction.Axis.Y && DirUtils.isY(quadDir)) {
            boolean right = rot == HorizontalRotation.RIGHT;
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir, right ? 1F : .5F, right ? .5F : 1F))
                    .apply(Modifiers.cut(dir.getOpposite(), right ? 1F : .5F, right ? .5F : 1F))
                    .export(quadMap, quadDir);
        } else if (triangleAxis != Direction.Axis.Y && quadDir.getAxis() == triangleAxis) {
            boolean up = rot == HorizontalRotation.UP;
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir, up ? 1F : .5F, up ? .5F : 1F))
                    .apply(Modifiers.cut(dir.getOpposite(), up ? .5F : 1F, up ? 1F : .5F))
                    .export(quadMap, quadDir);
        }
    }

public FramedExtendedSlopePanelGeometry(GeometryFactory.Context ctx) {
        this.facing = ctx.state().getValue(FramedProperties.FACING_HOR);
        this.rotation = ctx.state().getValue(PropertyHolder.ROTATION);
        this.orientation = rotation.withFacing(facing);
        this.altSlope = ctx.state().getValue(FramedProperties.ALT_SLOPE);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        Direction face = quad.direction();
        boolean yAxis = DirUtils.isY(orientation);
        if (face == orientation) {
            if (DirUtils.isY(orientation)) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(facing.getOpposite(), .5F))
                        .export(quadMap, face);

                if (altSlope) {
                    QuadModifier.of(quad)
                            .apply(FramedSlopePanelGeometry.createVerticalSlope(facing, orientation))
                            .apply(Modifiers.offset(facing.getOpposite(), .5F))
                            .export(quadMap, null);
                }
            } else {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(facing.getOpposite(), .5F))
                        .export(quadMap, face);
            }
        } else if ((!rotation.isVertical() || !altSlope) && face == facing.getOpposite()) {
            QuadModifier.of(quad)
                    .apply(FramedSlopePanelGeometry.createSlope(facing, orientation))
                    .export(quadMap, null);
        } else if (face.getAxis() != facing.getAxis() && face.getAxis() != orientation.getAxis()) {
            if (yAxis) {
                boolean up = orientation == Direction.UP;
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(facing.getOpposite(), up ? .5F :  1F, up ?  1F : .5F))
                        .export(quadMap, face);
            } else {
                boolean rightRot = rotation == HorizontalRotation.RIGHT;
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(facing.getOpposite(), rightRot ?  1F : .5F, rightRot ? .5F :  1F))
                        .export(quadMap, face);
            }
        }
    }

