@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        Direction face = quad.direction();
        boolean offset = top != topHalf;

        if (!altSlope && face == facing.getOpposite()) {
            QuadModifier.of(quad)
                    .apply(Modifiers.makeVerticalSlope(!top, SLOPE_ANGLE))
                    .applyIf(Modifiers.offset(top ? Direction.DOWN : Direction.UP, .5F), offset)
                    .export(quadMap, null);
        } else if (altSlope && ((!top && face == Direction.UP) || (top && face == Direction.DOWN))) {
            QuadModifier.of(quad)
                    .apply(Modifiers.makeVerticalSlope(facing.getOpposite(), SLOPE_ANGLE_VERT))
                    .applyIf(Modifiers.offset(top ? Direction.UP : Direction.DOWN, .5F), !offset)
                    .export(quadMap, null);
        } else if (face == facing) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(topHalf ? Direction.DOWN : Direction.UP, .5F))
                    .export(quadMap, face);
        } else if (face == facing.getClockWise() || face == facing.getCounterClockWise()) {
            boolean rightFace = face == facing.getClockWise();
            float right = rightFace ? (offset ? .5F : 0) : (offset ? 1 : .5F);
            float left =  rightFace ? (offset ? 1 : .5F) : (offset ? .5F : 0);

            QuadModifier.of(quad)
                    .apply(Modifiers.cut(top ? Direction.DOWN : Direction.UP, right, left))
                    .applyIf(Modifiers.cut(top ? Direction.UP : Direction.DOWN, .5F), offset)
                    .export(quadMap, face);
        } else if ((top && !topHalf && face == Direction.UP) || (!top && topHalf && face == Direction.DOWN)) {
            QuadModifier.of(quad)
                    .apply(Modifiers.setPosition(.5F))
                    .export(quadMap, null);
        }
    }

public FramedSlopedStairsGeometry(GeometryFactory.Context ctx) {
        this.dir = ctx.state().getValue(FramedProperties.FACING_HOR);
        this.top = ctx.state().getValue(FramedProperties.TOP);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        Direction quadDir = quad.direction();

        if (DirUtils.isY(quadDir)) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir.getOpposite(), 1, 0))
                    .export(quadMap, quadDir);

            QuadModifier.of(quad)
                    .apply(Modifiers.cut(dir, 1, 0))
                    .apply(Modifiers.setPosition(.5F))
                    .export(quadMap, null);
        } else {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(top ? Direction.DOWN : Direction.UP, .5F))
                    .export(quadMap, quadDir);

            if (quadDir == dir.getOpposite()) {
                QuadModifier.of(quad)
                        .apply(Modifiers.makeHorizontalSlope(false, 45))
                        .apply(Modifiers.cut(top ? Direction.UP : Direction.DOWN, .5F))
                        .export(quadMap, null);
            }
        }
    }

public FramedVerticalSlopedStairsGeometry(GeometryFactory.Context ctx) {
        this.facing = ctx.state().getValue(FramedProperties.FACING_HOR);
        HorizontalRotation rot = ctx.state().getValue(PropertyHolder.ROTATION);
        this.rotDir = rot.withFacing(facing);
        this.rotDirTwo = rot.rotate(Rotation.COUNTERCLOCKWISE_90).withFacing(facing);
        this.altSlope = ctx.state().getValue(FramedProperties.ALT_SLOPE);
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        Direction quadDir = quad.direction();
        if (quadDir == rotDir || quadDir == rotDirTwo) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(facing.getOpposite(), .5F))
                    .export(quadMap, quadDir);
        } else if (quadDir == facing.getOpposite()) {
            QuadModifier.of(quad)
                    .apply(Modifiers.cutSide(rotDir, 1F, 0F))
                    .export(quadMap, quadDir);

            QuadModifier.of(quad)
                    .apply(Modifiers.cutSide(rotDir.getOpposite(), 1F, 0F))
                    .apply(Modifiers.setPosition(.5F))
                    .export(quadMap, null);
        }

        boolean useRotDirQuad = DirUtils.isY(rotDir) == altSlope;
        Direction slopeQuadDir = useRotDirQuad ? rotDir : rotDirTwo;
        Direction slopeRotDir = useRotDirQuad ? rotDirTwo : rotDir;

        if (quadDir == slopeQuadDir) {
            if (DirUtils.isY(slopeQuadDir)) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(facing, .5F))
                        .apply(Modifiers.makeVerticalSlope(slopeRotDir, 45F))
                        .export(quadMap, null);
            } else {
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(facing, .5F))
                        .apply(Modifiers.makeVerticalSlope(slopeRotDir == Direction.UP, 45F))
                        .export(quadMap, null);
            }
        }
    }

