public static Factory factory(BlockState state, boolean large) {
        AttachFace face = state.getValue(BlockStateProperties.ATTACH_FACE);
        if (large) {
            Direction facing = switch (face) {
                case FLOOR -> Direction.DOWN;
                case WALL -> state.getValue(BlockStateProperties.HORIZONTAL_FACING);
                case CEILING -> Direction.UP;
            };
            return LARGE_FACTORIES[facing.ordinal()];
        } else {
            Direction facing = state.getValue(BlockStateProperties.HORIZONTAL_FACING);
            return SMALL_FACTORIES[smallIndex(face, facing)];
        }
    }

private static int smallIndex(AttachFace face, Direction facing) {
        return switch (face) {
            case FLOOR -> facing.getAxis().ordinal();
            case CEILING -> facing.getAxis().ordinal() + 3;
            case WALL -> facing.get2DDataValue() + 6;
        };
    }

private static Factory[] makeSmallFactories() {
        Factory[] factories = new Factory[10];
        for (Direction.Axis axis : new Direction.Axis[] { Direction.Axis.X, Direction.Axis.Z }) {
            factories[smallIndex(AttachFace.FLOOR, axis.getPositive())] = makeSmallFactory(Direction.UP, axis);
            factories[smallIndex(AttachFace.CEILING, axis.getPositive())] = makeSmallFactory(Direction.DOWN, axis);
        }
        for (Direction dir : Direction.Plane.HORIZONTAL) {
            factories[smallIndex(AttachFace.WALL, dir)] = makeSmallFactory(dir, Direction.Axis.Y);
        }
        return factories;
    }

private static Factory makeSmallFactory(Direction facing, Direction.Axis wideAxis) {
        return ctx -> {
            if (!ClientConfig.VIEW.showButtonPlateOverlay()) {
                return null;
            }

            @Nullable Direction[] cullFaces = { facing.getOpposite(), null };
            Material.Baked matFront = ctx.materialLookup().getMaterial(FRAME_LOCATION_SMALL_FRONT);
            Material.Baked matNarrow = ctx.materialLookup().getMaterial(FRAME_LOCATION_SMALL_NARROW);
            Material.Baked matWide = ctx.materialLookup().getMaterial(FRAME_LOCATION_SMALL_WIDE);
            OverlayPartGenerator.MaterialGetter matGetter = dir -> {
                if (dir.getAxis() == facing.getAxis()) {
                    return matFront;
                }
                if (dir.getAxis() == wideAxis) {
                    return matWide;
                }
                return matNarrow;
            };
            return new StoneButtonOverlayProvider(cullFaces, matFront, matGetter);
        };
    }

private static Factory[] makeLargeFactories() {
        Factory[] factories = new Factory[6];
        for (Direction facing : Direction.values()) {
            @Nullable Direction[] cullFaces = new @Nullable Direction[] { facing.getOpposite(), null };
            factories[facing.ordinal()] = ctx -> {
                if (!ClientConfig.VIEW.showButtonPlateOverlay()) {
                    return null;
                }

                Material.Baked matFront = ctx.materialLookup().getMaterial(FRAME_LOCATION_LARGE_FRONT);
                Material.Baked matSide = ctx.materialLookup().getMaterial(FRAME_LOCATION_LARGE_SIDE);
                return new StoneButtonOverlayProvider(cullFaces, matFront, dir -> dir.getAxis() == facing.getAxis() ? matFront : matSide);
            };
        }
        return factories;
    }

private TrapdoorPostModifierProvider(Direction dir, boolean top) {
        this.dir = dir;
        this.topFace = top ? Direction.UP : Direction.DOWN;
        Direction.Axis rotAxis = dir.getClockWise().getAxis();
        boolean positive = DirUtils.isPositive(dir);
        float xzOrigin = positive ? 1.5F/16F : 14.5F/16F;
        Vector3f rotOrigin = new Vector3f(xzOrigin, top ? 14.5F/16F : 1.5F/16F, xzOrigin);
        float rotAngle = (positive ^ DirUtils.isZ(dir)) == top ? -90 : 90;
        this.modifier = Modifiers.rotate(rotAxis, rotOrigin, rotAngle, false);
    }

@Override
    public void collectPostModifiers(Direction normal, boolean cullable, Consumer<QuadModifier.Modifier> collector) {
        collector.accept(modifier);
    }

@Override
    public @Nullable Direction transformCullFace(Direction normal, @Nullable Direction cullface) {
        if (normal == topFace) {
            return null;
        }
        if (normal == topFace.getOpposite()) {
            return dir.getOpposite();
        }
        if (normal == dir) {
            return topFace.getOpposite();
        }
        if (normal == dir.getOpposite()) {
            return topFace;
        }
        return cullface;
    }

public static PostModifierProvider get(BlockState state) {
        Direction dir = state.getValue(BlockStateProperties.HORIZONTAL_FACING);
        Half half = state.getValue(BlockStateProperties.HALF);
        return PROVIDERS[index(dir, half)];
    }

private static int index(Direction dir, Half half) {
        return dir.get2DDataValue() + 4 * half.ordinal();
    }

private FramedLanternGeometry(GeometryFactory.Context ctx, boolean closedHead, BlockState auxShaderState) {
        this.state = ctx.state();
        this.hanging = ctx.state().getValue(BlockStateProperties.HANGING);
        this.chain = ctx.state().getValue(PropertyHolder.CHAIN_TYPE);
        this.closedHead = closedHead;
        this.baseModel = ctx.baseModel();
        this.auxShaderState = auxShaderState;
    }

@Override
    public void transformQuad(QuadMapBuilder quadMap, BakedQuad quad, FramedBlockData blockData, @Nullable Object modelData) {
        Direction quadDir = quad.direction();
        if (DirUtils.isY(quadDir)) {
            boolean up = quadDir == Direction.UP;

            QuadModifier.of(quad)
                    .apply(Modifiers.cutTopBottom(5F/16F, 5F/16F, 11F/16F, 11F/16F))
                    .applyIf(Modifiers.setPosition(15F/16F), hanging && !up)
                    .applyIf(Modifiers.setPosition(hanging ? 8F/16F : 7F/16F), up)
                    .export(quadMap, hanging || up ? null : Direction.DOWN);

            if (up) {
                QuadModifier.of(quad)
                        .apply(Modifiers.cutTopBottom(6F/16F, 6F/16F, 10F/16F, 10F/16F))
                        .apply(Modifiers.setPosition(hanging ? 10F/16F : 9F/16F))
                        .export(quadMap, null);
            }
        } else {
            List<QuadModifier> sideMods = List.of(
                    QuadModifier.of(quad).apply(Modifiers.cutSide(5F/16F, 0, 6F/16F, 7F/16F)),
                    QuadModifier.of(quad).apply(Modifiers.cutSide(10F/16F, 0, 11F/16F, 7F/16F)),
                    QuadModifier.of(quad).apply(Modifiers.cutSide(6F/16F, 0, 10F/16F, 1F/16F)),
                    QuadModifier.of(quad).apply(Modifiers.cutSide(6F/16F, 6F/16F, 10F/16F, 7F/16F))
            );
            for (QuadModifier mod : sideMods) {
                mod.applyIf(Modifiers.offset(Direction.UP, 1F/16F), hanging)
                        .apply(Modifiers.setPosition(11F/16F))
                        .export(quadMap, null);
            }

            QuadModifier.of(quad).apply(Modifiers.cutSide(6F/16F, closedHead ? 7F/16F : 8F/16F, 10F/16F, 9F/16F))
                    .applyIf(Modifiers.offset(Direction.UP, 1F/16F), hanging)
                    .apply(Modifiers.setPosition(10F/16F))
                    .export(quadMap, null);

            if (chain == ChainType.CAMO) {
                createCamoChain(quadMap, quad, quadDir);
            }
        }
    }

private void createCamoChain(QuadMapBuilder quadMap, BakedQuad quad, Direction quadDir) {
        Direction.Axis quadPerpAxis = DirUtils.isX(quadDir) ? Direction.Axis.Z : Direction.Axis.X;
        Direction dirNeg = quadPerpAxis.getNegative();
        Direction dirPos = quadPerpAxis.getPositive();

        List<MultiQuadModifier> modifiers = new ArrayList<>();
        MultiQuadModifier baseEdgeMod = new MultiQuadModifier(
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dirNeg, 10F/16F))
                        .apply(Modifiers.cut(dirPos,  7F/16F))
                        .apply(Modifiers.offset(dirPos, .5F/16F)),
                QuadModifier.of(quad)
                        .apply(Modifiers.cut(dirNeg,  7F/16F))
                        .apply(Modifiers.cut(dirPos, 10F/16F))
                        .apply(Modifiers.offset(dirNeg, .5F/16F))
        );

        if (DirUtils.isX(quadDir) || !hanging) {
            modifiers.add(
                    baseEdgeMod.derive()
                            .apply(Modifiers.cut(Direction.DOWN, hanging ? 6F/16F : 7F/16F))
                            .apply(Modifiers.cut(Direction.UP, hanging ? 12F/16F : 11F/16F))
            );
        }
        for (int i = 0; i < 2; i++) {
            if (!hanging && i == 0) continue;

            float height = i == 0 ? 2 : (hanging ? 5 : 6);
            QuadModifier.of(quad)
                    .apply(Modifiers.cut(quadDir.getClockWise().getAxis(), 8.5F/16F))
                    .apply(Modifiers.cut(Direction.DOWN, height / 16F))
                    .apply(Modifiers.cut(Direction.UP, (16F - height + 1F) / 16F))
                    .apply(Modifiers.setPosition(.5F))
                    .apply(Modifiers.rotate(Direction.Axis.Y, ROT_ORIGIN, 45, false))
                    .export(quadMap, null);
        }

        if (hanging) {
            if (DirUtils.isX(quadDir)) {
                modifiers.add(
                        baseEdgeMod.derive()
                                .apply(Modifiers.cut(Direction.DOWN, 2F/16F))
                );
            } else if (DirUtils.isZ(quadDir)) {
                modifiers.add(
                        baseEdgeMod.derive()
                                .apply(Modifiers.cut(Direction.DOWN, 5F/16F))
                                .apply(Modifiers.cut(Direction.UP, 15F/16F))

                );
            }
        }

        for (MultiQuadModifier mod : modifiers) {
            mod.apply(Modifiers.setPosition(.5F))
                    .apply(Modifiers.rotate(Direction.Axis.Y, ROT_ORIGIN, 45, false))
                    .export(quadMap, null);
        }

        baseEdgeMod.discard();
    }

