private int computeMaterialFlags() {
        int flags = 0;
        for (List<BakedQuad> list : quads) {
            for (BakedQuad quad : Objects.requireNonNull(list)) {
                flags |= quad.materialInfo().flags();
            }
        }
        return flags;
    }

