        if (sharedState != null) {
            template = sharedState.get(STATE_KEY).get(name);
        } else {
            template = templates.get(name);
        }
        if (template != null) {
            return template;
        }
        if (failedTemplates.add(name)) {
            LOGGER.error("No template loaded with name: {}", name);
        }
        return GeometryTemplate.SINGLE_CUBE;
    }

