    public boolean shouldRender(FramedItemFrameBlockEntity be, Vec3 cameraPos) {
        return be.hasItem() && BlockEntityRenderer.super.shouldRender(be, cameraPos);
    }

public FramedSignRenderer(BlockEntityRendererProvider.Context ctx) {
        this.font = ctx.font();
    }

@Override
    public void submit(FramedSignRenderState renderState, PoseStack poseStack, SubmitNodeCollector submitNodeCollector, CameraRenderState camera) {
        int light = renderState.lightCoords;
        Vector3f textOffset = renderState.textOffset;
        int lineHeight = renderState.lineHeight;
        int lineWidth = renderState.lineWidth;
        boolean outline = renderState.outline;

        poseStack.pushPose();
        applyTransforms(poseStack, renderState.yRot, renderState.standing);
        renderText(renderState.frontText, poseStack, submitNodeCollector, light, textOffset, lineHeight, lineWidth, outline, true);
        renderText(renderState.backText, poseStack, submitNodeCollector, light, textOffset, lineHeight, lineWidth, outline, false);
        poseStack.popPose();
    }

@Override
    public FramedSignRenderState createRenderState() {
        return new FramedSignRenderState();
    }

@Override
    public void extractRenderState(
            FramedSignBlockEntity blockEntity,
            FramedSignRenderState renderState,
            float partialTick,
            Vec3 cameraPos,
            ModelFeatureRenderer.@Nullable CrumblingOverlay crumblingOverlay
    ) {
        BlockEntityRenderer.super.extractRenderState(blockEntity, renderState, partialTick, cameraPos, crumblingOverlay);

        BlockState state = blockEntity.getBlockState();
        if (!(state.getBlock() instanceof SignBlock signBlock)) {
            return;
        }

        renderState.standing = state.getBlock() instanceof FramedStandingSignBlock;
        renderState.yRot = -signBlock.getYRotationDegrees(state);
        renderState.frontText = blockEntity.getText(true);
        renderState.backText = blockEntity.getText(false);
        renderState.textOffset = getTextOffset(signBlock);
        renderState.lineHeight = blockEntity.getTextLineHeight();
        renderState.lineWidth = blockEntity.getMaxTextLineWidth();
        renderState.outline = AbstractSignRenderer.isOutlineVisible(blockEntity.getBlockPos());
    }

@Override
    public AABB getRenderBoundingBox(FramedSignBlockEntity blockEntity) {
        if (blockEntity.getBlockState().getBlock() instanceof FramedStandingSignBlock) {
            BlockPos pos = blockEntity.getBlockPos();
            return new AABB(pos.getX(), pos.getY() + .625, pos.getZ(), pos.getX() + 1.0, pos.getY() + 1.125, pos.getZ() + 1.0);
        }
        return BlockEntityRenderer.super.getRenderBoundingBox(blockEntity);
    }

protected void applyTransforms(PoseStack poseStack, float yRot, boolean standing) {
        poseStack.translate(.5F, .75F * RENDER_SCALE, .5F);
        poseStack.mulPose(Axis.YP.rotationDegrees(yRot));
        if (!standing) {
            poseStack.translate(0F, -5F/16F, -7F/16F);
        }
    }

private void applyTextTransforms(PoseStack poseStack, Vector3f offset, boolean front) {
        if (!front) {
            poseStack.mulPose(Quaternions.YP_180);
        }

        poseStack.translate(offset.x, offset.y, offset.z);
        float scale = 0.015625F * getSignTextRenderScale();
        poseStack.scale(scale, -scale, scale);
    }

protected float getSignTextRenderScale() {
        return RENDER_SCALE;
    }

protected Vector3f getTextOffset(SignBlock signBlock) {
        boolean standing = signBlock instanceof FramedStandingSignBlock;
        return standing ? TEXT_OFFSET : WALL_TEXT_OFFSET;
    }

private void renderText(
            SignText text,
            PoseStack poseStack,
            SubmitNodeCollector submitNodeCollector,
            int light,
            Vector3f textOffset,
            int lineHeight,
            int lineWidth,
            boolean outlineVisible,
            boolean front
    ) {
        poseStack.pushPose();
        applyTextTransforms(poseStack, textOffset, front);

        int darkColor = AbstractSignRenderer.getDarkColor(text);
        int textColor;
        boolean outline;
        int textLight;
        if (text.hasGlowingText()) {
            textColor = text.getColor().getTextColor();
            outline = textColor == DyeColor.BLACK.getTextColor() || outlineVisible;
            textLight = LightCoordsUtil.FULL_BRIGHT;
        } else {
            textColor = darkColor;
            outline = false;
            textLight = light;
        }

        boolean filter = Minecraft.getInstance().isTextFilteringEnabled();
        FormattedCharSequence[] lines = text.getRenderMessages(filter, line -> {
            List<FormattedCharSequence> parts = font.split(line, lineWidth);
            return parts.isEmpty() ? FormattedCharSequence.EMPTY : parts.getFirst();
        });

        int centerY = 4 * lineHeight / 2;
        for (int idx = 0; idx < 4; ++idx) {
            FormattedCharSequence line = lines[idx];
            float textX = (float) -font.width(line) / 2;
            float textY = idx * lineHeight - centerY;
            submitNodeCollector.submitText(poseStack, textX, textY, line, false, Font.DisplayMode.POLYGON_OFFSET, textLight, textColor, 0, outline ? darkColor : 0);
        }

        poseStack.popPose();
    }

public FramedTankRenderer(@SuppressWarnings("unused") BlockEntityRendererProvider.Context ctx) {
        this.fluidModels = Minecraft.getInstance().getModelManager().getFluidStateModelSet();
    }

@Override
    public void submit(FramedTankRenderState renderState, PoseStack poseStack, SubmitNodeCollector submitNodeCollector, CameraRenderState camera) {
        int fluidAmount = renderState.fluidAmount;
        if (fluidAmount != 0) {
            FluidModel model = renderState.fluidModel;
            boolean lighterThanAir = renderState.lighterThanAir;
            boolean gaseous = renderState.gaseous;
            int tint = renderState.tint;
            int lightCoords = renderState.lightCoords;
            int fluidLight = renderState.fluidLightEmission;
            submitContents(poseStack, submitNodeCollector, model, fluidAmount, lighterThanAir, gaseous, tint, lightCoords, fluidLight);
        }
    }

@Override
    public FramedTankRenderState createRenderState() {
        return new FramedTankRenderState();
    }

@Override
    public void extractRenderState(
            FramedTankBlockEntity blockEntity,
            FramedTankRenderState renderState,
            float partialTick,
            Vec3 cameraPos,
            ModelFeatureRenderer.@Nullable CrumblingOverlay crumblingOverlay
    ) {
        BlockEntityRenderer.super.extractRenderState(blockEntity, renderState, partialTick, cameraPos, crumblingOverlay);

        FluidStack fluid = blockEntity.getContents();
        if (fluid.isEmpty() || !blockEntity.hasLevel()) {
            return;
        }

        FluidState fluidState = fluid.getFluid().defaultFluidState();
        FluidType fluidType = fluid.getFluidType();

        FluidModel fluidModel = fluidModels.get(fluidState);
        renderState.fluidModel = fluidModel;
        renderState.fluidAmount = fluid.getAmount();
        renderState.lighterThanAir = fluidType.isLighterThanAir();
        renderState.gaseous = fluid.is(Tags.Fluids.GASEOUS);
        FluidTintSource tintSource = fluidModel.fluidTintSource();
        renderState.tint = tintSource != null ? tintSource.colorAsStack(fluid) : -1;
        renderState.fluidLightEmission = fluidType.getLightLevel(fluid);
    }

public static void submitContents(
            PoseStack poseStack,
            SubmitNodeCollector collector,
            FluidModel fluidModel,
            int fluidAmount,
            boolean lighterThanAir,
            boolean gaseous,
            int tint,
            int light,
            int fluidLight
    ) {
        TextureAtlasSprite stillTex = fluidModel.stillMaterial().sprite();
        TextureAtlasSprite flowTex = fluidModel.flowingMaterial().sprite();
        float fillState = fluidAmount / (float) TankFluidResourceHandler.CAPACITY;
        float height;
        int finalTint;
        if (gaseous) {
            height = 1F - OFFSET;
            finalTint = ARGB.multiplyAlpha(tint, fillState);
        } else {
            height = Mth.clamp(fillState, OFFSET, 1F - OFFSET);
            finalTint = tint;
        }
        int finalLight = LightCoordsUtil.lightCoordsWithEmission(light, fluidLight);
        boolean sameTex = stillTex == flowTex;

        // FIXME: translucent fluids (regardless of no-shade) break outlines with Improved Translucency and break translucent chunk geometry without Improved Translucency
        RenderType bufferType = FramedRenderTypes.getEntityRenderType(gaseous ? ChunkSectionLayer.TRANSLUCENT : fluidModel.layer(), fluidLight > 0);
        collector.submitCustomGeometry(poseStack, bufferType, (pose, consumer) -> {
            float minY;
            float maxY;
            if (lighterThanAir && !gaseous) {
                minY = 1F - height;
                maxY = 1F - OFFSET;
            } else {
                minY = OFFSET;
                maxY = height;
            }

            float minU = flowTex.getU(MIN_XZ);
            float maxU = sameTex ? flowTex.getU(MAX_XZ) : flowTex.getU(8F / 16F - OFFSET);
            float minV = sameTex ? flowTex.getV(1F - height) : flowTex.getV(8F / 16F * (1F - height));
            float maxV = sameTex ? flowTex.getV(MAX_XZ) : flowTex.getV(8F / 16F - OFFSET);

            for (Direction face : HOR_FACES) {
                renderFace(pose, consumer, face, minY, maxY, minU, minV, maxU, maxV, finalTint, finalLight);
            }

            minU = stillTex.getU(MIN_XZ);
            maxU = stillTex.getU(MAX_XZ);
            minV = stillTex.getV(MIN_XZ);
            maxV = stillTex.getV(MAX_XZ);

            for (Direction face : VERT_FACES) {
                renderFace(pose, consumer, face, minY, maxY, minU, minV, maxU, maxV, finalTint, finalLight);
            }
        });
    }

private static void renderFace(PoseStack.Pose pose, VertexConsumer buffer, Direction face, float minY, float maxY, float minU, float minV, float maxU, float maxV, int tint, int light) {
        ExtFaceInfo faceInfo = ExtFaceInfo.of(face);
        for (int i = 0; i < 4; i++) {
            ExtFaceInfo.ExtVertexInfo vertex = faceInfo.vertex(i);
            float x = vertex.xFace().select(MIN_XZ, minY, MIN_XZ, MAX_XZ, maxY, MAX_XZ);
            float y = vertex.yFace().select(MIN_XZ, minY, MIN_XZ, MAX_XZ, maxY, MAX_XZ);
            float z = vertex.zFace().select(MIN_XZ, minY, MIN_XZ, MAX_XZ, maxY, MAX_XZ);
            float u = vertex.uFace().select(minU, minV, maxU, maxV);
            float v = vertex.vFace().select(minU, minV, maxU, maxV);
            buffer.addVertex(pose, x, y, z).setColor(tint).setUv(u, v).setOverlay(OverlayTexture.NO_OVERLAY).setLight(light).setNormal(pose, face.getUnitVec3f());
        }
    }

