public static void onRenderBlockHighlight(ExtractBlockOutlineRenderStateEvent event) {
        if (!ClientConfig.VIEW.useFancySelectionBoxes() && !DevToolsConfig.VIEW.isOcclusionShapeDebugRenderingEnabled()) {
            return;
        }

        BlockHitResult result = event.getHitResult();
        ClientLevel level = Objects.requireNonNull(Minecraft.getInstance().level);
        BlockState state = level.getBlockState(result.getBlockPos());
        if (!(state.getBlock() instanceof IFramedBlock block)) {
            return;
        }

        if (DevToolsConfig.VIEW.isOcclusionShapeDebugRenderingEnabled()) {
            BlockState newState = state;
            if (newState.hasProperty(FramedProperties.SOLID)) {
                newState = newState.setValue(FramedProperties.SOLID, true);
            }
            event.getLevelRenderState().blockOutlineRenderState = new BlockOutlineRenderState(
                    result.getBlockPos(),
                    event.isInTranslucentPass(),
                    event.isHighContrast(),
                    newState.getOcclusionShape(),
                    List.of()
            );
            event.setCanceled(true);
            return;
        }

        IBlockType type = block.getBlockType();
        if (type.hasSpecialOutline()) {
            OutlineRenderer<Object> renderer = getRenderer(type);
            if (renderer == null) {
                if (ERRORED_TYPES.add(type)) {
                    LOGGER.error("IBlockType '{}' requests custom outline rendering but no OutlineRender was registered!", type.getName());
                }
                return;
            }

            Object data = renderer.extractOutlineData(state, level, result.getBlockPos());
            if (data == null) {
                return;
            }

            Vec3 offset = Vec3.atLowerCornerOf(result.getBlockPos()).subtract(event.getCamera().position());
            boolean highContrast = event.isHighContrast();
            event.addCustomRenderer((renderState, buffer, poseStack, translucentPass, _) -> {
                if (translucentPass == renderState.isTranslucent()) {
                    poseStack.pushPose();
                    poseStack.translate(offset.x, offset.y, offset.z);
                    poseStack.translate(.5, .5, .5);
                    renderer.rotateMatrix(poseStack, state);
                    poseStack.translate(-.5, -.5, -.5);

                    AbstractLineDrawer drawer = createDrawer(poseStack.last(), buffer, highContrast);
                    renderer.draw(state, data, drawer);
                    drawer.finish();

                    poseStack.popPose();
                }
                return true;
            });
        }
    }

@SuppressWarnings("unchecked")
    private static @Nullable OutlineRenderer<Object> getRenderer(IBlockType type) {
        return (OutlineRenderer<Object>) OUTLINE_RENDERERS.get(type);
    }

private static AbstractLineDrawer createDrawer(PoseStack.Pose pose, MultiBufferSource buffer, boolean highContrast) {
        if (highContrast) {
            return new HighContrastLineDrawer(pose, buffer);
        }
        return new DefaultLineDrawer(pose, buffer.getBuffer(RenderTypes.lines()), DEFAULT_LINE_COLOR);
    }

public static void init() {
        ModLoader.postEvent(new RegisterOutlineRenderersEvent((type, renderer) -> {
            Preconditions.checkArgument(type.hasSpecialOutline(), "IBlockType %s returns false from IBlockType#hasSpecialOutline()", type);
            OUTLINE_RENDERERS.put(type, renderer);
        }));
    }

public static boolean hasOutlineRenderer(IBlockType type) {
        return OUTLINE_RENDERERS.containsKey(type);
    }

AbstractLineDrawer(PoseStack.Pose pose) {
            this.pose = pose;
            this.lineWidth = Minecraft.getInstance().getWindow().getAppropriateLineWidth();
        }

final void drawLine(VertexConsumer builder, float x1, float y1, float z1, float x2, float y2, float z2, int color, float lineWidth) {
            float nX = x2 - x1;
            float nY = y2 - y1;
            float nZ = z2 - z1;
            float nLen = Mth.sqrt(nX * nX + nY * nY + nZ * nZ);

            nX = nX / nLen;
            nY = nY / nLen;
            nZ = nZ / nLen;

            builder.addVertex(pose, x1, y1, z1).setColor(color).setNormal(pose, nX, nY, nZ).setLineWidth(lineWidth);
            builder.addVertex(pose, x2, y2, z2).setColor(color).setNormal(pose, nX, nY, nZ).setLineWidth(lineWidth);
        }

DefaultLineDrawer(PoseStack.Pose pose, VertexConsumer builder, int lineColor) {
            super(pose);
            this.builder = builder;
            this.lineColor = lineColor;
        }

@Override
        public void drawLine(float x1, float y1, float z1, float x2, float y2, float z2) {
            drawLine(builder, x1, y1, z1, x2, y2, z2, lineColor, lineWidth);
        }

@Override
        public void drawLines(float[] vertices) {
            for (int i = 0; i < vertices.length; i += 6) {
                drawLine(vertices[i], vertices[i + 1], vertices[i + 2], vertices[i + 3], vertices[i + 4], vertices[i + 5]);
            }
        }

HighContrastLineDrawer(PoseStack.Pose pose, MultiBufferSource buffer) {
            super(pose);
            this.buffer = buffer;
            this.lines = new float[INITIAL_LINE_COUNT * LINE_STRIDE];
        }

@Override
        public void drawLine(float x1, float y1, float z1, float x2, float y2, float z2) {
            ensureCapacity(pointer + LINE_STRIDE);

            lines[pointer] = x1;
            lines[pointer + 1] = y1;
            lines[pointer + 2] = z1;
            lines[pointer + 3] = x2;
            lines[pointer + 4] = y2;
            lines[pointer + 5] = z2;

            pointer += LINE_STRIDE;
        }

@Override
        public void drawLines(float[] vertices) {
            Preconditions.checkArgument(vertices.length % LINE_STRIDE == 0, STRIDE_ERROR);

            ensureCapacity(pointer + vertices.length);
            System.arraycopy(vertices, 0, lines, pointer, vertices.length);
            pointer += vertices.length;
        }

private void ensureCapacity(int size) {
            if (size > lines.length) {
                int newSize = Math.max(lines.length + (INITIAL_LINE_COUNT * LINE_STRIDE), size);
                float[] newLines = new float[newSize];
                System.arraycopy(lines, 0, newLines, 0, lines.length);
                lines = newLines;
            }
        }

@Override
        void finish() {
            drawBufferedLines(RenderTypes.secondaryBlockOutline(), CommonColors.BLACK, 7F);
            drawBufferedLines(RenderTypes.lines(), CommonColors.HIGH_CONTRAST_DIAMOND, lineWidth);
        }

private void drawBufferedLines(RenderType renderType, int color, float lineWidth) {
            VertexConsumer builder = buffer.getBuffer(renderType);
            for (int i = 0; i < pointer; i += LINE_STRIDE) {
                drawLine(builder, lines[i], lines[i + 1], lines[i + 2], lines[i + 3], lines[i + 4], lines[i + 5], color, lineWidth);
            }
        }

public static void onRenderBlockHighlight(ExtractBlockOutlineRenderStateEvent event) {
        Player player = Objects.requireNonNull(Minecraft.getInstance().player);
        if (!player.getMainHandItem().is(FBContent.ITEM_FRAMED_HAMMER)) {
            return;
        }

        Level level = Objects.requireNonNull(Minecraft.getInstance().level);
        BlockHitResult hit = event.getHitResult();
        BlockPos pos = hit.getBlockPos();
        BlockState state = level.getBlockState(pos);
        if (!state.is(FBContent.BLOCK_FRAMED_COLLAPSIBLE_BLOCK)) {
            return;
        }
        if (!(level.getBlockEntity(pos) instanceof FramedCollapsibleBlockEntity be)) {
            return;
        }

        HammerTarget target = TargetCalculator.computeTarget(be, player, hit, true, 1F);
        if (target == null) {
            return;
        }

        Vec3 offset = Vec3.atLowerCornerOf(pos).subtract(event.getCamera().position());
        float[] vY = TargetCalculator.getVertexHeights(be, be.getCollapsedFace());

        event.addCustomRenderer((_, buffer, poseStack, translucentPass, _) -> {
            if (translucentPass) {
                poseStack.pushPose();
                poseStack.translate(offset.x + .5, offset.y + .5, offset.z + .5);
                if (target.face() == Direction.DOWN) {
                    poseStack.mulPose(Quaternions.XP_180);
                } else if (target.face() != Direction.UP) {
                    poseStack.mulPose(OutlineRenderer.YN_DIR[target.face().get2DDataValue()]);
                    poseStack.mulPose(Quaternions.XP_90);
                }
                poseStack.translate(-.5, -.5, -.5);

                OutlineRenderer.LineDrawer drawer = new BlockOutlineRenderer.DefaultLineDrawer(
                        poseStack.last(), buffer.getBuffer(FramedRenderTypes.LINES_NO_DEPTH), LINE_COLOR
                );
                drawSectionOverlay(drawer, vY);
                drawCornerMarkers(drawer, target.face(), target.pos(), vY);

                poseStack.popPose();
            }
            return false;
        });
    }

private static void drawSectionOverlay(OutlineRenderer.LineDrawer drawer, float[] vY) {
        float cenx = Mth.lerp(.5F, vY[0], vY[1]); // center edge negative X
        float cepx = Mth.lerp(.5F, vY[3], vY[2]); // center edge positive X
        float cenz = Mth.lerp(.5F, vY[0], vY[3]); // center edge negative Z
        float cepz = Mth.lerp(.5F, vY[1], vY[2]); // center edge positive Z

        float cinx = Mth.lerp(.25F, cenx, cepx); // center inset negative X
        float cipx = Mth.lerp(.75F, cenx, cepx); // center inset positive X
        float cinz = Mth.lerp(.25F, cenz, cepz); // center inset negative Z
        float cipz = Mth.lerp(.75F, cenz, cepz); // center inset positive Z

        drawer.drawLine( .5F, cenz,   0F,  .5F, cinz, .25F);
        drawer.drawLine( .5F, cipz, .75F,  .5F, cepz,   1F);
        drawer.drawLine(  0F, cenx,  .5F, .25F, cinx,  .5F);
        drawer.drawLine(.75F, cipx,  .5F,   1F, cepx,  .5F);

        drawer.drawLine(.5F, cinz, .25F, .25F, cinx, .5F);
        drawer.drawLine(.5F, cinz, .25F, .75F, cipx, .5F);
        drawer.drawLine(.5F, cipz, .75F, .25F, cinx, .5F);
        drawer.drawLine(.5F, cipz, .75F, .75F, cipx, .5F);
    }

private static void drawCornerMarkers(OutlineRenderer.LineDrawer drawer, Direction faceDir, Vec3 hitLocation, float[] vY) {
        int vert = FramedCollapsibleBlockEntity.vertexFromHit(faceDir, MathUtils.fraction(hitLocation));
        if (vert == 0 || vert == 4) {
            drawCubeFrame(drawer,  0.25F/16F,  0.25F/16F, vY[0]);
        }
        if (vert == 1 || vert == 4) {
            drawCubeFrame(drawer,  0.25F/16F, 15.75F/16F, vY[1]);
        }
        if (vert == 2 || vert == 4) {
            drawCubeFrame(drawer, 15.75F/16F, 15.75F/16F, vY[2]);
        }
        if (vert == 3 || vert == 4) {
            drawCubeFrame(drawer, 15.75F/16F,  0.25F/16F, vY[3]);
        }
    }

private static void drawCubeFrame(OutlineRenderer.LineDrawer drawer, float x, float z, float vY) {
        float minX = x - .5F/16F;
        float maxX = x + .5F/16F;
        float minZ = z - .5F/16F;
        float maxZ = z + .5F/16F;

        float minY = vY - .75F/16F;
        float maxY = vY + .25F/16F;

        // Bottom
        drawer.drawLine(minX, minY, minZ, minX, minY, maxZ);
        drawer.drawLine(minX, minY, minZ, maxX, minY, minZ);
        drawer.drawLine(maxX, minY, minZ, maxX, minY, maxZ);
        drawer.drawLine(minX, minY, maxZ, maxX, minY, maxZ);

        // Top
        drawer.drawLine(minX, maxY, minZ, minX, maxY, maxZ);
        drawer.drawLine(minX, maxY, minZ, maxX, maxY, minZ);
        drawer.drawLine(maxX, maxY, minZ, maxX, maxY, maxZ);
        drawer.drawLine(minX, maxY, maxZ, maxX, maxY, maxZ);

        // Vertical
        drawer.drawLine(minX, minY, minZ, minX, maxY, minZ);
        drawer.drawLine(minX, minY, maxZ, minX, maxY, maxZ);
        drawer.drawLine(maxX, minY, minZ, maxX, maxY, minZ);
        drawer.drawLine(maxX, minY, maxZ, maxX, maxY, maxZ);
    }

public static void onExtractRenderState(ExtractLevelRenderStateEvent event) {
        if (!ClientConfig.VIEW.isDoubleBlockPartIndicatorEnabled()) {
            return;
        }

        HitResult hit = Minecraft.getInstance().hitResult;
        if (!(hit instanceof BlockHitResult blockHit)) {
            return;
        }

        ClientLevel level = Objects.requireNonNull(Minecraft.getInstance().level);
        BlockPos pos = blockHit.getBlockPos();
        if (!(level.getBlockEntity(pos) instanceof FramedDoubleBlockEntity be)) {
            return;
        }

        Player player = Objects.requireNonNull(Minecraft.getInstance().player);
        boolean secondary = be.debugHitSecondary(blockHit, player);
        BlockPartRenderState partRenderState = new BlockPartRenderState(pos, secondary ? COLOR_SECONDARY : COLOR_PRIMARY);

        ModelData modelData = be.getModelData().derive().with(AbstractFramedBlockData.PROPERTY, MODEL_DATA.get()).build();
        BlockDisplayContext context = new FramedBlockDisplayContext(level, be.getBlockPos(), be.getBlockState(), modelData);
        Minecraft.getInstance().getBlockModelResolver().update(partRenderState, be.getParts().get(secondary), context);

        LevelRenderState renderState = event.getRenderState();
        renderState.haveGlowingEntities = true;
        renderState.setRenderData(DATA_KEY, partRenderState);
    }

public static void onSubmitCustomGeometry(SubmitCustomGeometryEvent event) {
        LevelRenderState levelRenderState = event.getLevelRenderState();
        BlockPartRenderState data = levelRenderState.getRenderData(DATA_KEY);
        if (data != null) {
            PoseStack poseStack = event.getPoseStack();
            Vec3 offset = Vec3.atLowerCornerOf(data.pos).subtract(levelRenderState.cameraRenderState.pos);
            poseStack.pushPose();
            poseStack.translate(offset.x, offset.y, offset.z);

            data.submitOnlyOutline(poseStack, event.getSubmitNodeCollector(), LightCoordsUtil.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, data.color);

            poseStack.popPose();
        }
    }

