@Override
    public void extractContents(GuiGraphicsExtractor graphics, int mouseX, int mouseY, float partialTick) {
        super.extractContents(graphics, mouseX, mouseY, partialTick);

        graphics.enableScissor(listContent.x0(), listContent.y0(), listContent.x1(), listContent.y1());
        int entryY = listContent.y0() - scrollOffset;
        for (Holder<BlockOverlay> overlay : overlayCache.getOverlays()) {
            if (entryY + ENTRY_HEIGHT > listContent.y0() && entryY <= listContent.y1()) {
                graphics.blitSprite(RenderPipelines.GUI_TEXTURED, ENTRY_BACKGROUND, listContent.x0(), entryY, listContent.width(), ENTRY_HEIGHT);

                TextureAtlasSprite sprite = blockAtlas.getSprite(overlay.value().solidTexture());
                int tint = TintUtils.getOverlayDefaultTint(overlay.value());
                graphics.blitSprite(RenderPipelines.GUI_TEXTURED, sprite, listContent.x0() + ENTRY_PADDING, entryY + ENTRY_PADDING, ICON_SIZE, ICON_SIZE, tint);

                Component name = BlockOverlay.getName(overlay);
                Component styledName = name.copy().withStyle(style -> style.withColor(CommonColors.DARK_GRAY).withoutShadow());
                graphics.drawScrollingString(graphics.textRenderer(), font, styledName, listContent.x0() + DETAILS_OFF_X, listContent.x1() - ENTRY_PADDING, entryY + ENTRY_PADDING);

                ItemStack srcItem = overlay.value().sourceItem().value().getDefaultInstance();
                graphics.pose().pushMatrix();
                graphics.pose().translate(listContent.x0() + DETAILS_OFF_X, entryY + ITEM_OFF_Y);
                graphics.pose().scale(.5F, .5F);
                graphics.fakeItem(srcItem, 0, 0);
                graphics.pose().popMatrix();

                if (listContent.contains(mouseX, mouseY) && mouseY >= entryY && mouseY < entryY + ENTRY_HEIGHT) {
                    Component itemName = srcItem.getItemName().copy().withStyle(ChatFormatting.WHITE);
                    List<Component> lines = List.of(
                            name,
                            Component.translatable(LABEL_SOURCE_ITEM, itemName).withStyle(ChatFormatting.GOLD)
                    );
                    graphics.setTooltipForNextFrame(font, lines, Optional.empty(), mouseX, mouseY);
                }
            }
            entryY += ENTRY_HEIGHT;
        }
        graphics.disableScissor();

        if (needScroller) {
            int scrollX = listContent.x1();
            float scrollFactor = scrollOffset / (float) (totalListHeight - LIST_INNER_HEIGHT);
            int scrollY = listContent.y0() + (int) ((LIST_INNER_HEIGHT - SCROLLER_HEIGHT) * scrollFactor);
            graphics.blitSprite(RenderPipelines.GUI_TEXTURED, Utils.id("minecraft", "container/villager/scroller"), scrollX, scrollY, SCROLLER_WIDTH, SCROLLER_HEIGHT);
        }
    }

@Override
    public boolean mouseClicked(MouseButtonEvent event, boolean doubleClick) {
        if (event.button() == InputConstants.MOUSE_BUTTON_LEFT && scrollBar.contains((int) event.x(), (int) event.y())) {
            setDragging(true);
            return true;
        }
        return super.mouseClicked(event, doubleClick);
    }

@Override
    public boolean mouseScrolled(double x, double y, double scrollX, double scrollY) {
        if (listArea.contains((int) x, (int) y)) {
            scrollOffset = Math.clamp(scrollOffset - (int) (scrollY * 10), 0, maxScrollOffset);
            return true;
        }
        return super.mouseScrolled(x, y, scrollX, scrollY);
    }

@Override
    public boolean mouseDragged(MouseButtonEvent event, double dx, double dy) {
        if (isDragging()) {
            double yRel = Math.clamp(event.y() - scrollBar.y0() - (SCROLLER_HEIGHT / 2D), 0, SCROLLER_DRAG_HEIGHT);
            scrollOffset = (int) Math.round(maxScrollOffset * (yRel / SCROLLER_DRAG_HEIGHT));
            return true;
        }
        return super.mouseDragged(event, dx, dy);
    }

@Override
    public void render(GuiGraphicsExtractor graphics, DeltaTracker delta) {
        Player player = Objects.requireNonNull(Minecraft.getInstance().player);
        if (player.isSpectator() || Minecraft.getInstance().options.hideGui) {
            return;
        }

        OverlayDisplayMode cfgMode = ClientConfig.VIEW.getMaxOverlayMode();
        String renderedOverlay = null;
        for (BlockInteractOverlayWrapper overlay : OVERLAYS) {
            if (overlay.render(graphics, player, cfgMode)) {
                if (Utils.PRODUCTION) {
                    break;
                }

                if (renderedOverlay != null) {
                    String msg = "Only one overlay may be active at any time, encountered collision between '%s' and '%s'"
                            .formatted(renderedOverlay, overlay.getName());
                    throw new IllegalStateException(msg);
                }
                renderedOverlay = overlay.getName();
            }
        }
    }

public static void init() {
        Map<String, BlockInteractOverlay> overlays = new HashMap<>();
        ModLoader.postEvent(new RegisterBlockInteractOverlaysEvent((name, overlay) -> {
            BlockInteractOverlay prevOverlay = overlays.put(name, overlay);
            if (prevOverlay != null) {
                throw new IllegalStateException(String.format(
                        Locale.ROOT, "Duplicate overlay registration for name: %s (old: %s, new: %s)", name, prevOverlay, overlay
                ));
            }
            OVERLAYS.add(new BlockInteractOverlayWrapper(name, overlay));
        }
        ));
    }

private static void onResourceReload(@SuppressWarnings("unused") ResourceManager manager) {
        OVERLAYS.forEach(overlay -> overlay.textWidthValid = false);
    }

BlockInteractOverlayWrapper(String name, BlockInteractOverlay overlay) {
        this.name = name;
        this.overlay = overlay;
    }

boolean render(GuiGraphicsExtractor graphics, Player player, OverlayDisplayMode cfgMode) {
        OverlayDisplayMode mode = cfgMode.constrain(overlay.getDisplayMode());
        if (mode == OverlayDisplayMode.HIDDEN) {
            return false;
        }

        ItemStack stack = player.getMainHandItem();
        if (!overlay.isValidTool(player, stack)) {
            return false;
        }

        BlockInteractOverlay.Target target = getTargettedBlock(player);
        if (target == null || !overlay.isValidTarget(target)) {
            return false;
        }

        boolean state = overlay.getState(target);
        int screenWidth = graphics.guiWidth();
        int screenHeight = graphics.guiHeight();
        int centerX = screenWidth / 2;
        int centerY = screenHeight / 2;

        BlockInteractOverlay.Texture tex = overlay.getTexture(target, state);
        int texX = centerX + ICON_MARGIN;
        int texY = centerY - (tex.height() / 2);
        tex.draw(graphics, texX, texY);
        overlay.renderAfterIcon(graphics, tex, texX, texY, target);

        if (isDetailedVisible(mode, player)) {
            List<Component> lines = overlay.getLines(target, state);
            renderDetailed(graphics, tex, lines, centerX, screenHeight, target);
        }

        return true;
    }

private static boolean isDetailedVisible(OverlayDisplayMode mode, Player player) {
        return switch (mode) {
            case HIDDEN, ICON -> false;
            case DETAILED_TOGGLE -> player.isShiftKeyDown();
            case DETAILED_ALWAYS -> true;
        };
    }

private void renderDetailed(
            GuiGraphicsExtractor graphics,
            BlockInteractOverlay.Texture tex,
            List<Component> lines,
            int centerX,
            int screenHeight,
            BlockInteractOverlay.Target target
    ) {
        Font font = Minecraft.getInstance().font;
        if (!textWidthValid) {
            updateTextWidth(font);
        }

        Gui gui = Minecraft.getInstance().gui;
        int lineHeight = font.lineHeight + LINE_DIST;
        int count = lines.size();
        int contentHeight = count * lineHeight - LINE_DIST;

        int width = textWidth + tex.width() + PADDING;
        int height = Math.max(contentHeight, tex.height());
        int minY = screenHeight / 2 + tex.height() / 2;
        int maxY = screenHeight - Math.min(gui.leftHeight, gui.rightHeight);
        int x = centerX - (width / 2);
        int y = Math.max(screenHeight - DEFAULT_Y_OFF - height, minY + TOOLTIP_MARGIN);
        if (y + height > maxY - TOOLTIP_MARGIN) {
            return;
        }

        drawTooltipBackground(graphics, x, y, width, height);

        int textX = x + tex.width() + PADDING;
        int yBaseOff = tex.height() > contentHeight ? ((tex.height() - contentHeight) / 2) : 0;
        for (int i = 0; i < count; i++) {
            Component text = lines.get(i);
            int yOff = yBaseOff + lineHeight * i;
            graphics.text(font, text, textX, y + yOff, -1);
        }

        int texY = y + (height / 2) - (tex.height() / 2);
        tex.draw(graphics, x, texY);
        overlay.renderAfterIcon(graphics, tex, x, texY, target);
    }

private void updateTextWidth(Font font) {
        textWidth = 0;
        for (Component line : overlay.getAllLines()) {
            textWidth = Math.max(textWidth, font.width(line));
        }
        textWidthValid = true;
    }

