private static BlockInteractOverlay.@Nullable Target getTargettedBlock(Player player) {
        HitResult hit = Minecraft.getInstance().hitResult;
        if (hit instanceof BlockHitResult blockHit) {
            Level level = player.level();
            BlockPos pos = blockHit.getBlockPos();
            return new BlockInteractOverlay.Target(level, pos, level.getBlockState(pos), blockHit.getDirection(), player);
        }
        return null;
    }

private static void drawTooltipBackground(GuiGraphicsExtractor graphics, int x, int y, int width, int height) {
        TooltipRenderUtil.extractTooltipBackground(graphics, x - 2, y - 2, width + 4, height + 4, null);
    }

@Override
    public void render(GuiGraphicsExtractor graphics, DeltaTracker deltaTracker) {
        Player player = Minecraft.getInstance().player;
        if (player == null || (!(player.getMainHandItem().getItem() instanceof IFramedBlockItem blockItem)) || !blockItem.isStateCyclingActive(player)) {
            return;
        }

        List<Component> lines = new ArrayList<>();
        blockItem.getStateCycleSpec().appendHoverText(player, (BlockItem) blockItem, lines::add);
        if (lines.isEmpty()) {
            return;
        }

        lines.addFirst(IFramedBlockItem.HEADER_SELECTED_STATE);

        Font font = Minecraft.getInstance().font;
        int lineHeight = font.lineHeight + 1;

        int width = 0;
        for (Component line : lines) {
            width = Math.max(width, font.width(line));
        }
        int height = lineHeight * lines.size() - 1;
        int x = PADDING;
        int y = graphics.guiHeight() - PADDING - 1 - height;
        TooltipRenderUtil.extractTooltipBackground(graphics, x, y, width, height, null);
        y += 1;
        for (Component line : lines) {
            graphics.text(font, line, x, y, 0xFF404040);
            y += lineHeight;
        }
    }

