public static void onClientDisconnect(ClientPlayerNetworkEvent.LoggingOut event) {
        if (event.getConnection() == null) {
            // For some reason, vanilla performs a disconnect before joining an SP world or a server or closing the game
            return;
        }

        FramingSawRecipeCache.get(true).clear();
        BlockOverlayCache.get(true).clear();
        CacheCleaner.clearModelCaches(CacheCleaner.Reason.DISCONNECT);
        ColorResolvingLevel.clearBiomeReference();
    }

public static void onScrollInput(InputEvent.MouseScrollingEvent event) {
        double deltaY = event.getScrollDeltaY();
        if (Mth.equal(deltaY, 0F)) {
            return;
        }

        Player player = Minecraft.getInstance().player;
        if (player == null) {
            return;
        }

        ItemStack stack = player.getMainHandItem();
        if (!(stack.getItem() instanceof IFramedBlockItem item) || !item.isStateCyclingActive(player)) {
            return;
        }

        if (KeyMappings.UNLOCK_STATE_CYCLE.get().isDown()) {
            boolean forward = deltaY < 0;
            ClientPacketDistributor.sendToServer(ServerboundStateCycleActionPayload.cycle(forward));
            event.setCanceled(true);
        }
    }

public static void enqueueClientTask(long delay, Runnable task) {
        if (delay == 0) {
            Minecraft.getInstance().schedule(task);
            return;
        }

        //noinspection ConstantConditions
        long time = Minecraft.getInstance().level.getGameTime() + delay;
        tasks.add(new ClientTask(time, task));
    }

public static void onClientTick(@SuppressWarnings("unused") ClientTickEvent.Post event) {
        if (tasks.isEmpty()) {
            return;
        }

        Level level = Minecraft.getInstance().level;
        if (level == null || level.dimension() != lastDimension) {
            lastDimension = level != null ? level.dimension() : null;
            tasks.clear(); //Clear remaining tasks from the previous level

            if (level == null) {
                return;
            }
        }

        Iterator<ClientTask> it = tasks.iterator();
        while (it.hasNext()) {
            ClientTask task = it.next();
            if (level.getGameTime() >= task.time) {
                task.task.run();
                it.remove();
            }
        }
    }

private static Lazy<KeyMapping> makeKeyMapping(String name, int key) {
        return Lazy.of(() -> new KeyMapping(FramedConstants.MOD_ID + ".key." + name, key, KEY_CATEGORY));
    }

public static void onRegisterKeyMappings(RegisterKeyMappingsEvent event) {
        event.registerCategory(KEY_CATEGORY);

        event.register(UPDATE_CULLING.get());
        event.register(WIPE_CACHE.get());
        event.register(TOGGLE_STATE_CYCLE.get());
        event.register(UNLOCK_STATE_CYCLE.get());
    }

public static void onClientTick(@SuppressWarnings("unused") ClientTickEvent.Pre event) {
        Level level = Minecraft.getInstance().level;
        if (level == null || Minecraft.getInstance().screen != null) {
            return;
        }

        if (isKeyPressed(UPDATE_CULLING)) {
            HitResult hit = Minecraft.getInstance().hitResult;
            if (hit instanceof BlockHitResult blockHit && level.getBlockEntity(blockHit.getBlockPos()) instanceof IFramedBlockEntity be) {
                try {
                    be.updateCulling(true, true);
                } catch (Throwable throwable) {
                    LOGGER.error(
                            "Encountered unexpected exception while updating culling of '{}'",
                            be.getBlockState().getBlock(),
                            throwable
                    );
                }

                BlockPos pos = blockHit.getBlockPos();
                Component blockName = be.getBlockState().getBlock().getName();

                Component msg = Component.literal("Culling updated for '")
                        .append(blockName)
                        .append("' at ")
                        .append(Component.literal(
                                String.format("{x=%d, y=%d, z=%d}", pos.getX(), pos.getY(), pos.getZ())
                        ));

                //noinspection ConstantConditions
                Minecraft.getInstance().player.sendOverlayMessage(msg);
            }
        }

        if (isKeyPressed(WIPE_CACHE)) {
            CacheCleaner.clearModelCaches(CacheCleaner.Reason.MANUAL);

            //noinspection ConstantConditions
            Minecraft.getInstance().player.sendOverlayMessage(Component.literal("Model cache cleared"));
        }

        if (isKeyPressed(TOGGLE_STATE_CYCLE)) {
            Player player = Minecraft.getInstance().player;
            if (player != null && player.getMainHandItem().getItem() instanceof IFramedBlockItem item && item.getStateCycleSpec().canCycle()) {
                ClientPacketDistributor.sendToServer(ServerboundStateCycleActionPayload.TOGGLE);
            }
        }
    }

private static boolean isKeyPressed(Lazy<KeyMapping> mapping) {
        boolean pressed = false;
        while (mapping.get().consumeClick()) {
            pressed = true;
        }
        return pressed;
    }

