                byte[] offsets = FramedCollapsibleCopycatBlockEntity.unpackOffsets(key);
                return box(
                        offsets[WEST],
                        offsets[DOWN],
                        offsets[NORTH],
                        16 - offsets[EAST],
                        16 - offsets[UP],
                        16 - offsets[SOUTH]
                );
            });
        }
