        return new DoubleBlockParts(
                FBContent.BLOCK_FRAMED_INNER_CORNER_BOARD.value()
                        .defaultBlockState()
                        .setValue(PropertyHolder.FACING_DIR, cmpDir),
                FBContent.BLOCK_FRAMED_CORNER_BOARD.value()
