public static BooleanProperty getPropFromAxis(Direction dir) {
        return switch (dir.getAxis()) {
            case X -> FramedProperties.X_AXIS;
            case Y -> FramedProperties.Y_AXIS;
            case Z -> FramedProperties.Z_AXIS;
        };
