        BlockState stateOne;
        if (DirUtils.isY(facing)) {
            stateOne = FBContent.BLOCK_FRAMED_SLAB.value()
                    .defaultBlockState()
                    .setValue(FramedProperties.TOP, facing == Direction.UP);
        } else {
            stateOne = FBContent.BLOCK_FRAMED_PANEL.value()
                    .defaultBlockState()
                    .setValue(FramedProperties.FACING_HOR, facing);
