                stateOne.setValue(FramedProperties.COPYCAT_STYLE, copycatStyle),
                FBContent.BLOCK_FRAMED_HALF_PILLAR.value()
                        .defaultBlockState()
                        .setValue(BlockStateProperties.FACING, facing.getOpposite())
