public FramedElevatedDoubleSlopeEdgeBlockEntity(BlockPos pos, BlockState state) {
        super(FBContent.BE_TYPE_FRAMED_ELEVATED_DOUBLE_SLOPE_EDGE.value(), pos, state);
    }

@Override
    protected boolean hitSecondary(BlockHitResult hit, Vec3 lookVec, Vec3 eyePos) {
        Direction side = hit.getDirection();

        Direction dir = getBlockState().getValue(FramedProperties.FACING_HOR);
        if (side == dir) {
            return false;
        }

        SlopeType type = getBlockState().getValue(PropertyHolder.SLOPE_TYPE);
        Direction dirTwo = switch (type) {
            case BOTTOM -> Direction.DOWN;
            case HORIZONTAL -> dir.getCounterClockWise();
            case TOP -> Direction.UP;
        };
        if (side == dirTwo) {
            return false;
        }

        Vec3 hitVec = hit.getLocation();
        if (side == dir.getOpposite()) {
            return MathUtils.fractionInDir(hitVec, dirTwo.getOpposite()) > .5;
        } else if (side == dirTwo.getOpposite()) {
            return MathUtils.fractionInDir(hitVec, dir.getOpposite()) > .5;
        }

        double par = (MathUtils.fractionInDir(hitVec, dir.getOpposite()) - .5) * 2D;
        double perp = (MathUtils.fractionInDir(hitVec, dirTwo.getOpposite()) - .5) * 2D;
        if (par >= 0D && perp >= 0D) {
            return perp >= (1D - par);
        }
        return false;
    }

public FramedDoubleSlopePanelBlockEntity(BlockPos pos, BlockState state) {
        super(FBContent.BE_TYPE_FRAMED_DOUBLE_SLOPE_PANEL.value(), pos, state);
    }

@Override
    protected boolean hitSecondary(BlockHitResult hit, Vec3 lookVec, Vec3 eyePos) {
        Direction face = hit.getDirection();
        Direction facing = getBlockState().getValue(FramedProperties.FACING_HOR);

        if (face == facing) {
            return false;
        }
        if (face == facing.getOpposite()) {
            return true;
        }

        Direction orientation = getBlockState().getValue(PropertyHolder.ROTATION).withFacing(facing);
        if (face == orientation) {
            return true;
        }
        if (face == orientation.getOpposite()) {
            return false;
        }

        Vec3 vec = MathUtils.fraction(hit.getLocation());

        double hor = DirUtils.isX(facing) ? vec.x() : vec.z();
        if (!DirUtils.isPositive(facing)) {
            hor = 1D - hor;
        }
        if (!getBlockState().getValue(PropertyHolder.FRONT)) {
            hor -= .5D;
        }

        double vert = DirUtils.isY(orientation) ? vec.y() : (DirUtils.isX(facing) ? vec.z() : vec.x());
        if (orientation == Direction.DOWN || (!DirUtils.isY(orientation) && !DirUtils.isPositive(orientation))) {
            vert = 1F - vert;
        }
        return (hor * 2D) < vert;
    }

