public FramedSmallDoubleCornerSlopePanelBlockEntity(BlockPos pos, BlockState state) {
        super(FBContent.BE_TYPE_FRAMED_SMALL_DOUBLE_CORNER_SLOPE_PANEL.value(), pos, state);
    }

@Override
    protected boolean hitSecondary(BlockHitResult hit, Vec3 lookVec, Vec3 eyePos) {
        Direction side = hit.getDirection();
        boolean top = getBlockState().getValue(FramedProperties.TOP);

        if (DirUtils.isY(side)) {
            boolean up = side == Direction.UP;
            return top != up;
        }

        Direction facing = getBlockState().getValue(FramedProperties.FACING_HOR);
        if (side == facing.getOpposite() || side == facing.getClockWise()) {
            return false;
        }

        Vec3 hitVec = hit.getLocation();
        double xz = MathUtils.fractionInDir(hitVec, side == facing ? facing.getCounterClockWise() : facing) - .5;
        double y = MathUtils.fractionInDir(hitVec, top ? Direction.UP : Direction.DOWN);
        return (xz * 2D) > y;
    }

public FramedSmallDoubleCornerSlopePanelWallBlockEntity(BlockPos pos, BlockState state) {
        super(FBContent.BE_TYPE_FRAMED_SMALL_DOUBLE_CORNER_SLOPE_PANEL_WALL.value(), pos, state);
    }

@Override
    protected boolean hitSecondary(BlockHitResult hit, Vec3 lookVec, Vec3 eyePos) {
        Direction side = hit.getDirection();
        Direction dir = getBlockState().getValue(FramedProperties.FACING_HOR);
        if (side == dir) {
            return false;
        }
        if (side == dir.getOpposite()) {
            return true;
        }

        HorizontalRotation rot = getBlockState().getValue(PropertyHolder.ROTATION);
        Direction rotDir = rot.withFacing(dir);
        Direction perpRotDir = rot.rotate(Rotation.COUNTERCLOCKWISE_90).withFacing(dir);

        if (side == rotDir.getOpposite() || side == perpRotDir.getOpposite()) {
            return false;
        }

        Vec3 hitVec = hit.getLocation();
        double xzDir = MathUtils.fractionInDir(hitVec, dir);
        double xzPerp;
        if (DirUtils.isY(side)) {
            xzPerp = MathUtils.fractionInDir(hitVec, DirUtils.isY(rotDir) ? perpRotDir : rotDir);
        } else {
            xzPerp = MathUtils.fractionInDir(hitVec, DirUtils.isY(rotDir) ? rotDir : perpRotDir);
        }

        return ((xzPerp - .5) * 2D) > xzDir;
    }

public FramedDoubleSlopeSlabBlockEntity(BlockPos pos, BlockState state) {
        super(FBContent.BE_TYPE_FRAMED_DOUBLE_SLOPE_SLAB.value(), pos, state);
    }

@Override
    protected boolean hitSecondary(BlockHitResult hit, Vec3 lookVec, Vec3 eyePos) {
        Direction facing = getBlockState().getValue(FramedProperties.FACING_HOR);
        Direction side = hit.getDirection();

        if (side == facing.getOpposite() || side == Direction.UP) {
            return true;
        }
        if (side == facing || side == Direction.DOWN) {
            return false;
        }

        Vec3 vec = MathUtils.fraction(hit.getLocation());

        double hor = DirUtils.isX(facing) ? vec.x() : vec.z();
        if (!DirUtils.isPositive(facing)) {
            hor = 1D - hor;
        }

        double y = vec.y();
        if (getBlockState().getValue(PropertyHolder.TOP_HALF)) {
            y -= .5;
        }
        return (y * 2D) >= hor;
    }

public FramedElevatedDoubleSlopeSlabBlockEntity(BlockPos pos, BlockState state) {
        super(FBContent.BE_TYPE_FRAMED_ELEVATED_DOUBLE_SLOPE_SLAB.value(), pos, state);
    }

@Override
    protected boolean hitSecondary(BlockHitResult hit, Vec3 lookVec, Vec3 eyePos) {
        Direction facing = getBlockState().getValue(FramedProperties.FACING_HOR);
        boolean top = getBlockState().getValue(FramedProperties.TOP);
        Direction side = hit.getDirection();

        if (side == Direction.UP) {
            return !top;
        }
        if (side == Direction.DOWN || side == facing) {
            return top;
        }

        Vec3 vec = MathUtils.fraction(hit.getLocation());
        if (side == facing.getOpposite()) {
            return (vec.y() >= .5D) != top;
        }

        double hor = DirUtils.isX(facing) ? vec.x() : vec.z();
        if (!DirUtils.isPositive(facing)) {
            hor = 1D - hor;
        }

        double y = vec.y();
        if (top) {
            y = 1D - y;
        }
        y -= .5D;
        return (y * 2D) >= hor;
    }

