public static byte[] unpackOffsets(int packed) {
        byte[] offsets = new byte[DIRECTIONS.length];
        for (int i = 0; i < DIRECTIONS.length; i++) {
            offsets[i] = (byte) (packed >> (i * 4) & 0xF);
        }
