@Override
    public boolean canConnectFullEdge(BlockState state, Direction side, @Nullable Direction edge) {
        Direction facing = state.getValue(BlockStateProperties.HORIZONTAL_FACING);
        boolean open = state.getValue(BlockStateProperties.OPEN);

        Direction fullFace = facing.getOpposite();
        if (open) {
            DoorHingeSide hinge = state.getValue(BlockStateProperties.DOOR_HINGE);
            fullFace = hinge == DoorHingeSide.LEFT ? facing.getCounterClockWise() : facing.getClockWise();
        }

        if (side == fullFace) {
            return true;
        } else if (side.getAxis() != fullFace.getAxis()) {
            return edge == fullFace;
        }

        return false;
    }

@Override
    public boolean canConnectDetailed(BlockState state, Direction side, Direction edge) {
        Direction facing = state.getValue(BlockStateProperties.HORIZONTAL_FACING);
        boolean open = state.getValue(BlockStateProperties.OPEN);

        Direction fullFace = facing;
        if (open) {
            DoorHingeSide hinge = state.getValue(BlockStateProperties.DOOR_HINGE);
            fullFace = hinge == DoorHingeSide.LEFT ? facing.getClockWise() : facing.getCounterClockWise();
        }

        if (side == fullFace) {
            return edge.getAxis() != fullFace.getAxis();
        } else if (side.getAxis() == fullFace.getClockWise().getAxis()) {
            return DirUtils.isY(edge);
        }
        return false;
    }

@Override
    public boolean canConnectFullEdge(BlockState state, Direction side, @Nullable Direction edge) {
        boolean open = state.getValue(BlockStateProperties.OPEN);
        if (open && state.getValue(PropertyHolder.ROTATE_TEXTURE)) {
            return false;
        }

        Direction facing = state.getValue(BlockStateProperties.HORIZONTAL_FACING);

        Direction fullFace = facing.getOpposite();
        if (!open) {
            Half half = state.getValue(BlockStateProperties.HALF);
            fullFace = half == Half.BOTTOM ? Direction.DOWN : Direction.UP;
        }

        if (side == fullFace) {
            return true;
        } else if (side.getAxis() != fullFace.getAxis()) {
            return edge == fullFace;
        }

        return false;
    }

@Override
    public boolean canConnectDetailed(BlockState state, Direction side, Direction edge) {
        boolean open = state.getValue(BlockStateProperties.OPEN);
        if (open && state.getValue(PropertyHolder.ROTATE_TEXTURE)) {
            return false;
        }

        Direction fullFace = state.getValue(BlockStateProperties.HORIZONTAL_FACING);
        if (!open) {
            Half half = state.getValue(BlockStateProperties.HALF);
            fullFace = half == Half.BOTTOM ? Direction.UP : Direction.DOWN;
        }

        if (side == fullFace) {
            return true;
        } else if (side.getAxis() != fullFace.getAxis()) {
            return edge == fullFace.getOpposite() || edge.getAxis() != fullFace.getAxis();
        }

        return false;
    }

@Override
    public boolean canConnectFullEdge(BlockState state, Direction side, @Nullable Direction edge) {
        return DirUtils.isY(side) || edge != null;
    }

@Override
    public boolean canConnectFullEdge(BlockState state, Direction side, @Nullable Direction edge) {
        return false;
    }

@Override
