@Override
    public boolean canConnectFullEdge(BlockState state, Direction side, @Nullable Direction edge) {
        Direction facing = state.getValue(FramedProperties.FACING_HOR);
        StairsType type = state.getValue(PropertyHolder.STAIRS_TYPE);

        boolean top = type.isTop();
        boolean bottom = type.isBottom();
        boolean fwd = type.isForward();
        boolean ccw = type.isCounterClockwise();

        if (side == facing) {
            if (!fwd) {
                return true;
            }
            return edge != facing.getClockWise() && ((top && edge != Direction.UP) || (bottom && edge != Direction.DOWN));
        }
        if (side == facing.getCounterClockWise()) {
            if (!ccw) {
                return true;
            }
            return edge != facing.getOpposite() && ((top && edge != Direction.UP) || (bottom && edge != Direction.DOWN));
        }
        if (side == facing.getOpposite()) {
            return !ccw && edge == facing.getCounterClockWise();
        }
        if (side == facing.getClockWise()) {
            return !fwd && edge == facing;
        }
        if (side == Direction.UP) {
            if (!top) {
                return edge == facing || edge == facing.getCounterClockWise();
            }
            return (!fwd && edge == facing) || (!ccw && edge == facing.getCounterClockWise());
        }
        if (side == Direction.DOWN) {
            if (!bottom) {
                return edge == facing || edge == facing.getCounterClockWise();
            }
            return (!fwd && edge == facing) || (!ccw && edge == facing.getCounterClockWise());
        }
        return false;
    }

@Override
    public boolean canConnectDetailed(BlockState state, Direction side, Direction edge) {
        Direction facing = state.getValue(FramedProperties.FACING_HOR);
        StairsType type = state.getValue(PropertyHolder.STAIRS_TYPE);

        boolean top = type.isTop();
        boolean bottom = type.isBottom();
        boolean fwd = type.isForward();
        boolean ccw = type.isCounterClockwise();

        if (side == facing && fwd) {
            return edge == facing.getClockWise() || (top && edge == Direction.UP) || (bottom && edge == Direction.DOWN);
        }
        if (side == facing.getCounterClockWise() && ccw) {
            return edge == facing.getOpposite() || (top && edge == Direction.UP) || (bottom && edge == Direction.DOWN);
        }
        if (side == facing.getOpposite()) {
            return ccw || edge != facing.getCounterClockWise();
        }
        if (side == facing.getClockWise()) {
            return fwd || edge != facing;
        }
        if (side == Direction.UP) {
            if (edge == facing.getOpposite() || edge == facing.getClockWise()) {
                return true;
            }
            return top && ((fwd && edge == facing) || (ccw && edge == facing.getCounterClockWise()));
        }
        if (side == Direction.DOWN) {
            if (edge == facing.getOpposite() || edge == facing.getClockWise()) {
                return true;
            }
            return bottom && ((fwd && edge == facing) || (ccw && edge == facing.getCounterClockWise()));
        }
        return false;
    }

public static void handleCullingUpdates(long chunkPos, LongSet positions) {
        ClientTaskQueue.enqueueClientTask(1, () -> {
            Level level = Objects.requireNonNull(Minecraft.getInstance().level);
            BlockPos.MutableBlockPos blockPos = new BlockPos.MutableBlockPos();
            if (level.hasChunk(ChunkPos.getX(chunkPos), ChunkPos.getZ(chunkPos))) {
                positions.forEach(pos -> {
                    blockPos.set(pos);
                    if (level.getBlockEntity(blockPos) instanceof IFramedBlockEntity be) {
                        be.updateCulling(true, true);
                    }
                });
            }
        });
    }

public static void onServerLevelTick(LevelTickEvent.Pre event) {
        Level level = event.getLevel();
        if (level.isClientSide()) {
            return;
        }

        ResourceKey<Level> dim = level.dimension();
        Long2ObjectMap<LongSet> chunks = UPDATED_POSITIONS.get(dim);
        if (chunks != null && !chunks.isEmpty()) {
            for (Long2ObjectMap.Entry<LongSet> entry : chunks.long2ObjectEntrySet()) {
                long chunk = entry.getLongKey();
                PacketDistributor.sendToPlayersTrackingChunk(
                        (ServerLevel) level,
                        ChunkPos.unpack(chunk),
                        new ClientboundCullingUpdatePayload(chunk, entry.getValue())
                );
            }
            chunks.clear();
        }
    }

public static void onServerShutdown(@SuppressWarnings("unused") ServerStoppedEvent event) {
        UPDATED_POSITIONS.clear();
    }

public static void enqueueCullingUpdate(Level level, BlockPos pos) {
        UPDATED_POSITIONS.computeIfAbsent(level.dimension(), _ -> new Long2ObjectOpenHashMap<>())
                .computeIfAbsent(ChunkPos.pack(pos), _ -> new LongArraySet())
                .add(pos.asLong());
    }

