@Override
    public boolean test(BlockState state, Direction side) {
        Direction facing = state.getValue(BlockStateProperties.HORIZONTAL_FACING);
        if (state.getValue(BlockStateProperties.OPEN)) {
            if (state.getValue(BlockStateProperties.DOOR_HINGE) == DoorHingeSide.LEFT) {
                return facing.getCounterClockWise() == side;
            }
            return facing.getClockWise() == side;
        }
        return facing.getOpposite() == side;
    }

@Override
    public boolean test(BlockState state, Direction side) {
        if (state.getValue(BlockStateProperties.OPEN)) {
            if (state.getValue(PropertyHolder.ROTATE_TEXTURE)) {
                return false;
            }
            return state.getValue(BlockStateProperties.HORIZONTAL_FACING).getOpposite() == side;
        }
        if (state.getValue(BlockStateProperties.HALF) == Half.TOP) {
            return side == Direction.UP;
        }
        return side == Direction.DOWN;
    }

@Override
    public boolean test(BlockState state, Direction side) {
        return FramedBoardBlock.isFacePresent(state, side);
    }

@Override
    public boolean test(BlockState state, Direction side) {
        NullableDirection face = state.getValue(PropertyHolder.NULLABLE_FACE);
        if (face == NullableDirection.NONE) {
            return true;
        }
        return side == face.toDirection().getOpposite();
    }

@Override
    public boolean test(BlockState state, Direction side) {
        int solid = state.getValue(PropertyHolder.SOLID_FACES);
        int mask = ~(1 << side.getOpposite().ordinal());
        return (solid & mask) == (mask & FramedCollapsibleCopycatBlock.ALL_SOLID);
    }

@Override
    public boolean test(BlockState state, Direction side) {
        return !state.getValue(PropertyHolder.CORNER_TYPE_ORIENTATION).isSideOpen(side);
    }

@Override
    public boolean test(BlockState state, Direction side) {
        int layers = state.getValue(BlockStateProperties.LAYERS);
        return layers == 8 || side == state.getValue(BlockStateProperties.FACING).getOpposite();
    }

@Override
    public boolean test(BlockState state, Direction side) {
        NullableDirection face = state.getValue(PropertyHolder.NULLABLE_FACE);
        return face == NullableDirection.NONE || side != face.toDirection();
    }

