    }

@Override
    public boolean test(BlockState state, Direction side) {
        return side == state.getValue(PropertyHolder.FACING_DIR).direction().getOpposite();
    }

@Override
    public boolean test(BlockState state, Direction side) {
        CornerType type = state.getValue(PropertyHolder.CORNER_TYPE);
        if (type == CornerType.TOP) {
            return side == Direction.UP;
        }
        if (type == CornerType.BOTTOM) {
            return side == Direction.DOWN;
        }
        return state.getValue(FramedProperties.FACING_HOR) == side;
    }

@Override
    public boolean test(BlockState state, Direction side) {
        Direction dir = state.getValue(FramedProperties.FACING_HOR);
        CornerType type = state.getValue(PropertyHolder.CORNER_TYPE);

        if (type.isHorizontal()) {
            if (side == dir || side == dir.getOpposite()) {
                return true;
            }
            if (side == dir.getCounterClockWise()) {
                return !type.isRight();
            }
            if (side == dir.getClockWise()) {
                return type.isRight();
            }
            return (side == Direction.DOWN && !type.isTop()) || (side == Direction.UP && type.isTop());
        }
        return DirUtils.isY(side) || side == dir || side == dir.getCounterClockWise();
    }

@Override
    public boolean test(BlockState state, Direction side) {
        if (state.getValue(PropertyHolder.SLOPE_TYPE) == SlopeType.HORIZONTAL) {
            return !DirUtils.isY(side);
        }

        Direction facing = state.getValue(FramedProperties.FACING_HOR);
        return DirUtils.isY(side) || side == facing || side == facing.getOpposite();
    }

@Override
    public boolean test(BlockState state, Direction side) {
        Direction dir = state.getValue(FramedProperties.FACING_HOR);
        boolean top = state.getValue(FramedProperties.TOP);

        if (side == dir || side == dir.getCounterClockWise()) {
            return true;
        }
        return (dir == Direction.DOWN && !top) || (dir == Direction.UP && top);
    }

@Override
    public boolean test(BlockState state, Direction side) {
        CornerType type = state.getValue(PropertyHolder.CORNER_TYPE);
        if ((type == CornerType.TOP || (type.isHorizontal() && type.isTop())) && side == Direction.UP) {
            return true;
        }
        if ((type == CornerType.BOTTOM || (type.isHorizontal() && !type.isTop())) && side == Direction.DOWN) {
            return true;
        }

        Direction facing = state.getValue(FramedProperties.FACING_HOR);
        if (type.isHorizontal()) {
            return facing == side || (type.isRight() && facing.getClockWise() == side) || (!type.isRight() && facing.getCounterClockWise() == side);
        }
        return facing == side || facing.getCounterClockWise() == side;
    }

@Override
    public boolean test(BlockState state, Direction side) {
        boolean top = state.getValue(FramedProperties.TOP);
        if (top && side == Direction.UP) {
            return true;
        }
        if (!top && side == Direction.DOWN) {
            return true;
        }

        Direction facing = state.getValue(FramedProperties.FACING_HOR);
        return facing == side || facing.getCounterClockWise() == side;
    }

@Override
    public boolean test(BlockState state, Direction side) {
        SlopeBlock block = (SlopeBlock) state.getBlock();
        SlopeType type = block.getSlopeType(state);
        if (side == Direction.UP && type == SlopeType.TOP) {
            return true;
        }
        if (side == Direction.DOWN && type == SlopeType.BOTTOM) {
            return true;
        }
        if (type == SlopeType.HORIZONTAL) {
            Direction facing = state.getValue(FramedProperties.FACING_HOR);
            return side == facing || side == facing.getCounterClockWise();
        }
        return block.getFacing(state) == side;
    }

@Override
    public boolean test(BlockState state, Direction side) {
        Direction dir = state.getValue(FramedProperties.FACING_HOR);
        if (side == dir) {
            return true;
        }

        return switch (state.getValue(PropertyHolder.SLOPE_TYPE)) {
            case BOTTOM -> side == Direction.DOWN;
            case HORIZONTAL -> side == dir.getCounterClockWise();
            case TOP -> side == Direction.UP;
        };
    }

@Override
    public boolean test(BlockState state, Direction side) {
        Direction facing = state.getValue(FramedProperties.FACING_HOR);
        boolean front = state.getValue(PropertyHolder.FRONT);
        return (!front && side == facing) || (front && side == facing.getOpposite());
    }

@Override
    public boolean test(BlockState state, Direction side) {
        Direction dir = state.getValue(FramedProperties.FACING_HOR);
        if (side.getAxis() == dir.getAxis()) {
            return true;
        }

        HorizontalRotation rot = state.getValue(PropertyHolder.ROTATION);
        return side == rot.withFacing(dir).getOpposite();
    }

@Override
    public boolean test(BlockState state, Direction side) {
        Direction facing = state.getValue(FramedProperties.FACING_HOR);
        Direction orientation = state.getValue(PropertyHolder.ROTATION).withFacing(facing);
        return side == facing || side == orientation.getOpposite();
    }

@Override
    public boolean test(BlockState state, Direction side) {
        Direction facing = state.getValue(FramedProperties.FACING_HOR);
        if (state.getValue(PropertyHolder.FRONT)) {
            return side == facing.getOpposite();
        }
        return side == facing;
    }

@Override
    public boolean test(BlockState state, Direction side) {
        Direction facing = state.getValue(FramedProperties.FACING_HOR);
        if (side.getAxis() == facing.getAxis()) {
            return true;
        }

