private static ShapeContainer generate(List<BlockState> states, ShapeCache<CornerSlopeEdgeShapes.ShapeKey> edgeShapes, ShapeCache<CornerType> baseShapes) {
        VoxelShape[] shapes = new VoxelShape[4 * 6];
        for (CornerType type : CornerType.values()) {
            VoxelShape edgeShape = edgeShapes.get(new CornerSlopeEdgeShapes.ShapeKey(type, true));
            VoxelShape shape = ShapeUtils.orUnoptimized(baseShapes.get(type), edgeShape);
            ShapeUtils.makeHorizontalRotations(shape, Direction.NORTH, shapes, type, ElevatedCornerSlopeEdgeShapes::makeIndex);
        }

        Map<BlockState, VoxelShape> map = new IdentityHashMap<>(states.size());
        for (BlockState state : states) {
            Direction dir = state.getValue(FramedProperties.FACING_HOR);
            CornerType type = state.getValue(PropertyHolder.CORNER_TYPE);
            map.put(state, shapes[makeIndex(dir, type)]);
        }
        return ShapeContainer.of(map);
    }

private static int makeIndex(Direction dir, CornerType type) {
        return (type.ordinal() << 2) | dir.get2DDataValue();
    }

private static ShapeCache<CornerType> makeCache() {
        return ShapeCache.createEnum(CornerType.class, map -> {
            map.put(CornerType.BOTTOM, ShapeUtils.orUnoptimized(
                    CommonShapes.SLAB.get(false),
                    CommonShapes.CORNER_PILLAR.get(Direction.NORTH)
            ));
            map.put(CornerType.TOP, ShapeUtils.orUnoptimized(
                    CommonShapes.SLAB.get(true),
                    CommonShapes.CORNER_PILLAR.get(Direction.NORTH)
            ));

            VoxelShape horShape = ShapeUtils.orUnoptimized(
                    CommonShapes.PANEL.get(Direction.NORTH),
                    CommonShapes.SLAB_EDGE.get(new CommonShapes.DirBoolKey(Direction.WEST, false))
            );
            map.put(CornerType.HORIZONTAL_BOTTOM_LEFT, horShape);
            map.put(CornerType.HORIZONTAL_TOP_LEFT, ShapeUtils.rotateShapeUnoptimizedAroundZ(
                    Direction.DOWN, Direction.WEST, horShape
            ));
            map.put(CornerType.HORIZONTAL_TOP_RIGHT, ShapeUtils.rotateShapeUnoptimizedAroundZ(
                    Direction.DOWN, Direction.UP, horShape
            ));
            map.put(CornerType.HORIZONTAL_BOTTOM_RIGHT, ShapeUtils.rotateShapeUnoptimizedAroundZ(
                    Direction.DOWN, Direction.EAST, horShape
            ));
        });
    }

private static ShapeCache<CornerType> makeInnerCache() {
        return ShapeCache.createEnum(CornerType.class, map -> {
            VoxelShape bottomShape = ShapeUtils.orUnoptimized(
                    CommonShapes.SLAB.get(false),
                    CommonShapes.STRAIGHT_VERTICAL_STAIRS.get(Direction.NORTH)
            );
            map.put(CornerType.BOTTOM, bottomShape);

            VoxelShape topShape = ShapeUtils.orUnoptimized(
                    CommonShapes.SLAB.get(true),
                    CommonShapes.STRAIGHT_VERTICAL_STAIRS.get(Direction.NORTH)
            );
            map.put(CornerType.TOP, topShape);

            map.put(CornerType.HORIZONTAL_BOTTOM_LEFT, bottomShape);
            map.put(CornerType.HORIZONTAL_BOTTOM_RIGHT, ShapeUtils.rotateShapeUnoptimizedAroundY(
                    Direction.NORTH, Direction.EAST, bottomShape
            ));
            map.put(CornerType.HORIZONTAL_TOP_LEFT, topShape);
            map.put(CornerType.HORIZONTAL_TOP_RIGHT, ShapeUtils.rotateShapeUnoptimizedAroundY(
                    Direction.NORTH, Direction.EAST, topShape
            ));
        });
    }

@Override
    public ShapeContainer generatePrimary(List<BlockState> states) {
        return generate(states, SlopeEdgeShapes.SHAPES);
    }

@Override
    public ShapeContainer generateOcclusion(List<BlockState> states) {
        return generate(states, SlopeEdgeShapes.OCCLUSION_SHAPES);
    }

private static ShapeContainer generate(List<BlockState> states, ShapeCache<SlopeEdgeShapes.ShapeKey> cache) {
        VoxelShape shapeBottom = ShapeUtils.orUnoptimized(
                ShapeUtils.orUnoptimized(Block.box(0, 0, 0, 16, 8, 16), Block.box(0, 8, 0, 16, 16, 8)),
                cache.get(new SlopeEdgeShapes.ShapeKey(SlopeType.BOTTOM, true))
        );
        VoxelShape shapeHorizontal = ShapeUtils.orUnoptimized(
                VerticalStairsShapes.SHAPES.get(new VerticalStairsShapes.ShapeKey(Direction.NORTH, StairsType.VERTICAL)),
                cache.get(new SlopeEdgeShapes.ShapeKey(SlopeType.HORIZONTAL, true))
        );
        VoxelShape shapeTop = ShapeUtils.orUnoptimized(
                ShapeUtils.orUnoptimized(Block.box(0, 8, 0, 16, 16, 16), Block.box(0, 0, 0, 16, 8, 8)),
                cache.get(new SlopeEdgeShapes.ShapeKey(SlopeType.TOP, true))
        );

        VoxelShape[] shapes = new VoxelShape[4 * 3];

        ShapeUtils.makeHorizontalRotations(shapeBottom, Direction.NORTH, shapes, 0);
        ShapeUtils.makeHorizontalRotations(shapeHorizontal, Direction.NORTH, shapes, SlopeType.HORIZONTAL.ordinal() << 2);
        ShapeUtils.makeHorizontalRotations(shapeTop, Direction.NORTH, shapes, SlopeType.TOP.ordinal() << 2);

        Map<BlockState, VoxelShape> map = new IdentityHashMap<>(states.size());

        for (BlockState state : states) {
            SlopeType type = state.getValue(PropertyHolder.SLOPE_TYPE);
            Direction dir = state.getValue(FramedProperties.FACING_HOR);
            int idx = (type.ordinal() << 2) + dir.get2DDataValue();
            map.put(state, shapes[idx]);
        }

        return ShapeContainer.of(map);
    }

@Override
    public ShapeContainer generatePrimary(List<BlockState> states) {
        return generateShapes(states, SlopeEdgeShapes.SHAPES);
    }

@Override
    public ShapeContainer generateOcclusion(List<BlockState> states) {
        return generateShapes(states, SlopeEdgeShapes.OCCLUSION_SHAPES);
    }

private static ShapeContainer generateShapes(List<BlockState> states, ShapeCache<SlopeEdgeShapes.ShapeKey> edgeShapes) {
        VoxelShape[] shapes = new VoxelShape[4 * 8];
        for (int i = 0; i < 8; i++) {
            HorizontalRotation rot = ROTATIONS[i >> 1];
            boolean front = (i & 1) != 0;

            VoxelShape slabEdgeShape = switch (rot) {
                case UP -> CommonShapes.SLAB_EDGE.get(new CommonShapes.DirBoolKey(front ? Direction.SOUTH : Direction.NORTH, false));
                case DOWN -> CommonShapes.SLAB_EDGE.get(new CommonShapes.DirBoolKey(front ? Direction.SOUTH : Direction.NORTH, true));
                case RIGHT -> CommonShapes.CORNER_PILLAR.get(front ? Direction.WEST : Direction.NORTH);
                case LEFT -> CommonShapes.CORNER_PILLAR.get(front ? Direction.SOUTH : Direction.EAST);
            };
            VoxelShape slopeEdgeShape = switch (rot) {
                case UP -> {
                    VoxelShape shape = edgeShapes.get(new SlopeEdgeShapes.ShapeKey(SlopeType.BOTTOM, front));
                    if (!front) { shape = shape.move(0, .5, 0); }
                    yield shape;
                }
                case DOWN -> {
                    VoxelShape shape = edgeShapes.get(new SlopeEdgeShapes.ShapeKey(SlopeType.TOP, front));
                    if (!front) { shape = shape.move(0, -.5, 0); }
                    yield shape;
                }
                case RIGHT -> {
                    VoxelShape shape = edgeShapes.get(new SlopeEdgeShapes.ShapeKey(SlopeType.HORIZONTAL, front));
                    if (!front) { shape = shape.move(.5, 0, 0); }
                    yield shape;
                }
                case LEFT -> {
                    VoxelShape shape = edgeShapes.get(new SlopeEdgeShapes.ShapeKey(SlopeType.HORIZONTAL, front));
                    shape = ShapeUtils.rotateShapeAroundY(Direction.NORTH, Direction.EAST, shape);
                    if (!front) { shape = shape.move(-.5, 0, 0); }
                    yield shape;
                }
            };
            VoxelShape shape = ShapeUtils.orUnoptimized(slabEdgeShape, slopeEdgeShape);

            ShapeUtils.makeHorizontalRotations(shape, Direction.NORTH, shapes, i * 4);
        }

        Map<BlockState, VoxelShape> map = new IdentityHashMap<>();
        for (BlockState state : states) {
            Direction dir = state.getValue(FramedProperties.FACING_HOR);
            HorizontalRotation rot = state.getValue(PropertyHolder.ROTATION);
            boolean front = state.getValue(PropertyHolder.FRONT);
            int idx = dir.get2DDataValue() | (rot.ordinal() << 3) | (front ? 0b100 : 0);
            map.put(state, shapes[idx]);
        }
        return ShapeContainer.of(map);
    }

@Override
    public ShapeContainer generatePrimary(List<BlockState> states) {
        return generate(states, SHAPES);
    }

@Override
    public ShapeContainer generateOcclusion(List<BlockState> states) {
        return generate(states, OCCLUSION_SHAPES);
    }

private static ShapeContainer generate(List<BlockState> states, ShapeCache<ShapeKey> cache) {
        VoxelShape[] shapes = new VoxelShape[3 * 4 * 2];

        for (SlopeType type : SlopeType.values()) {
            ShapeUtils.makeHorizontalRotations(
                    cache.get(new ShapeKey(type, false)),
                    Direction.NORTH,
                    shapes,
                    type,
                    (dir, keyType) -> makeShapeIndex(dir, keyType, false)
            );
            ShapeUtils.makeHorizontalRotations(
                    cache.get(new ShapeKey(type, true)),
                    Direction.NORTH,
                    shapes,
                    type,
                    (dir, keyType) -> makeShapeIndex(dir, keyType, true)
            );
        }

        Map<BlockState, VoxelShape> map = new IdentityHashMap<>(states.size());

        for (BlockState state : states) {
            SlopeType type = state.getValue(PropertyHolder.SLOPE_TYPE);
            Direction dir = state.getValue(FramedProperties.FACING_HOR);
            boolean altType = state.getValue(PropertyHolder.ALT_TYPE);
            map.put(state, shapes[makeShapeIndex(dir, type, altType)]);
        }

        return ShapeContainer.of(map);
    }

private static int makeShapeIndex(Direction dir, SlopeType type, boolean altType) {
        return (type.ordinal() << 3) | (dir.get2DDataValue() << 1) | (altType ? 1 : 0);
    }

private static ShapeCache<ShapeKey> makeCache(Supplier<VoxelShape> bottomShape) {
        return ShapeCache.create(map -> {
            VoxelShape shapeBottom = bottomShape.get();
            map.put(new ShapeKey(SlopeType.BOTTOM, false), shapeBottom);
            map.put(new ShapeKey(SlopeType.BOTTOM, true), shapeBottom.move(0, .5, .5));

            VoxelShape shapeTop = ShapeUtils.rotateShapeUnoptimizedAroundZ(Direction.DOWN, Direction.UP, shapeBottom);
            map.put(new ShapeKey(SlopeType.TOP, false), shapeTop);
            map.put(new ShapeKey(SlopeType.TOP, true), shapeTop.move(0, -.5, .5));

            VoxelShape shapeHorizontal = ShapeUtils.rotateShapeUnoptimizedAroundZ(Direction.DOWN, Direction.WEST, shapeBottom);
            map.put(new ShapeKey(SlopeType.HORIZONTAL, false), shapeHorizontal);
            map.put(new ShapeKey(SlopeType.HORIZONTAL, true), shapeHorizontal.move(.5, 0, .5));
        });
    }

