                VoxelShape shapeOne = cache.get(SlopePanelShape.get(rotOne, true));
                VoxelShape preShape = ShapeUtils.orUnoptimized(
                        ShapeUtils.rotateShapeUnoptimizedAroundY(Direction.NORTH, Direction.SOUTH, shapeOne),
