private static ShapeContainer generateShapes(List<BlockState> states, ShapeCache<ShapeKey> shapeCache) {
        Map<BlockState, VoxelShape> map = new IdentityHashMap<>(states.size());

        for (BlockState state : states) {
            Direction dir = state.getValue(FramedProperties.FACING_HOR);
            HorizontalRotation rot = state.getValue(PropertyHolder.ROTATION);
            map.put(state, shapeCache.get(new ShapeKey(dir, rot)));
        }

        return ShapeContainer.of(map);
    }

private static ShapeCache<ShapeKey> makeCache(ShapeCache<HalfSlopeShapes.ShapeKey> shapeCache) {
        return ShapeCache.create(map -> {
            VoxelShape panelShape = CommonShapes.PANEL.get(Direction.NORTH);

            VoxelShape shapeUp = ShapeUtils.orUnoptimized(
                    panelShape,
                    ShapeUtils.rotateShapeUnoptimizedAroundY(
                            Direction.NORTH,
                            Direction.EAST,
                            shapeCache.get(new HalfSlopeShapes.ShapeKey(false, true))
                    )
            );

            VoxelShape shapeDown = ShapeUtils.orUnoptimized(
                    panelShape,
                    ShapeUtils.rotateShapeUnoptimizedAroundY(
                            Direction.NORTH,
                            Direction.WEST,
                            shapeCache.get(new HalfSlopeShapes.ShapeKey(true, false))
                    )
            );

            VoxelShape shapeRight = ShapeUtils.orUnoptimized(
                    panelShape,
                    ShapeUtils.rotateShapeUnoptimizedAroundY(
                            Direction.NORTH,
                            Direction.WEST,
                            shapeCache.get(new HalfSlopeShapes.ShapeKey(false, false))
                    )
            );

            VoxelShape shapeLeft = ShapeUtils.orUnoptimized(
                    panelShape,
                    ShapeUtils.rotateShapeUnoptimizedAroundY(
                            Direction.NORTH,
                            Direction.EAST,
                            shapeCache.get(new HalfSlopeShapes.ShapeKey(true, true))
                    )
            );

            ShapeUtils.makeHorizontalRotations(shapeUp, Direction.NORTH, map, HorizontalRotation.UP, ShapeKey::new);
            ShapeUtils.makeHorizontalRotations(shapeDown, Direction.NORTH, map, HorizontalRotation.DOWN, ShapeKey::new);
            ShapeUtils.makeHorizontalRotations(shapeRight, Direction.NORTH, map, HorizontalRotation.RIGHT, ShapeKey::new);
            ShapeUtils.makeHorizontalRotations(shapeLeft, Direction.NORTH, map, HorizontalRotation.LEFT, ShapeKey::new);
        });
    }

public static ShapeContainer generate(List<BlockState> states) {
        Map<BlockState, VoxelShape> map = new IdentityHashMap<>(states.size());

        for (BlockState state : states) {
            Direction dir = state.getValue(FramedProperties.FACING_HOR);
            StairsType type = state.getValue(PropertyHolder.STAIRS_TYPE);
            map.put(state, SHAPES.get(new ShapeKey(dir, type)));
        }

        return ShapeContainer.of(map);
    }

CornerDir(Direction normal, Direction edgeOne, Direction edgeTwo) {
        this.normal = normal;
        this.edgeOne = edgeOne;
        this.edgeTwo = edgeTwo;
    }

public CornerDir getOppositeNormal() {
        if (this == NULL) {
            return this;
        }
        return fromDirections(normal.getOpposite(), edgeOne, edgeTwo);
    }

public boolean isEqualTo(CornerDir other) {
        return this != NULL && getOppositeNormal() == other;
    }

public static CornerDir fromDirections(Direction normal, Direction edgeOne, Direction edgeTwo) {
        CornerDir dir = FROM_DIRS[normal.ordinal()][edgeOne.ordinal()][edgeTwo.ordinal()];
        if (dir == null) {
            throw new IllegalArgumentException(
                    "Invalid direction triple: normal:" + normal + ", edge one: " + edgeOne + ", edge two: " + edgeTwo
            );
        }
        return dir;
    }

private static CornerDir[][][] makeDirTable() {
        CornerDir[][][] table = new CornerDir[6][6][6];
        for (CornerDir dir : values()) {
            if (dir == NULL) {
                continue;
            }

            table[dir.normal.ordinal()][dir.edgeOne.ordinal()][dir.edgeTwo.ordinal()] = dir;
            table[dir.normal.ordinal()][dir.edgeTwo.ordinal()][dir.edgeOne.ordinal()] = dir;
        }
        return table;
    }

DiagCornerDir(CornerDir dirOne, CornerDir dirTwo) {
        this.dirOne = dirOne;
        this.dirTwo = dirTwo;
    }

public boolean isEqualTo(DiagCornerDir other) {
        return this != NULL && dirOne.isEqualTo(other.dirOne) && dirTwo.isEqualTo(other.dirTwo);
    }

