@Override
    @CullTest.TestTarget(BlockType.FRAMED_CHEST)
    public boolean test(BlockGetter level, BlockPos pos, BlockState state, BlockState adjState, Direction side) {
        if (!adjState.is(state.getBlock())) {
            return false;
        }

        ChestType type = state.getValue(BlockStateProperties.CHEST_TYPE);
        if (type == ChestType.SINGLE) {
            return false;
        }

        ChestType adjType = adjState.getValue(BlockStateProperties.CHEST_TYPE);
        if (type != adjType.getOpposite()) {
            return false;
        }

        return FramedChestBlock.getConnectionDirection(state) == side && FramedChestBlock.getConnectionDirection(adjState) == side.getOpposite();
    }

@Override
    @CullTest.TestTarget(BlockType.FRAMED_COLLAPSIBLE_BLOCK)
    public boolean test(BlockGetter level, BlockPos pos, BlockState state, BlockState adjState, Direction side) {
        NullableDirection face = state.getValue(PropertyHolder.NULLABLE_FACE);
        if (face == NullableDirection.NONE || side.getAxis() == face.toDirection().getAxis()) {
            return false;
        }

        if (adjState.getBlock() == state.getBlock() && adjState.getValue(PropertyHolder.NULLABLE_FACE) == face) {
            BlockEntity be = level.getBlockEntity(pos);
            BlockEntity adjBe = level.getBlockEntity(pos.relative(side));

            if (be instanceof CollapsibleBlockEntity cbe && adjBe instanceof CollapsibleBlockEntity adjCbe) {
                Direction faceDir = face.toDirection();
                VertexPair verts = VertexMappings.getEdgeVertices(faceDir, side);
                VertexPair adjVerts = VertexMappings.getEdgeVertices(faceDir, side.getOpposite());

                int offV1 = cbe.getVertexOffset(state, verts.v1());
                int offV2 = cbe.getVertexOffset(state, verts.v2());
                int adjOffV1 = adjCbe.getVertexOffset(adjState, adjVerts.v1());
                int adjOffV2 = adjCbe.getVertexOffset(adjState, adjVerts.v2());

                return offV1 == adjOffV2 && offV2 == adjOffV1;
            }
        }
        return false;
    }

@Override
    @CullTest.TestTarget(BlockType.FRAMED_COLLAPSIBLE_COPYCAT_BLOCK)
    public boolean test(BlockGetter level, BlockPos pos, BlockState state, BlockState adjState, Direction side) {
        if (adjState.getBlock() == state.getBlock()) {
            int solid = state.getValue(PropertyHolder.SOLID_FACES);
            if ((solid & (1 << side.ordinal())) == 0) {
                return false;
            }

            int adjSolid = adjState.getValue(PropertyHolder.SOLID_FACES);
            if ((adjSolid & (1 << side.getOpposite().ordinal())) == 0) {
                return false;
            }

            if (!(level.getBlockEntity(pos) instanceof CollapsibleCopycatBlockEntity be)) {
                return false;
            }
            if (!(level.getBlockEntity(pos.relative(side)) instanceof CollapsibleCopycatBlockEntity adjBe)) {
                return false;
            }

            for (Direction face : DIRECTIONS) {
                if (face.getAxis() == side.getAxis()) {
                    continue;
                }
                int offset = be.getFaceOffset(state, face);
                int adjOffset = adjBe.getFaceOffset(adjState, face);
                if (offset != adjOffset) {
                    return false;
                }
            }
            return true;
        }
        return false;
    }

@Override
    public boolean test(BlockGetter level, BlockPos pos, BlockState state, BlockState adjState, Direction side) {
        CornerTubeOrientation orientation = state.getValue(PropertyHolder.CORNER_TYPE_ORIENTATION);
        if (MiscDirs.CornerTube.testEarlyExit(orientation, side)) {
            return false;
