public static void addPlayerInvSlots(Consumer<Slot> slotConsumer, Inventory playerInv, int x, int y, SlotFactory factory) {
        for (int row = 0; row < 3; ++row) {
            for (int col = 0; col < 9; ++col) {
                slotConsumer.accept(factory.create(playerInv, col + row * 9 + 9, x + col * 18, y));
            }
            y += 18;
        }

        for (int col = 0; col < 9; ++col) {
            slotConsumer.accept(factory.create(playerInv, col, x + col * 18, y + 4));
        }
    }

public static <T, R extends T> Function<T, DataResult<R>> validateSubType(Class<R> subType) {
        String messagePrefix = "Not a " + subType.getSimpleName() + ": ";
        return value -> {
            if (subType.isInstance(value)) {
                return DataResult.success(subType.cast(value));
            }
            return DataResult.error(() -> messagePrefix + value);
        };
    }

public static <T, R extends T> Function<T, R> assertSubType(Class<R> subType) {
        String messagePrefix = "Not a " + subType.getSimpleName() + ": ";
        return value -> {
            if (subType.isInstance(value)) {
                return subType.cast(value);
            }
            throw new IllegalArgumentException(messagePrefix + value);
        };
    }

public MarkdownTable header(String cell) {
        return header(cell, false);
    }

public MarkdownTable header(String cell, boolean alignRight) {
        header.add(cell.trim());
        alignment.add(alignRight);
        return this;
    }

public MarkdownTable cell(String cell) {
        currRow.add(cell.trim());
        return this;
    }

public MarkdownTable newRow() {
        Preconditions.checkState(
                currRow.size() == header.size(),
                "Row length inconsistent. Expected: %s, got: %s",
                header.size(), currRow.size()
        );

        rows.add(currRow);
        currRow = new ArrayList<>();
        return this;
    }

public String print() {
        if (!currRow.isEmpty()) {
            newRow();
        }

        int[] lengths = new int[header.size()];
        for (int i = 0; i < header.size(); i++) {
            lengths[i] = header.get(i).length();
            for (List<String> row : rows) {
                lengths[i] = Math.max(lengths[i], row.get(i).length());
            }
        }

        StringBuilder out = new StringBuilder();

        // Header texts
        out.append("|");
        for (int i = 0; i < header.size(); i++) {
            String cell = header.get(i);
            int targetLen = lengths[i];
            printCell(out, cell, targetLen, alignment.getBoolean(i));
        }
        out.append("\n");

        // Header separator
        out.append("|");
        for (int i = 0; i < header.size(); i++) {
            boolean alignRight = alignment.getBoolean(i);
            int targetLen = lengths[i];
            if (!alignRight) {
                out.append(":");
            }
            out.append("-".repeat(targetLen + 1));
            if (alignRight) {
                out.append(":");
            }
            out.append("|");
        }
        out.append("\n");

        // Cell texts
        for (List<String> row : rows) {
            out.append("|");
            for (int i = 0; i < row.size(); i++) {
                String cell = row.get(i);
                int targetLen = lengths[i];
                printCell(out, cell, targetLen, alignment.getBoolean(i));
            }
            out.append("\n");
        }

        return out.toString();
    }

private static void printCell(StringBuilder out, String cell, int targetLen, boolean alignRight) {
        out.append(" ");

        int diff = targetLen - cell.length();
        if (diff == 0) {
            out.append(cell);
        } else {
            if (alignRight) {
                out.append(" ".repeat(diff));
            }
            out.append(cell);
            if (!alignRight) {
                out.append(" ".repeat(diff));
            }
        }

        out.append(" |");
    }

