public FramedBlocksTest(IEventBus modBus) {
        modBus.addListener(SelfTest::runStartupSelfTest);

        NeoForge.EVENT_BUS.addListener(SpecialTestCommand::registerCommands);
        NeoForge.EVENT_BUS.addListener(ChunkBanTest::onLevelTick);
        NeoForge.EVENT_BUS.addListener(SelfTest::runInWorldSelfTest);
    }

public static void registerCommands(RegisterCommandsEvent event) {
        event.getDispatcher().register(Commands.literal("fbtest")
                .then(Commands.literal("skippredicates")
                        .then(Commands.literal("errors")
                                .executes(async(
                                        SkipPredicateErrors.NAME, SkipPredicateErrors::testSkipPredicates
                                ))
                        )
                        .then(Commands.literal("consistency")
                                .executes(async(
                                        SkipPredicateConsistency.NAME, SkipPredicateConsistency::testSkipPredicates
                                ))
                        )
                        .then(Commands.literal("redundancy")
                                .executes(async(
                                        SkipPredicateRedundancy.NAME, SkipPredicateRedundancy::testSkipPredicates
                                ))
                        )
                )
                .then(Commands.literal("chunkban")
                        .then(Commands.argument("confirm", StringArgumentType.string())
                                .then(Commands.argument("state", BlockStateArgument.block(event.getBuildContext()))
                                        .executes(ctx -> ChunkBanTest.startChunkBanTest(ctx, true))
                                )
                                .executes(ctx -> ChunkBanTest.startChunkBanTest(ctx, false))
                        )
                )
                .then(Commands.literal("stateinfo")
                        .executes(BlockStateInfo::dumpBlockStateInfo)
                )
                .then(Commands.literal("modelperf")
                        .executes(async(ModelPerformanceTest.NAME, ModelPerformanceTest::testModelPerformance))
                )
                .then(Commands.literal("benchmark_cube")
                        .then(Commands.argument("overlays", BoolArgumentType.bool())
                                .then(Commands.argument("confirm", StringArgumentType.string())
                                        .executes(ModelBenchmarkCube::buildBenchmarkCube)
                                )
                        )
                )
                .then(Commands.literal("reload_shapes")
                        .executes(SpecialTestCommand::reloadShapes)
                )
        );
    }

private static int reloadShapes(CommandContext<CommandSourceStack> ctx) {
        if (ShapeReloader.reload()) {
            ctx.getSource().sendSuccess(() -> Component.literal("Shapes reloaded"), false);
            return Command.SINGLE_SUCCESS;
        }

        ctx.getSource().sendFailure(Component.literal("Shape reload failed, see log for details"));
        return 0;
    }

private static Command<CommandSourceStack> async(String testName, AsyncCommand cmd) {
        return ctx -> {
            ctx.getSource().sendSuccess(() -> Component.literal("Starting " + testName + " test"), false);

            Consumer<Component> appender = msg -> ctx.getSource().getServer().submit(() ->
                    ctx.getSource().source.sendSystemMessage(msg)
            );
            runGuardedOffThread(testName, appender, () -> cmd.run(ctx, appender));

            return Command.SINGLE_SUCCESS;
        };
    }

public static void runGuardedOffThread(String testName, Consumer<Component> msgQueueAppender, Runnable test) {
        Util.backgroundExecutor().execute(() -> {
            try {
                test.run();
            } catch (Throwable t) {
                msgQueueAppender.accept(Component.literal(
                        "Encountered an uncaught error while testing " + testName + ". See log for details"
                ));
                LOGGER.error("Encountered an error while testing {}", testName, t);
            }
        });
    }

public static Component writeResultToFile(String filePrefix, String data) {
        return writeResultToFile(filePrefix, "txt", data);
    }

public static Component writeResultToFile(String filePrefix, String fileType, String data) {
        try {
            Files.createDirectories(EXPORT_DIR);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }

        String dateTime = FORMATTER.format(LocalDateTime.now());
        Path path = EXPORT_DIR.resolve("%s_%s.%s".formatted(filePrefix, dateTime, fileType));

        try {
            Files.writeString(path, data, StandardOpenOption.WRITE, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING);

            String pathText = path.toAbsolutePath().toString();
            Component pathComponent = Component.literal(pathText).withStyle(style ->
                    style.withClickEvent(new ClickEvent.OpenFile(pathText))
                            .applyFormat(ChatFormatting.UNDERLINE)
            );
            return Component.literal("Tests results exported to ").append(pathComponent);
        } catch (IOException e) {
            LOGGER.error("Encountered an error while exporting test results", e);
            return Component.literal("Export of test results failed with error: %s: %s".formatted(
                    e.getClass().getSimpleName(), e.getMessage()
            ));
        }
    }

public static int dumpBlockStateInfo(CommandContext<CommandSourceStack> ctx) {
        Stopwatch watch = Stopwatch.createStarted();

        MarkdownTable table = new MarkdownTable();
        table.header("Block")
                .header("State count", true)
                .header("Model state count", true)
                .header("BlockOverlays")
                .header("Solid")
                .header("Glowing")
                .header("Skylight")
                .header("Waterlogging")
                .header("State lock")
                .header("Copycat")
                .header("Ignored properties");

        long totalPlaceableBlocks = 0;
        long totalDoubleBlocks = 0;
        long totalBlocksWithOverlays = 0;
        long totalBlocksWithCopycat = 0;
        long totalStates = 0;
        long totalModelStates = 0;
        long totalStatesWithOverlays = 0;
        long totalModelStatesWithOverlays = 0;
        for (BlockType type : TYPES) {
            Block block = FBContent.byType(type);
            String name = BuiltInRegistries.BLOCK.getKey(block).getPath();
            ModelWrappingHandler wrapper = ModelWrappingManager.getHandler(block);
            int stateCount = block.getStateDefinition().getPossibleStates().size();
            int modelStateCount = wrapper.getVisitedStateCount();

            String blockOverlays = type.supportsBlockOverlays() ? "supported" : "-";
            String solid = type.canOccludeWithSolidCamo() ? checkBooleanProperty(block, FramedProperties.SOLID) : "-";
            String glowing = checkBooleanProperty(block, FramedProperties.GLOWING);
            String skylight = checkBooleanProperty(block, FramedProperties.PROPAGATES_SKYLIGHT);
            String waterlogging = type.supportsWaterLogging() ? checkBooleanProperty(block, BlockStateProperties.WATERLOGGED) : "-";
            String stateLock = block instanceof ShapeLockableBlock ? checkBooleanProperty(block, FramedProperties.STATE_LOCKED) : "-";
            String copycat = switch (block) {
                case CopycatStyleBlock.Always _ -> "always";
                case CopycatStyleBlock.StateDependent _ -> "state";
                default -> "-";
            };
            String ignoredProperties = printIgnoredProperties(wrapper, block);

            table.cell(name)
                    .cell("%,d".formatted(stateCount))
                    .cell("%,d".formatted(modelStateCount))
                    .cell(blockOverlays)
                    .cell(solid)
                    .cell(glowing)
                    .cell(skylight)
                    .cell(waterlogging)
                    .cell(stateLock)
                    .cell(copycat)
                    .cell(ignoredProperties)
                    .newRow();

            totalStates += stateCount;
            totalModelStates += modelStateCount;
            if (type.hasBlockItem()) {
                totalPlaceableBlocks++;
            }
            if (type.isDoubleBlock()) {
                totalDoubleBlocks++;
            }
            if (type.supportsBlockOverlays()) {
                totalBlocksWithOverlays++;
                totalStatesWithOverlays += stateCount;
                totalModelStatesWithOverlays += modelStateCount;
            }
            if (block instanceof CopycatStyleBlock) {
                totalBlocksWithCopycat++;
            }
        }

        String dump = table.print() +
                "\nBlock count: " + TYPES.length +
                "\\\n↳ With item: " + totalPlaceableBlocks +
                "\\\n↳ With two camos: " + totalDoubleBlocks +
                "\\\n↳ With BlockOverlays: " + totalBlocksWithOverlays +
                "\\\n↳ With copycat: " + totalBlocksWithCopycat +
                "\\\nTotal states: " + totalStates +
                "\\\n↳ With BlockOverlays: " + totalStatesWithOverlays +
                "\\\nTotal model states: " + totalModelStates +
                "\\\n↳ With BlockOverlays: " + totalModelStatesWithOverlays +
                "\n";

        watch.stop();

        Component exportMsg = SpecialTestCommand.writeResultToFile("blockstate_info", "md", dump);
        Component resultMsg = Component.literal(RESULT_MSG.formatted(TYPES.length, watch)).append(exportMsg);
        ctx.getSource().sendSuccess(() -> resultMsg, true);

        return Command.SINGLE_SUCCESS;
    }

@SuppressWarnings("deprecation")
    private static String printIgnoredProperties(ModelWrappingHandler wrapper, Block block) {
        return wrapper.getStateMerger()
                .getHandledProperties(block.builtInRegistryHolder())
                .stream()
                .filter(block.defaultBlockState()::hasProperty)
                .map(Property::getName)
                .sorted()
                .collect(Collectors.joining(", "));
    }

private static String checkBooleanProperty(Block block, BooleanProperty property) {
        if (!block.defaultBlockState().hasProperty(property)) {
            return "missing";
        }
        if (block.defaultBlockState().getValue(property)) {
            return "wrong default";
        }
        return "present";
    }

public static int startChunkBanTest(CommandContext<CommandSourceStack> ctx, boolean withState) {
        String confirmation = ctx.getArgument("confirm", String.class);
        if (!confirmation.equals(CONFIRMATION_KEY)) {
            ctx.getSource().sendFailure(MSG_NO_CONFIRM);
            return 0;
        }

        if (!(ctx.getSource().getPlayer() instanceof ServerPlayer player) || player instanceof FakePlayer) {
            ctx.getSource().sendFailure(MSG_NOT_A_PLAYER);
            return 0;
        }

        if (dimension != null) {
            ctx.getSource().sendFailure(MSG_ALREADY_RUNNING);
            return 0;
        }

        if (withState) {
            state = BlockStateArgument.getBlock(ctx, "state").getState();
        } else {
            state = FBContent.BLOCK_FRAMED_DOUBLE_SLAB.value().defaultBlockState();
        }

        ServerLevel level = ctx.getSource().getLevel();
        ChunkPos chunk = ChunkPos.containing(new BlockPos((int) player.getX(), (int) player.getY(), (int) player.getZ()));
        int minY = level.getMinY();
        startPos = placePos = SectionPos.of(chunk, SectionPos.blockToSectionCoord(minY)).origin().above();
        dimension = level.dimension();
        resultMsgConsumer = msg -> ctx.getSource().sendSuccess(() -> msg, true);

        ctx.getSource().sendSuccess(() -> Component.literal("Starting chunkban test preparation in chunk " + chunk), true);

        return 1;
    }

public static void onLevelTick(LevelTickEvent.Pre event) {
        Level level = event.getLevel();
        if (dimension != null && level.dimension() == dimension) {
            Objects.requireNonNull(state);
            Objects.requireNonNull(startPos);
            Objects.requireNonNull(placePos);

            for (int i = 0; i < 16; i++) {
                BlockPos pos = placePos.east(i);

                level.setBlockAndUpdate(pos, state);
                BlockEntity be = level.getBlockEntity(pos);
                if (be instanceof IFramedBlockEntity fbe) {
                    fbe.setCamo(CAMO_ONE_FACTORY.get(), false);
                }
                if (be instanceof FramedDoubleBlockEntity fdbe) {
                    fdbe.setCamo(CAMO_TWO_FACTORY.get(), true);
                }

                blocksPlaced++;
            }

            placePos = placePos.south();
            if (placePos.getZ() > startPos.getZ() + 15) {
                placePos = placePos.north(16).above();
                if (placePos.getY() >= level.getMaxY()) {
                    Objects.requireNonNull(resultMsgConsumer).accept(Component.literal(
                            "Chunkban test preparation completed, placed " + blocksPlaced + " blocks"
                    ));

                    resultMsgConsumer = null;
                    dimension = null;
                    state = null;
                    startPos = null;
                    placePos = null;
                    blocksPlaced = 0;
                }
            }
        }
    }

public static int buildBenchmarkCube(CommandContext<CommandSourceStack> ctx) {
        String confirmation = ctx.getArgument("confirm", String.class);
        if (!confirmation.equals(CONFIRMATION_KEY)) {
            ctx.getSource().sendFailure(MSG_NO_CONFIRM);
            return 0;
        }

        if (!(ctx.getSource().getPlayer() instanceof ServerPlayer player) || player instanceof FakePlayer) {
            ctx.getSource().sendFailure(MSG_NOT_A_PLAYER);
            return 0;
        }

        ServerLevel level = ctx.getSource().getLevel();
        Direction horViewDir = Direction.getApproximateNearest(player.getViewVector(1F).multiply(1, 0, 1));
        SectionPos chunk = SectionPos.of(player.position().add(horViewDir.getUnitVec3().multiply(16, 0, 16)));
        BlockState state = FBContent.BLOCK_FRAMED_SLAB.value().defaultBlockState();
        BlockPos.MutableBlockPos pos = new BlockPos.MutableBlockPos();
        CamoContainer<?, ?> camo = FBContent.FACTORY_BLOCK.value().applyCamo(level, BlockPos.ZERO, player, ItemAccess.forStack(new ItemStack(Blocks.STONE)));
        if (camo == null) {
            ctx.getSource().sendFailure(MSG_CAMO_FAILED);
            return 0;
        }

        Holder<BlockOverlay> blockOverlay = null;
        if (ctx.getArgument("overlays", Boolean.class)) {
            Optional<Holder.Reference<BlockOverlay>> optional = level.registryAccess().get(OVERLAY_KEY);
            if (optional.isEmpty()) {
                ctx.getSource().sendFailure(MSG_OVERLAY_FAILED);
                return 0;
            }
            blockOverlay = optional.get();
        }

        int minX = chunk.minBlockX();
        int minY = chunk.minBlockY();
        int minZ = chunk.minBlockZ();
        for (int y = 0; y < 16; y++) {
            for (int x = 0; x < 16; x++) {
                for (int z = 0; z < 16; z++) {
                    pos.set(minX + x, minY + y, minZ + z);
                    boolean top = ((x % 2) ^ (z % 2)) != 0;
                    top |= y == 14 && x >= 7 && x <= 8 && z >= 7 && z <= 9;

                    level.setBlockAndUpdate(pos, state.setValue(FramedProperties.TOP, top));
                    if (level.getBlockEntity(pos) instanceof IFramedBlockEntity be) {
                        be.setCamo(camo, false);
                        be.setOverlay(blockOverlay);
                    }
                }
            }
        }

        pos.set(minX + 7, minY + 15, minZ + 7);
        level.setBlockAndUpdate(pos, Blocks.REDSTONE_WIRE.defaultBlockState());
        pos.set(minX + 8, minY + 15, minZ + 7);
        level.setBlockAndUpdate(pos, Blocks.REDSTONE_WIRE.defaultBlockState());

        pos.set(minX + 7, minY + 15, minZ + 8);
        level.setBlockAndUpdate(pos, Blocks.REPEATER.defaultBlockState().setValue(BlockStateProperties.HORIZONTAL_FACING, Direction.SOUTH));
        pos.set(minX + 8, minY + 15, minZ + 8);
        level.setBlockAndUpdate(pos, Blocks.REPEATER.defaultBlockState().setValue(BlockStateProperties.HORIZONTAL_FACING, Direction.NORTH));

        pos.set(minX + 7, minY + 15, minZ + 9);
        level.setBlockAndUpdate(pos, Blocks.REDSTONE_WIRE.defaultBlockState());
        pos.set(minX + 8, minY + 15, minZ + 9);
        level.setBlockAndUpdate(pos, Blocks.REDSTONE_TORCH.defaultBlockState());

        BlockPos dustPos = new BlockPos(minX + 8, minY + 15, minZ + 9);
        level.getServer().schedule(new TickTask(level.getServer().getTickCount() + 1, () ->
                level.setBlockAndUpdate(dustPos, Blocks.REDSTONE_WIRE.defaultBlockState())
        ));

        return Command.SINGLE_SUCCESS;
    }

public static void testModelPerformance(CommandContext<CommandSourceStack> ignored, Consumer<Component> msgQueueAppender) {
        Map<String, BlockState> testStates = new LinkedHashMap<>();

        testStates.put(STONE_NAME, Blocks.STONE.defaultBlockState());
        for (BlockType type : BlockType.values()) {
            if (EXCLUDED.contains(type)) {
                continue;
            }

            BlockState state = FBContent.byType(type).defaultBlockState();
            String blockName = BuiltInRegistries.BLOCK.getKey(state.getBlock()).toString();
            testStates.put(blockName, state);
        }

        // Warmup runs
        msgQueueAppender.accept(Component.literal(PREFIX + "Warmup..."));
        for (BlockState state : testStates.values()) {
            testModel(state, makeModelData(state, EmptyCamoContainer.EMPTY, false, null));
            testModel(state, makeModelData(state, TEST_CAMO_CONTAINER, false, null));
            testModel(state, makeModelData(state, TEST_CAMO_CONTAINER, true, null));
            testModel(state, makeModelData(state, TEST_CAMO_CONTAINER, false, TEST_OVERLAY));
        }

        msgQueueAppender.accept(Component.literal(PREFIX + "Measure..."));
        Map<String, List<Result>> results = new LinkedHashMap<>();
        for (int i = 0; i < RUNS; i++) {
            msgQueueAppender.accept(Component.literal(PREFIX + "  Run " + (i + 1)));

            for (Map.Entry<String, BlockState> entry : testStates.entrySet()) {
                BlockState state = entry.getValue();
                boolean stone = state.getBlock() == Blocks.STONE;
                long timeEmpty = testModel(state, makeModelData(state, EmptyCamoContainer.EMPTY, false, null));
                long timeCamo = stone ? 0 : testModel(state, makeModelData(state, TEST_CAMO_CONTAINER, false, null));
                long timeCamoEmissive = stone ? 0 : testModel(state, makeModelData(state, TEST_CAMO_CONTAINER, true, null));
                long timeCamoOverlay = stone ? 0 : testModel(state, makeModelData(state, TEST_CAMO_CONTAINER, true, TEST_OVERLAY));
                results.computeIfAbsent(entry.getKey(), _ -> new ArrayList<>()).add(new Result(timeEmpty, timeCamo, timeCamoEmissive, timeCamoOverlay));
            }
        }

        msgQueueAppender.accept(Component.literal(PREFIX + "Done, exporting results..."));

        MarkdownTable table = new MarkdownTable();
        table.header("Block");
        for (int i = 0; i < RUNS; i++) {
            table.header("Run %d".formatted(i + 1), true);
        }
        table.header("Average", true).header("Relative", true);

        int[] count = new int[1];
        long[] stoneAvg = new long[1];
        long[] allEmptyAvg = new long[results.size() - 1];
        float[] allEmptyRel = new float[results.size() - 1];
        long[] allCamoAvg = new long[results.size() - 1];
        float[] allCamoRel = new float[results.size() - 1];
        long[] allCamoEmissiveAvg = new long[results.size() - 1];
        float[] allCamoEmissiveRel = new float[results.size() - 1];
        long[] allCamoOverlayAvg = new long[results.size() - 1];
        float[] allCamoOverlayRel = new float[results.size() - 1];
        results.forEach((name, values) -> {
            int index = count[0] - 1;
            computeAndPrintEntry(table, index, name, TestType.EMPTY, values, allEmptyAvg, allEmptyRel, stoneAvg);
            computeAndPrintEntry(table, index, name, TestType.CAMO, values, allCamoAvg, allCamoRel, stoneAvg);
            computeAndPrintEntry(table, index, name, TestType.CAMO_EMISSIVE, values, allCamoEmissiveAvg, allCamoEmissiveRel, stoneAvg);
            computeAndPrintEntry(table, index, name, TestType.CAMO_OVERLAY, values, allCamoOverlayAvg, allCamoOverlayRel, stoneAvg);

            count[0]++;
        });

        StringBuilder data = new StringBuilder();

        int minBlank = 0;
        int maxBlank = 0;
        int minCamo = 0;
        int maxCamo = 0;
        int minCamoEmissive = 0;
        int maxCamoEmissive = 0;
        int minCamoOverlay = 0;
        int maxCamoOverlay = 0;
        for (int i = 0; i < results.size() - 1; i++) {
            minBlank = compare(allEmptyAvg, i, minBlank, true);
            maxBlank = compare(allEmptyAvg, i, maxBlank, false);
            minCamo = compare(allCamoAvg, i, minCamo, true);
            maxCamo = compare(allCamoAvg, i, maxCamo, false);
            minCamoEmissive = compare(allCamoEmissiveAvg, i, minCamoEmissive, true);
            maxCamoEmissive = compare(allCamoEmissiveAvg, i, maxCamoEmissive, false);
            minCamoOverlay = compare(allCamoOverlayAvg, i, minCamoOverlay, true);
            maxCamoOverlay = compare(allCamoOverlayAvg, i, maxCamoOverlay, false);
        }

        data.append("Relative speed:\n")
                .append("- Min (blank):          ").append("%6.2f (%6d us)\n".formatted(allEmptyRel[minBlank], allEmptyAvg[minBlank]))
                .append("- Max (blank):          ").append("%6.2f (%6d us)\n".formatted(allEmptyRel[maxBlank], allEmptyAvg[maxBlank]))
                .append("- Min (camo):           ").append("%6.2f (%6d us)\n".formatted(allCamoRel[minCamo], allCamoAvg[minCamo]))
                .append("- Max (camo):           ").append("%6.2f (%6d us)\n".formatted(allCamoRel[maxCamo], allCamoAvg[maxCamo]))
                .append("- Min (camo emissive):  ").append("%6.2f (%6d us)\n".formatted(allCamoEmissiveRel[minCamoEmissive], allCamoEmissiveAvg[minCamoEmissive]))
                .append("- Max (camo emissive):  ").append("%6.2f (%6d us)\n".formatted(allCamoEmissiveRel[maxCamoEmissive], allCamoEmissiveAvg[maxCamoEmissive]))
                .append("- Min (camo overlay):   ").append("%6.2f (%6d us)\n".formatted(allCamoOverlayRel[minCamoOverlay], allCamoOverlayAvg[minCamoOverlay]))
                .append("- Max (camo overlay):   ").append("%6.2f (%6d us)\n".formatted(allCamoOverlayRel[maxCamoOverlay], allCamoOverlayAvg[maxCamoOverlay]))
                .append("\n\n").append(table.print());

        Component msg = SpecialTestCommand.writeResultToFile("modelperf", "md", data.toString());
        msgQueueAppender.accept(Component.literal(PREFIX).append(msg));
    }

private static void computeAndPrintEntry(MarkdownTable table, int index, String name, TestType type, List<Result> values, long[] allAverage, float[] allRelative, long[] stoneAvg) {
        boolean stone = name.equals(STONE_NAME);
        if (stone && type != TestType.EMPTY) { return; }

        if (!stone) {
            name += " (" + type.suffix + ")";
        }
        table.cell(name);
        long total = 0;
        for (Result entry : values) {
            long time = type.resultGetter.applyAsLong(entry);
            table.cell("%6d us".formatted(time));
            total += time;
        }
        long average = total / RUNS;
        float relative = stone ? 1 : ((float) average / (float) stoneAvg[0]);
        table.cell("%6d us".formatted(average)).cell("%6.02f".formatted(relative)).newRow();

        if (stone) {
            stoneAvg[0] = average;
        } else {
            allAverage[index] = average;
            allRelative[index] = relative;
        }
    }

private static int compare(long[] data, int idx, int prevIdx, boolean min) {
        if (min ? data[idx] < data[prevIdx] : data[idx] > data[prevIdx]) {
            return idx;
        }
        return prevIdx;
    }

private static long testModel(BlockState state, ModelData data) {
        BlockStateModel model = ModelUtils.getModel(state);
        if (model instanceof FramedBlockStateModel framedModel) {
            framedModel.clearCache();
        }

        BlockAndTintGetter level = new FreestandingBlockRenderFakeLevel.Simple(state, data);

        Stopwatch watch = Stopwatch.createStarted();

        for (int i = 0; i < SAMPLE_COUNT; i++) {
            model.collectParts(level, BlockPos.ZERO, state, RANDOM, PART_SCRATCH_LIST);
            for (BlockStateModelPart part : PART_SCRATCH_LIST) {
                for (Direction side : DIRECTIONS) {
                    part.getQuads(side);
                }
            }
            PART_SCRATCH_LIST.clear();
        }

        watch.stop();
        return watch.elapsed(TimeUnit.MICROSECONDS);
    }

private static ModelData makeModelData(BlockState state, CamoContainer<?, ?> camo, boolean emissive, @Nullable Holder<BlockOverlay> overlay) {
        AbstractFramedBlockData fbData;
        if (state.getBlock() instanceof IFramedDoubleBlock doubleBlock) {
            FramedBlockData dataOne = new FramedBlockData(state, camo, (byte) 0, false, false, emissive, TriState.DEFAULT, overlay, null);
            FramedBlockData dataTwo = new FramedBlockData(state, camo, (byte) 0, true, false, emissive, TriState.DEFAULT, null, null);
            fbData = new FramedDoubleBlockData(doubleBlock.getCache(state).getParts(), dataOne, dataTwo);
        } else {
            fbData = new FramedBlockData(state, camo, (byte) 0, false, false, emissive, TriState.DEFAULT, overlay, null);
        }
        return ModelData.of(AbstractFramedBlockData.PROPERTY, fbData);
    }

