public static void checkRecipePresence(SelfTestReporter reporter, Level level) {
        reporter.startTest("recipe presence");

        MutableInt craftCount = new MutableInt(0);
        MutableInt sawCount = new MutableInt(0);

        RecipeManager recipeManager = ((ServerLevel) level).recipeAccess();
        List<? extends Recipe<?>> fbRecipes = recipeManager.getRecipes()
                .stream()
                .filter(holder -> holder.id().identifier().getNamespace().equals(FramedConstants.MOD_ID))
                .map(RecipeHolder::value)
                .toList();

        Set<ItemLike> craftResults = fbRecipes.stream()
                .filter(CraftingRecipe.class::isInstance)
                .map(CraftingRecipe.class::cast)
                .peek(_ -> craftCount.increment())
                .map(RecipePresence::unpackResult)
                .filter(Optional::isPresent)
                .map(Optional::get)
                .map(ItemStack::getItem)
                .map(ItemLike.class::cast)
                .collect(Collectors.toSet());

        Set<ItemLike> sawResults = fbRecipes.stream()
                .filter(FramingSawRecipe.class::isInstance)
                .map(FramingSawRecipe.class::cast)
                .peek(_ -> sawCount.increment())
                .map(FramingSawRecipe::getResultStack)
                .map(ItemStack::getItem)
                .map(ItemLike.class::cast)
                .collect(Collectors.toSet());

        Set<ItemLike> blockItems = collectBlockTypedItems();
        Set<ItemLike> craftDiff = Sets.difference(blockItems, craftResults);
        Set<ItemLike> sawDiff = Sets.difference(blockItems, sawResults);
        for (ItemLike item : sawDiff) {
            if (craftDiff.contains(item)) {
                reporter.warn("Block {} is uncraftable", item);
            } else {
                reporter.warn("Block {} has no saw recipe", item);
            }
        }

        Set<ItemLike> miscCraftDiff = Sets.difference(collectMiscItems(), craftResults);
        for (ItemLike item : miscCraftDiff) {
            reporter.warn("Item {} is uncraftable", item);
        }

        reporter.endTest();
    }

private static Optional<ItemStack> unpackResult(CraftingRecipe recipe) {
        return switch (recipe) {
            case ShapedRecipe shaped -> Optional.of(shaped.result.create());
            case ShapelessRecipe shapeless -> Optional.of(shapeless.result.create());
            default -> Optional.empty();
        };
    }

private static Set<ItemLike> collectMiscItems() {
        return FBContent.getRegisteredItems()
                .stream()
                .map(Holder::value)
                .filter(item -> !(item instanceof BlockItem blockItem) || !(blockItem.getBlock() instanceof IFramedBlock))
                .collect(Collectors.toSet());
    }

private static Set<ItemLike> collectBlockTypedItems() {
        return Arrays.stream(BlockType.values())
                .filter(BlockType::hasBlockItem)
                .map(FBContent::byType)
                .map(Block::asItem)
                .map(ItemLike.class::cast)
                .collect(Collectors.toSet());
    }

@SuppressWarnings("deprecation")
    public static void checkRotateMirrorErrors(SelfTestReporter reporter, List<Block> blocks) {
        reporter.startTest("rotate/mirror correctness");

        Set<Block> knownFaultyWrench = new HashSet<>();
        Set<Block> knownFaultyRotate = new HashSet<>();
        Set<Block> knownFaultyMirror = new HashSet<>();
        blocks.stream()
                .map(Block::getStateDefinition)
                .map(StateDefinition::getPossibleStates)
                .flatMap(List::stream)
                .forEach(state -> {
                    IFramedBlock block = (IFramedBlock) state.getBlock();
                    for (WrenchRotationMode mode : MODES) {
                        for (RotationDirection direction : DIRECTIONS) {
                            String type = "wrench_rotate_" + mode.getSerializedName();
                            guard(reporter, state, (modState, mod) -> block.rotate(modState, mod, mode), direction, type, knownFaultyWrench);
                        }
                    }

                    for (Rotation rot : ROTATIONS) {
                        guard(reporter, state, BlockState::rotate, rot, "rotate", knownFaultyRotate);
                    }

                    for (Mirror mirror : MIRRORS) {
                        guard(reporter, state, BlockState::mirror, mirror, "mirror", knownFaultyMirror);
                    }
                });

        reporter.endTest();
    }

private static <T extends Enum<T>> void guard(
            SelfTestReporter reporter, BlockState state, Action<T> action, T modifier, String type, Set<Block> knownFaulty
    ) {
        try {
            var ignored = action.perform(state, modifier);
        } catch (Throwable t) {
            if (!knownFaulty.add(state.getBlock())) { return; }

            reporter.error(
                    "Action '{}' throws exception on block '{}' with modifier '{}': {}",
                    type, state.getBlock(), modifier, t.getMessage()
            );
        }
    }

public static void checkSkipPredicateConsistency(SelfTestReporter reporter) {
        reporter.startTest("skip predicate consistency");

        SideSkipPredicates.PREDICATES.forEach((_, pred) -> {
            Class<?> clazz = pred.getClass();
            CullTest cullTest = clazz.getAnnotation(CullTest.class);
            if (cullTest == null) {
                return;
            }

            Method[] methods = clazz.getDeclaredMethods();
            Test test = new Test(clazz.getSimpleName(), cullTest.noSelfTest(), EnumSet.noneOf(BlockType.class), EnumSet.noneOf(BlockType.class));
            for (Method mth : methods) {
                CullTest.TestTarget target = mth.getAnnotation(CullTest.TestTarget.class);

                if (target != null) {
                    collectTarget(reporter, test, mth, target);
                }

                if (Modifier.isStatic(mth.getModifiers()) && mth.getReturnType() == Boolean.TYPE && mth.getName().contains("test")) {
                    if (target == null) {
                        reporter.error(
                                "Method '{}' in class '{}' is missing test target annotation",
                                mth.getName(), test.clazzName
                        );
                    }
                }
            }
            for (BlockType testType : cullTest.value()) {
                TESTS.put(testType, test);
            }
        });

        TESTS.forEach((type, test) -> {
            if (!test.noSelfTest && !test.targets.contains(type)) {
                reporter.warn("Type '{}' is missing a test against itself", type);
            }
            test.targets.forEach(target -> {
                if (test.oneWayTargets.contains(target)) {
                    return;
                }

                Test reverse = TESTS.get(target);
                if (reverse != null && !reverse.targets.contains(type)) {
                    reporter.warn(
                            "Type '{}' has a test against type '{}' in class '{}' but class '{}' is missing the reverse test",
                            type, target, test.clazzName, reverse.clazzName
                    );
                }
            });
        });

        reporter.endTest();
    }

private static void collectTarget(SelfTestReporter reporter, Test test, Method mth, CullTest.TestTarget target) {
        for (BlockType targetType : target.value()) {
            if (targetType.isDoubleBlock()) {
                reporter.error(
                        "SingleTarget must not handle double blocks, method '{}' in class '{}' specifies type '{}'",
                        mth.getName(), test.clazzName, targetType
                );
                continue;
            }

            if (!test.targets.add(targetType)) {
                reporter.error("Class '{}' has duplicate test against type '{}'", test.clazzName, targetType);
            }
            if (target.oneWay()) {
                test.oneWayTargets.add(targetType);
            }
        }
    }

