public void animate(IAnimatedEntity entity, float f, float f1, float f2, float f3, float f4, float f5) {
        this.resetToDefaultPose();
        animator.update(entity);
        if (animator.setAnimation(EntityGorgon.ANIMATION_SCARE)) {
            animator.startKeyframe(5);
            this.rotate(animator, Head, 0, 20, 0);
            this.rotate(animator, Left_Arm, 0, -12.5F, -70F);
            this.rotate(animator, Right_Arm, 0, 12.5F, 70F);
            animator.endKeyframe();
            animator.startKeyframe(5);
            this.rotate(animator, Head, 0, -20, 0);
            this.rotate(animator, Left_Arm, 0, -25, -140);
            this.rotate(animator, Right_Arm, 0, 25, 140);
            animator.endKeyframe();
            animator.startKeyframe(5);
            this.rotate(animator, Head, 0, 20, 0);
            this.rotate(animator, Left_Arm, 0, -25, -140);
            this.rotate(animator, Right_Arm, 0, 25, 140);
            animator.endKeyframe();
            animator.startKeyframe(5);
            this.rotate(animator, Head, 0, -20, 0);
            this.rotate(animator, Left_Arm, 0, -25, -140);
            this.rotate(animator, Right_Arm, 0, 25, 140);
            animator.endKeyframe();
            animator.resetKeyframe(10);
        }
        if (animator.setAnimation(EntityGorgon.ANIMATION_HIT)) {
            animator.startKeyframe(5);
            this.rotate(animator, Body, 10F, 0F, 0F);

            this.rotate(animator, Left_Arm, -120F, 0F, 0F);
            this.rotate(animator, Right_Arm, -120F, 0F, 0F);
            animator.endKeyframe();
            animator.resetKeyframe(5);
        }
    }

@Override
    public void setupAnim(EntityGorgon entity, float f, float f1, float f2, float f3, float f4) {
        animate(entity, f, f1, f2, f3, f4, 1);
        float speed_walk = 0.6F;
        float speed_idle = 0.05F;
        float degree_walk = 1F;
        float degree_idle = 0.5F;
        AdvancedModelBox[] TAIL = new AdvancedModelBox[]{Tail_4, Tail_5, Tail_6, Tail_7, Tail_8, Tail_9};
        AdvancedModelBox[] SNAKEL1 = new AdvancedModelBox[]{SnakeBaseL1, SnakeBodyL1, SnakeHeadL1};
        AdvancedModelBox[] SNAKEL2 = new AdvancedModelBox[]{SnakeBaseL2, SnakeBodyL2, SnakeHeadL2};
        AdvancedModelBox[] SNAKEL3 = new AdvancedModelBox[]{SnakeBaseL3, SnakeBodyL3, SnakeHeadL3};
        AdvancedModelBox[] SNAKEL4 = new AdvancedModelBox[]{SnakeBaseL4, SnakeBaseL4, SnakeBaseL4};
        AdvancedModelBox[] SNAKEL5 = new AdvancedModelBox[]{SnakeBaseL5, SnakeBaseL5, SnakeBaseL5};
        AdvancedModelBox[] SNAKEL6 = new AdvancedModelBox[]{SnakeBaseL6, SnakeBaseL6, SnakeBaseL6};
