        return this.level.getBlockState(blockpos.below()).is(BlockTags.SAND)
                && this.getRandom().nextInt(1 + IafConfig.deathWormSpawnCheckChance) == 0
                && this.level.getMaxLocalRawBrightness(blockpos) > 8;
