                    }
                });
            } else {
                final int radius = stage == 4 ? 2 : 3;
                j = radius + world.random.nextInt(2);
                k = radius + world.random.nextInt(2);
                l = radius + world.random.nextInt(2);
                final float f = (float) (j + k + l) * 0.333F + 0.5F;
