@Override
    public boolean place(FeaturePlaceContext<NoneFeatureConfiguration> context) {
        WorldGenLevel worldIn = context.level();
        Random rand = context.random();
        BlockPos position = context.origin();
        if (rand.nextInt(IafConfig.generateDragonRoostChance) != 0 || !IafWorldRegistry.isFarEnoughFromSpawn(worldIn, position) || !IafWorldRegistry.isFarEnoughFromDangerousGen(worldIn, position, "dragon_roost")) {
            return false;
        }
        if (!worldIn.getFluidState(worldIn.getHeightmapPos(Heightmap.Types.WORLD_SURFACE_WG, position).below()).isEmpty()) {
            return false;
        }
        isMale = new Random().nextBoolean();
        int radius = 12 + rand.nextInt(8);
        worldIn.setBlock(position, Blocks.AIR.defaultBlockState(), 2);
        if (!worldIn.isClientSide()) {
            EntityDragonBase dragon = IafEntityRegistry.LIGHTNING_DRAGON.get().create(worldIn.getLevel());
            dragon.setGender(isMale);
            dragon.setPersistenceRequired();
            dragon.growDragon(40 + radius);
            dragon.setAgingDisabled(true);
            dragon.setHealth(dragon.getMaxHealth());
            dragon.setVariant(new Random().nextInt(4));
            dragon.absMoveTo(position.getX() + 0.5, 1 + worldIn.getHeightmapPos(Heightmap.Types.WORLD_SURFACE_WG, position).getY() + 1.5, position.getZ() + 0.5, rand.nextFloat() * 360, 0);
            dragon.homePos = new HomePosition(position, worldIn.getLevel());
            dragon.hasHomePosition = true;
            dragon.setHunger(50);
            dragon.setInSittingPose(true);
            worldIn.addFreshEntity(dragon);
        }
        {
            int j = radius;
            int k = 2;
            int l = radius;
            float f = (j + k + l) * 0.333F + 0.5F;
            BlockPos.betweenClosedStream(position.offset(-j, k, -l), position.offset(j, 0, l)).map(BlockPos::immutable).forEach(blockPos -> {
                int yAdd = blockPos.getY() - position.getY();
                if (blockPos.distSqr(position) <= f * f && yAdd < 2 + rand.nextInt(k) && !worldIn.isEmptyBlock(blockPos.below())) {
                    if (worldIn.isEmptyBlock(blockPos.above()))
                        worldIn.setBlock(blockPos, IafBlockRegistry.CRACKLED_DIRT.get().defaultBlockState(), 2);
                    else
                        worldIn.setBlock(blockPos, IafBlockRegistry.CRACKLED_GRASS.get().defaultBlockState(), 2);
                }
            });
        }
        {
            int j = radius;
            int k = (radius / 5);
            int l = radius;
            float f = (j + k + l) * 0.333F + 0.5F;
            BlockPos.betweenClosedStream(position.offset(-j, -k, -l), position.offset(j, 1, l)).map(BlockPos::immutable).forEach(blockPos -> {
                if (blockPos.distSqr(position) < f * f) {
                    worldIn.setBlock(blockPos, rand.nextBoolean() ? IafBlockRegistry.CRACKLED_GRAVEL.get().defaultBlockState() : IafBlockRegistry.CRACKLED_DIRT.get().defaultBlockState(), 2);
                } else if (blockPos.distSqr(position) == f * f) {
                    worldIn.setBlock(blockPos, IafBlockRegistry.CRACKLED_COBBLESTONE.get().defaultBlockState(), 2);
                }
            });
        }
        radius -= 2;
        {
            int j = radius;
            int k = 2;
            int l = radius;
            float f = (j + k + l) * 0.333F + 0.5F;
            BlockPos up = position.above(k - 1);
            BlockPos.betweenClosedStream(up.offset(-j, -k + 2, -l), up.offset(j, k, l)).map(BlockPos::immutable).forEach(blockPos -> {
                if (blockPos.distSqr(position) <= f * f) {
                    worldIn.setBlock(blockPos, Blocks.AIR.defaultBlockState(), 2);
                }
            });
        }
        radius += 15;
        {
            int j = radius;
            int k = (radius / 5);
            int l = radius;
            float f = (j + k + l) * 0.333F + 0.5F;
            BlockPos.betweenClosedStream(position.offset(-j, -k, -l), position.offset(j, k, l)).map(BlockPos::immutable).forEach(blockPos -> {
                if (blockPos.distSqr(position) <= f * f) {
                    double dist = blockPos.distSqr(position) / (f * f);
                    if (!worldIn.isEmptyBlock(position) && rand.nextDouble() > dist * 0.5D) {
                        transformState(worldIn, blockPos, worldIn.getBlockState(blockPos));
                    }
                    if (dist > 0.5D && rand.nextInt(1000) == 0) {
                        BlockPos height = worldIn.getHeightmapPos(Heightmap.Types.WORLD_SURFACE_WG, blockPos);
                        new WorldGenRoostBoulder(IafBlockRegistry.CRACKLED_COBBLESTONE.get(), rand.nextInt(3), true).generate(worldIn, rand, height);
                    }
                    if (dist > 0.05D && rand.nextInt(800) == 0) {
                        BlockPos height = worldIn.getHeightmapPos(Heightmap.Types.WORLD_SURFACE_WG, blockPos);
                        new WorldGenRoostSpire().generate(worldIn, rand, height);
                    }
                    if (dist > 0.05D && rand.nextInt(1000) == 0) {
                        BlockPos height = worldIn.getHeightmapPos(Heightmap.Types.WORLD_SURFACE_WG, blockPos);
                        new WorldGenRoostSpike(HORIZONTALS[rand.nextInt(3)]).generate(worldIn, rand, height);
                    }
                    if (dist < 0.3D && rand.nextInt(isMale ? 250 : 400) == 0) {
                        BlockPos height = WorldGenUtils.degradeSurface(worldIn, worldIn.getHeightmapPos(Heightmap.Types.WORLD_SURFACE_WG, blockPos)).above();
                        new WorldGenRoostGoldPile(IafBlockRegistry.COPPER_PILE.get()).generate(worldIn, rand, height);
                    }
                    if (dist < 0.3D && rand.nextInt(isMale ? 500 : 700) == 0) {
                        BlockPos height = WorldGenUtils.degradeSurface(worldIn, worldIn.getHeightmapPos(Heightmap.Types.WORLD_SURFACE_WG, blockPos)).above();
                        worldIn.setBlock(height, Blocks.CHEST.defaultBlockState().setValue(ChestBlock.FACING, HORIZONTALS[new Random().nextInt(3)]), 2);
                        if (worldIn.getBlockState(height).getBlock() instanceof ChestBlock) {
                            BlockEntity tileentity1 = worldIn.getBlockEntity(height);
                            if (tileentity1 instanceof ChestBlockEntity) {
                                ((ChestBlockEntity) tileentity1).setLootTable(DRAGON_CHEST, new Random().nextLong());
                            }
                        }
                    }
                    if (rand.nextInt(6000) == 0) {
                        BlockPos height = worldIn.getHeightmapPos(Heightmap.Types.WORLD_SURFACE_WG, blockPos);
                        new WorldGenRoostArch(IafBlockRegistry.CRACKLED_COBBLESTONE.get()).generate(worldIn, rand, height);
                    }
                }
            });
        }
        return false;
    }

private void transformState(LevelAccessor world, BlockPos blockpos, BlockState state) {
        float hardness = state.getDestroySpeed(world, blockpos);
        if (hardness != -1.0F) {
            if (state.getBlock() instanceof BaseEntityBlock) {
                return;
            }
            if (state.getMaterial() == Material.GRASS) {
                world.setBlock(blockpos, IafBlockRegistry.CRACKLED_GRASS.get().defaultBlockState(), 2);
            } else if (state.getMaterial() == Material.DIRT && state.getBlock() == Blocks.DIRT) {
                world.setBlock(blockpos, IafBlockRegistry.CRACKLED_DIRT.get().defaultBlockState(), 2);
            } else if (state.getMaterial() == Material.DIRT && state.getBlock() == Blocks.GRAVEL) {
                world.setBlock(blockpos, IafBlockRegistry.CRACKLED_GRAVEL.get().defaultBlockState(), 2);
            } else if (state.getMaterial() == Material.STONE && (state.getBlock() == Blocks.COBBLESTONE || state.getBlock().getDescriptionId().contains("cobblestone"))) {
                world.setBlock(blockpos, IafBlockRegistry.CRACKLED_COBBLESTONE.get().defaultBlockState(), 2);
            } else if (state.getMaterial() == Material.STONE && state.getBlock() != IafBlockRegistry.CRACKLED_COBBLESTONE.get()) {
                world.setBlock(blockpos, IafBlockRegistry.CRACKLED_STONE.get().defaultBlockState(), 2);
            } else if (state.getBlock() == Blocks.DIRT_PATH) {
                world.setBlock(blockpos, IafBlockRegistry.CRACKLED_DIRT_PATH.get().defaultBlockState(), 2);
            } else if (state.getMaterial() == Material.WOOD) {
                world.setBlock(blockpos, IafBlockRegistry.ASH.get().defaultBlockState(), 2);
            } else if (state.getMaterial() == Material.LEAVES || state.getMaterial() == Material.PLANT) {
                world.setBlock(blockpos, Blocks.AIR.defaultBlockState(), 2);
            }
        }
    }

public static void generateSkeleton(LevelAccessor worldIn, BlockPos blockpos, BlockPos origin, int radius, Random rand) {
        if (worldIn.getBlockState(blockpos.below()).isFaceSturdy(worldIn, blockpos.below(), Direction.UP)) {
            Direction direction = Direction.from2DDataValue(rand.nextInt(3));
            Direction.Axis oppositeAxis = direction.getAxis() == Direction.Axis.X ? Direction.Axis.Z : Direction.Axis.X;
            int maxRibHeight = rand.nextInt(2);
            for (int spine = 0; spine < 5 + rand.nextInt(2) * 2; spine++) {
                BlockPos segment = blockpos.relative(direction, spine);
                if (origin.distSqr(segment) <= (double) (radius * radius)) {
                    worldIn.setBlock(segment, Blocks.BONE_BLOCK.defaultBlockState().setValue(RotatedPillarBlock.AXIS, direction.getAxis()), 2);
                }
                if (spine % 2 != 0) {
                    BlockPos rightRib = segment.relative(direction.getCounterClockWise());
                    BlockPos leftRib = segment.relative(direction.getClockWise());
                    if (origin.distSqr(rightRib) <= (double) (radius * radius)) {
                        worldIn.setBlock(rightRib, Blocks.BONE_BLOCK.defaultBlockState().setValue(RotatedPillarBlock.AXIS, oppositeAxis), 2);
                    }
                    if (origin.distSqr(leftRib) <= (double) (radius * radius)) {
                        worldIn.setBlock(leftRib, Blocks.BONE_BLOCK.defaultBlockState().setValue(RotatedPillarBlock.AXIS, oppositeAxis), 2);
                    }
                    for (int ribHeight = 1; ribHeight < maxRibHeight + 2; ribHeight++) {
                        if (origin.distSqr(rightRib.above(ribHeight).relative(direction.getCounterClockWise())) <= (double) (radius * radius)) {
                            worldIn.setBlock(rightRib.above(ribHeight).relative(direction.getCounterClockWise()), Blocks.BONE_BLOCK.defaultBlockState().setValue(RotatedPillarBlock.AXIS, Direction.Axis.Y), 2);
                        }
                        if (origin.distSqr(leftRib.above(ribHeight).relative(direction.getClockWise())) <= (double) (radius * radius)) {
                            worldIn.setBlock(leftRib.above(ribHeight).relative(direction.getClockWise()), Blocks.BONE_BLOCK.defaultBlockState().setValue(RotatedPillarBlock.AXIS, Direction.Axis.Y), 2);
                        }
                    }
                    if (origin.distSqr(rightRib.above(maxRibHeight + 2)) <= (double) (radius * radius)) {
                        worldIn.setBlock(rightRib.above(maxRibHeight + 2), Blocks.BONE_BLOCK.defaultBlockState().setValue(RotatedPillarBlock.AXIS, oppositeAxis), 2);
                    }
                    if (origin.distSqr(leftRib.above(maxRibHeight + 2)) <= (double) (radius * radius)) {
                        worldIn.setBlock(leftRib.above(maxRibHeight + 2), Blocks.BONE_BLOCK.defaultBlockState().setValue(RotatedPillarBlock.AXIS, oppositeAxis), 2);
                    }
                }
            }
        }
    }

public static void generateLeaves(LevelAccessor worldIn, BlockPos blockpos, BlockPos origin, int radius, Random rand, boolean jungle) {
        if (worldIn.getBlockState(blockpos.below()).isFaceSturdy(worldIn, blockpos.below(), Direction.UP)) {
            BlockState leaf = Blocks.OAK_LEAVES.defaultBlockState().setValue(LeavesBlock.PERSISTENT, Boolean.TRUE);
            if (jungle) {
                leaf = Blocks.JUNGLE_LEAVES.defaultBlockState().setValue(LeavesBlock.PERSISTENT, Boolean.TRUE);
            }
            int i1 = 0;
            for (int i = 0; i1 >= 0 && i < 3; ++i) {
                int j = i1 + rand.nextInt(2);
                int k = i1 + rand.nextInt(2);
                int l = i1 + rand.nextInt(2);
                float f = (float) (j + k + l) * 0.333F + 0.5F;
                for (BlockPos pos : BlockPos.betweenClosedStream(blockpos.offset(-j, -k, -l), blockpos.offset(j, k, l)).map(BlockPos::immutable).collect(Collectors.toSet())) {
                    if (pos.distSqr(blockpos) <= (double) (f * f) && worldIn.isEmptyBlock(pos)) {
                        worldIn.setBlock(pos, leaf, 4);
                    }
                }
                blockpos = blockpos.offset(-(i1 + 1) + rand.nextInt(2 + i1 * 2), -rand.nextInt(2), -(i1 + 1) + rand.nextInt(2 + i1 * 2));
            }
        }
    }

