private static String toConfigKey(String storagePrefix) {
			String[] parts = storagePrefix.split(" ");
			StringBuilder key = new StringBuilder();
			for (int i = 0; i < parts.length; i++) {
				String part = switch (parts[i]) {
					case "IV" -> "4";
					case "III" -> "3";
					case "II" -> "2";
					case "I" -> "1";
					default -> parts[i];
				};

				if (i == 0) {
					key.append(part.substring(0, 1).toLowerCase(Locale.ROOT)).append(part.substring(1));
				} else if (Character.isDigit(part.charAt(0))) {
					key.append(part);
				} else {
					key.append(part.substring(0, 1).toUpperCase(Locale.ROOT)).append(part.substring(1));
				}
			}
			return key.toString();
		}

