@Override
	public ItemInteractionResult useItemOn(ItemStack stack, BlockState state, Level level, BlockPos pos, Player player, InteractionHand hand,
			BlockHitResult hitResult) {
		return WorldHelper.getBlockEntity(level, pos, WoodStorageBlockEntity.class).map(b -> {
			if (b.isPacked()) {
				return ItemInteractionResult.FAIL;
			}
			if (level.isClientSide || hand == InteractionHand.OFF_HAND) {
				return ItemInteractionResult.SUCCESS;
			}

			if (tryItemInteraction(player, hand, b, stack, getFacing(state), hitResult)) {
				return ItemInteractionResult.SUCCESS;
			}
			return ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION;
		}).orElse(ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION);
	}

