public static Optional<TintColors> getTintColors(WoodType woodType) {
		Optional<TintColors> tintColors = TINT_CACHE.getIfPresent(woodType);
		if (tintColors == null) {
			tintColors = calculateTintColors(woodType);
			TINT_CACHE.put(woodType, tintColors);
		}
		return tintColors;
	}

public static int getMainColor(WoodType woodType) {
		return getTintColors(woodType).map(TintColors::mainColor).orElse(-1);
	}

public static int getAccentColor(WoodType woodType) {
		return getMainColor(woodType);
	}

private static Optional<TintColors> calculateTintColors(WoodType woodType) {
		return GenericWoodStorageHelper.getGenericWoodInfo(woodType).flatMap(info -> {
			try {
				TextureAtlasSprite sprite = RenderHelper.getSprite(info.planksLocation(), null, RandomSource.create());
				NativeImage image = sprite.contents().getOriginalImage();
				List<ColorGroup> colorGroups = getColorGroups(image, sprite.contents().width(), sprite.contents().height());
				if (colorGroups.isEmpty()) {
					return Optional.empty();
				}

				ColorGroup mainGroup = colorGroups.get(0);
				int mainColor = FastColor.ARGB32.opaque(mainGroup.getRepresentativeColor());
				return Optional.of(new TintColors(mainColor));
			} catch (Exception e) {
				return Optional.empty();
			}
		});
	}

private static List<ColorGroup> getColorGroups(NativeImage image, int width, int height) {
		Map<Integer, Integer> colorCounts = new HashMap<>();
		for (int y = 0; y < height; y++) {
			for (int x = 0; x < width; x++) {
				int color = FastColor.ABGR32.fromArgb32(image.getPixelRGBA(x, y));
				if (FastColor.ARGB32.alpha(color) < 32 || touchesTransparentPixel(image, width, height, x, y)) {
					continue;
				}
				colorCounts.merge(color & 0xFFFFFF, 1, Integer::sum);
			}
		}

		List<ColorGroup> colorGroups = new ArrayList<>();
		for (Map.Entry<Integer, Integer> colorCount : colorCounts.entrySet()) {
			int color = colorCount.getKey();
			Optional<ColorGroup> matchingGroup = colorGroups.stream().filter(group -> group.distanceTo(color) <= MAX_MERGE_DISTANCE).findFirst();
			if (matchingGroup.isPresent()) {
				matchingGroup.get().add(color, colorCount.getValue());
			} else {
				colorGroups.add(new ColorGroup(color, colorCount.getValue()));
			}
		}
		colorGroups.sort(Comparator.comparingInt(ColorGroup::totalWeight).reversed());
		return colorGroups;
	}

private static boolean touchesTransparentPixel(NativeImage image, int width, int height, int x, int y) {
		for (int dy = -1; dy <= 1; dy++) {
			for (int dx = -1; dx <= 1; dx++) {
				if (dx == 0 && dy == 0) {
					continue;
				}
				int neighborX = x + dx;
				int neighborY = y + dy;
				if (neighborX < 0 || neighborY < 0 || neighborX >= width || neighborY >= height) {
					continue;
				}
				int color = FastColor.ABGR32.fromArgb32(image.getPixelRGBA(neighborX, neighborY));
				if (FastColor.ARGB32.alpha(color) < 32) {
					return true;
				}
			}
		}
		return false;
	}

ColorGroup(int color, int weight) {
			add(color, weight);
		}

void add(int color, int weight) {
			redSum += FastColor.ARGB32.red(color) * weight;
			greenSum += FastColor.ARGB32.green(color) * weight;
			blueSum += FastColor.ARGB32.blue(color) * weight;
			totalWeight += weight;
			colors.add(color);
		}

int totalWeight() {
			return totalWeight;
		}

int getRepresentativeColor() {
			int averageColor = getAverageColor();
			int bestColor = colors.get(0);
			double bestDistance = Double.MAX_VALUE;
			for (int color : colors) {
				double distance = colorDistance(averageColor, color);
				if (distance < bestDistance) {
					bestDistance = distance;
					bestColor = color;
				}
			}
			return bestColor;
		}

double distanceTo(int color) {
			return colorDistance(getAverageColor(), color);
		}

private int getAverageColor() {
			if (totalWeight == 0) {
				return 0;
			}
			return FastColor.ARGB32.color(redSum / totalWeight, greenSum / totalWeight, blueSum / totalWeight);
		}

private static double colorDistance(int firstColor, int secondColor) {
			int dr = FastColor.ARGB32.red(firstColor) - FastColor.ARGB32.red(secondColor);
			int dg = FastColor.ARGB32.green(firstColor) - FastColor.ARGB32.green(secondColor);
			int db = FastColor.ARGB32.blue(firstColor) - FastColor.ARGB32.blue(secondColor);
			return Math.sqrt(dr * dr + dg * dg + db * db);
		}

private StorageTextureManager() {
		super(GSON, "storage_texture_definitions");
	}

@Override
	protected Map<ResourceLocation, JsonElement> prepare(ResourceManager resourceManager, ProfilerFiller profiler) {
		clear();
		Map<ResourceLocation, JsonElement> fileContents = super.prepare(resourceManager, profiler);
		Map<ResourceLocation, StorageTextureDefinition> storageTextureDefinitions = new HashMap<>();
		fileContents.forEach((resourceLocation, json) -> loadDefinition(storageTextureDefinitions, resourceLocation, json, fileContents));

		storageTextureDefinitions.forEach((fileName, definition) -> {
			String type = definition.getType();
			String filePath = fileName.getPath();
			if (type.equals("chest") && filePath.endsWith(CHEST_SUFFIX)) {
				WoodType.values().filter(wt -> wt.name().equals(filePath.substring(0, filePath.lastIndexOf(CHEST_SUFFIX)))).findFirst().ifPresent(wt -> {
					Map<ChestType, Map<ChestMaterial, Material>> chestMaterials = new EnumMap<>(ChestType.class);
					definition.getTextures()
							.forEach((chestTypeName, textures) -> textures.forEach((textureName, rl) -> ChestMaterial.fromString(textureName)
									.ifPresent(cm -> chestMaterials
											.computeIfAbsent(ChestType.valueOf(chestTypeName.toUpperCase(Locale.ROOT)), t -> new EnumMap<>(ChestMaterial.class))
											.put(cm, new Material(Sheets.CHEST_SHEET, rl)))));
					woodChestMaterials.put(wt, chestMaterials);
				});
			}
		});
		return fileContents;
	}

private void clear() {
		woodChestMaterials.clear();
		GenericWoodStorageTintCache.clear();
	}

@Override
	protected void apply(Map<ResourceLocation, JsonElement> object, ResourceManager resourceManager, ProfilerFiller profiler) {
		// noop as everything is done in prepare due to the need to have it done before TextureStitchEvent fires
	}

@Nullable // can return null when resources are reloading and this collection was cleared
	public Map<ChestMaterial, Material> getWoodChestMaterials(ChestType chestType, WoodType woodType) {
		Map<ChestType, Map<ChestMaterial, Material>> chestTypeMaterials = woodChestMaterials.getOrDefault(woodType,
				woodChestMaterials.get(defaultChestWoodType));
		return chestTypeMaterials == null ? null : chestTypeMaterials.get(chestType);
	}

private Optional<StorageTextureDefinition> loadDefinition(Map<ResourceLocation, StorageTextureDefinition> storageTextureDefinitions,
			ResourceLocation resourceLocation, JsonElement json, Map<ResourceLocation, JsonElement> fileContents) {
		// already loaded probably because it is a parent to another definition
		if (storageTextureDefinitions.containsKey(resourceLocation)) {
			return Optional.of(storageTextureDefinitions.get(resourceLocation));
		}

		if (!json.isJsonObject()) {
			return Optional.empty();
		}

		JsonObject jsonContents = json.getAsJsonObject();

		String type = "";

		@Nullable
		StorageTextureDefinition parentDefinition = null;

		if (jsonContents.has(PARENT_TAG) && jsonContents.get(PARENT_TAG).isJsonPrimitive()) {
			ResourceLocation parent = ResourceLocation.parse(jsonContents.get(PARENT_TAG).getAsString());
			JsonElement parentJson = fileContents.get(parent);
			parentDefinition = loadDefinition(storageTextureDefinitions, parent, parentJson, fileContents).orElse(null);
			if (parentDefinition != null) {
				type = parentDefinition.getType();
			}
		}

		if (jsonContents.has(TYPE_TAG) && jsonContents.get(TYPE_TAG).isJsonPrimitive()) {
			type = jsonContents.get(TYPE_TAG).getAsString();
		}

		if (!TEXTURE_PARSERS.containsKey(type)) {
			return Optional.empty();
		}

		ITextureParser textureParser = TEXTURE_PARSERS.get(type).get();

		if (parentDefinition != null) {
			textureParser.copyFromParentDefinition(parentDefinition);
		}

		Optional<StorageTextureDefinition> result = textureParser.parseDefinition(type, jsonContents);
		result.ifPresent(def -> storageTextureDefinitions.put(resourceLocation, def));

		return result;
	}

@SuppressWarnings({"unused", "java:S1172"})
		// ignoring unused parameter bNatcause it's needed due to two constructors with the same erasure
		public StorageTextureDefinition(String type, Map<String, Map<String, Map<String, ResourceLocation>>> multiplePartTextures,
				boolean multipleTextureIgnoredParameter) {
			this.type = type;
			textures = multiplePartTextures;
		}

public StorageTextureDefinition(String type, Map<String, Map<String, ResourceLocation>> textures) {
			this.type = type;
			this.textures = new HashMap<>();
			this.textures.put(ALL_SIDES_TEXTURES, textures);
		}

public String getType() {
			return type;
		}

public Map<String, Map<String, ResourceLocation>> getTextures() {
			return textures.getOrDefault(ALL_SIDES_TEXTURES, new HashMap<>());
		}

@Override
		public void copyFromParentDefinition(StorageTextureDefinition parentDefinition) {
			parentDefinition.getTextures().forEach((key, value) -> textures.put(key, new HashMap<>(value)));
		}

@Override
		public Optional<StorageTextureDefinition> parseDefinition(String type, JsonObject jsonContents) {
			if (jsonContents.has(TEXTURES_TAG) && jsonContents.get(TEXTURES_TAG).isJsonObject()) {
				JsonObject jsonTextures = jsonContents.get(TEXTURES_TAG).getAsJsonObject();

				jsonTextures.keySet().forEach(name -> jsonTextures.get(name).getAsJsonObject().entrySet().forEach(entry -> {
					if (entry.getValue().isJsonPrimitive()) {
						textures.computeIfAbsent(name, k -> new HashMap<>()).put(entry.getKey(), ResourceLocation.parse(entry.getValue().getAsString()));
					}
				}));
			}

			return Optional.of(new StorageTextureDefinition(type, textures));
		}

public static Optional<ChestMaterial> fromString(String materialName) {
			for (ChestMaterial value : values()) {
				if (value.name().toLowerCase(Locale.ROOT).equals(materialName)) {
					return Optional.of(value);
				}
			}
			return Optional.empty();
		}

