			case 2 -> LIMITED_II_BACKGROUND;
			case 3 -> LIMITED_III_BACKGROUND;
			case 4 -> LIMITED_IV_BACKGROUND;
			default -> throw new IllegalStateException("Unexpected number of limited barrel slots: " + slotsNumber);
		};
