			if (tintIndex == 1000) {
				return StorageBlockItem.getMainColorFromComponentHolder(stack).orElseGet(() -> WoodStorageBlockItem.getWoodType(stack)
						.filter(GenericWoodStorageHelper::isGenericWood).map(GenericWoodStorageTintCache::getMainColor).orElse(-1));
			} else {
				return StorageBlockItem.getAccentColorFromComponentHolder(stack).orElseGet(() -> WoodStorageBlockItem.getWoodType(stack)
						.filter(GenericWoodStorageHelper::isGenericWood).map(GenericWoodStorageTintCache::getAccentColor).orElse(-1));
