@SuppressWarnings({"java:S1874", "deprecation"}) // overriding getElements here
	@Override
	public List<BlockElement> getElements() {
		return elements;
	}

@Override
	public void resolveParents(Function<ResourceLocation, UnbakedModel> modelGetter) {
		super.resolveParents(modelGetter);

		copyElementsFromAllIncludedModels();
		copyTexturesFromAllIncludedModels();
	}

@SuppressWarnings({"java:S1874", "deprecation"}) // need to call getElements even though deprecated
	private void copyElementsFromAllIncludedModels() {
		if (parent != null) {
			elements.addAll(parent.getElements());
			if (parent.customData.hasCustomGeometry() && parent.customData.getCustomGeometry() instanceof SimpleCompositeModel simpleCompositeModel) {
				elements.addAll(simpleCompositeModel.getElements());
			}
		}
	}

@SuppressWarnings("java:S5803") // need to call textureMap here even though only visible for testing
	private void copyTexturesFromAllIncludedModels() {
		if (parent != null) {
			parent.textureMap.forEach(textureMap::putIfAbsent);
			if (parent.customData.hasCustomGeometry() && parent.customData.getCustomGeometry() instanceof SimpleCompositeModel simpleCompositeModel) {
				simpleCompositeModel.getTextures().forEach(textureMap::putIfAbsent);
			}
		}
	}

@Override
	public Material getMaterial(String textureName) {
		if (textureName.charAt(0) == '#') {
			textureName = textureName.substring(1);
		}

		List<String> visitedTextureReferences = Lists.newArrayList();
		while (true) {
			Either<Material, String> either = findTexture(textureName);
			Optional<Material> optional = either.left();
			if (optional.isPresent()) {
				return optional.get();
			}

			textureName = either.right().orElse("");

			if (visitedTextureReferences.contains(textureName)) {
				String finalTextureName = textureName;
				SophisticatedStorage.LOGGER.warn("Unable to resolve texture due to reference chain {}->{} in {}",
						() -> Joiner.on("->").join(visitedTextureReferences), () -> finalTextureName, () -> name);
				return new Material(InventoryMenu.BLOCK_ATLAS, MissingTextureAtlasSprite.getLocation());
			}

			visitedTextureReferences.add(textureName);
		}
	}

private Either<Material, String> findTexture(String textureName) {
		for (BlockModel blockmodel = this; blockmodel != null; blockmodel = blockmodel.parent) {
			Either<Material, String> either = blockmodel.textureMap.get(textureName);
			if (either != null) {
				return either;
			}
		}

		return Either.left(new Material(InventoryMenu.BLOCK_ATLAS, MissingTextureAtlasSprite.getLocation()));
	}

@Override
	public void render(ControllerBlockEntity controller, float partialTick, PoseStack poseStack, MultiBufferSource bufferSource, int packedLight,
			int packedOverlay) {
		SimpleMaterialOverlayRenderer.renderHiddenOverlay(controller, poseStack, bufferSource, packedLight, packedOverlay);

		LocalPlayer player = Minecraft.getInstance().player;
		if (player == null) {
			return;
		}
		ClientLevel level = Minecraft.getInstance().level;

		if (level == null) {
			return;
		}

		InventoryHelper.getItemFromEitherHand(player, ModItems.DEBUG_TOOL.get()).ifPresent(
				storageTool -> renderConnectedStorageBlocksInfo(controller, Direction.orderedByNearest(player)[0].getOpposite(), poseStack, bufferSource));
		InventoryHelper.getItemFromEitherHand(player, ModItems.STORAGE_TOOL.get()).ifPresent(storageTool -> {
			if (StorageToolItem.getMode(storageTool) != StorageToolItem.Mode.LINK) {
				return;
			}

			if (StorageToolItem.getControllerLink(storageTool).map(controllerPos -> controllerPos.equals(controller.getBlockPos())).orElse(false)) {
				renderControllerOutline(controller, poseStack, bufferSource);
			}
			renderLinkedBlocks(controller, level, poseStack, bufferSource);
			renderStorageBlocksOutline(controller, poseStack, bufferSource);
		});
	}

private void renderConnectedStorageBlocksInfo(ControllerBlockEntity controller, Direction playerLookDirection, PoseStack poseStack,
			MultiBufferSource bufferSource) {
		Font fontRenderer = Minecraft.getInstance().font;
		double zScale = 0.001;
		float scale = 0.015f;
		int storageOrder = 1;
		for (BlockPos position : controller.getStoragePositions()) {
			BlockPos controllerPos = controller.getBlockPos();

			double translateX = position.getX() + 0.5 - controllerPos.getX() + 0.501 * (playerLookDirection.getNormal().getX());
			double translateY = position.getY() + 0.5 - controllerPos.getY() + 0.501 * (playerLookDirection.getNormal().getY());
			double translateZ = position.getZ() + 0.5 - controllerPos.getZ() + 0.501 * (playerLookDirection.getNormal().getZ());

			poseStack.pushPose();
			poseStack.translate(translateX, translateY, translateZ);
			Quaternionf rotation = playerLookDirection.getRotation();
			rotation.mul(Axis.XP.rotationDegrees(-90.0F));
			poseStack.mulPose(rotation);
			poseStack.translate(-0.45f, 0.45f, 0);

			poseStack.scale(scale, -scale, (float) zScale);
			fontRenderer.drawInBatch("Order: " + storageOrder, 0, 0, DyeColor.WHITE.getTextColor(), false, poseStack.last().pose(), bufferSource,
					Font.DisplayMode.SEE_THROUGH, 0, 15728880);
			poseStack.translate(0, 10, 0);
			fontRenderer.drawInBatch("Slots: " + controller.getSlots(storageOrder - 1), 0, 0, DyeColor.WHITE.getTextColor(), false, poseStack.last().pose(),
					bufferSource, Font.DisplayMode.SEE_THROUGH, 0, 15728880);
			poseStack.popPose();

			storageOrder++;
		}
	}

private void renderLinkedBlocks(ControllerBlockEntity controller, ClientLevel level, PoseStack poseStack, MultiBufferSource bufferSource) {
		controller.getLinkedBlocks().forEach(pos -> {
			BlockState state = level.getBlockState(pos);
			VoxelShape shape = state.getShape(level, pos, CollisionContext.empty());
			renderLineBetweenBlocks(controller.getBlockPos(), pos, shape, poseStack, bufferSource, DyeColor.LIME.getTextColor());
		});
		BlockHighlightRenderHelper.renderThickEdges(poseStack, bufferSource, DyeColor.LIME.getTextColor(), controller.getLinkedBlockEdges(),
				controller.getBlockPos());
	}

private void renderStorageBlocksOutline(ControllerBlockEntity controller, PoseStack poseStack, MultiBufferSource bufferSource) {
		BlockHighlightRenderHelper.renderThickEdges(poseStack, bufferSource, 0x69c53b, controller.getStorageBlockEdges(), controller.getBlockPos());
	}

private void renderLineBetweenBlocks(BlockPos initialPos, BlockPos pos, VoxelShape shape, PoseStack poseStack, MultiBufferSource bufferSource, int color) {
		if (shape.isEmpty()) {
			return;
		}

		int red = color >> 16 & 255;
		int green = color >> 8 & 255;
		int blue = color & 255;

		Vec3 center = shape.bounds().getCenter();

		VertexConsumer buffer = bufferSource.getBuffer(LINES);

		PoseStack.Pose pose = poseStack.last();
		Matrix4f matrix4f = pose.pose();
		float normalX = (float) (pos.getX() - initialPos.getX() + (0.5F - center.x()));
		float normalY = (float) (pos.getY() - initialPos.getY() + (0.5F - center.y()));
		float normalZ = (float) (pos.getZ() - initialPos.getZ() + (0.5F - center.z()));
		buffer.addVertex(matrix4f, 0.5F, 0.5F, 0.5F).setColor(red, green, blue, 255).setNormal(pose, normalX, normalY, normalZ);
		buffer.addVertex(matrix4f, (float) (pos.getX() - initialPos.getX() + center.x()), (float) (pos.getY() - initialPos.getY() + center.y()),
				(float) (pos.getZ() - initialPos.getZ() + center.z())).setColor(red, green, blue, 255).setNormal(pose, normalX, normalY, normalZ);
	}

