private void renderItemCounts(LimitedBarrelBlockEntity blockEntity, PoseStack poseStack, MultiBufferSource bufferSource, boolean flatTop,
			Direction horizontalFacing, VerticalFacing verticalFacing, int packedLight) {
		if (!blockEntity.shouldShowCounts()) {
			return;
		}

		if (blockEntity.getLevel() != null) {
			packedLight = LevelRenderer.getLightColor(blockEntity.getLevel(),
					blockEntity.getBlockPos().relative(verticalFacing != VerticalFacing.NO ? verticalFacing.getDirection() : horizontalFacing));
		}

		poseStack.pushPose();

		poseStack.translate(0.5, 0.5, 0.5);
		poseStack.mulPose(DisplayItemRenderer.getNorthBasedRotation(horizontalFacing.getOpposite()));// because of the font flipping
		if (verticalFacing != VerticalFacing.NO) {
			poseStack.mulPose(DisplayItemRenderer.getNorthBasedRotation(verticalFacing.getDirection().getOpposite()));// because of the font flipping
		}
		poseStack.translate(0.5, -0.5, 0.5);

		RenderInfo.ItemDisplayRenderInfo itemDisplayRenderInfo = blockEntity.getStorageWrapper().getRenderInfo().getItemDisplayRenderInfo();
		List<Integer> slotCounts = itemDisplayRenderInfo.getSlotCounts();
		List<Integer> infiniteSlots = itemDisplayRenderInfo.getInfiniteSlots();
		if (slotCounts.isEmpty()) {
			slotCounts = blockEntity.getSlotCounts();
		}
		float countDisplayYOffset = -(slotCounts.size() == 1 ? 0.25f : 0.11f);
		for (int displayItemIndex = 0; displayItemIndex < slotCounts.size(); displayItemIndex++) {
			int count = slotCounts.get(displayItemIndex);
			if (count <= 0) {
				continue;
			}

			poseStack.pushPose();
			Vector3f frontOffset = DisplayItemRenderer.getDisplayItemIndexFrontOffset(displayItemIndex, slotCounts.size());

			double xTranslation = -frontOffset.x();
			boolean isInfinite = infiniteSlots.contains(displayItemIndex);
			float yTranslation = frontOffset.y() + (isInfinite ? countDisplayYOffset / 1.8f : countDisplayYOffset);
			double zTranslation = 0.001 - (flatTop ? 0 : 0.75 / 16D);
			poseStack.translate(xTranslation, yTranslation, zTranslation);

			float scale = slotCounts.size() == 1 ? SINGLE_ITEM_FONT_SCALE : MULTIPLE_ITEMS_FONT_SCALE;
			if (isInfinite) {
				scale *= 2;
			}
			poseStack.scale(scale, -scale, scale);
			MutableComponent countString;
			if (isInfinite) {
				countString = Component.literal("∞").withStyle(INFINITE_COUNT_DISPLAY_STYLE);
			} else {
				countString = Component.literal(CountAbbreviator.abbreviate(count, slotCounts.size() == 1 ? 6 : 5)).withStyle(COUNT_DISPLAY_STYLE);
			}
			Font font = Minecraft.getInstance().font;
			float countDisplayXOffset = -font.getSplitter().stringWidth(countString) / 2f;
			poseStack.translate(countDisplayXOffset, 0, 0);
			font.drawInBatch(countString, 0, 0, blockEntity.getSlotColor(displayItemIndex), false, poseStack.last().pose(), bufferSource,
					Font.DisplayMode.NORMAL, 0, packedLight);

			poseStack.popPose();
		}
		poseStack.popPose();
	}

private void renderFillLevel(PoseStack poseStack, MultiBufferSource bufferSource, int packedLight, int packedOverlay, float fillLevel, float x, float y,
			boolean large, boolean translucentRender) {
		poseStack.pushPose();
		poseStack.translate(x + 1 / 16F / 5F, y + 1 / 16F / 5F, 0);
		int barHeight = large ? 14 : 6;
		poseStack.scale(1 / 16F / 5F * 3, fillLevel * 1 / 16F / 5F * (barHeight * 5 - 2), 1);
		poseStack.pushPose();
		VertexConsumer vertexConsumer;
		if (translucentRender) {
			TextureAtlasSprite sprite = FILL_INDICATORS_TEXTURE.sprite();
			vertexConsumer = sprite.wrap(bufferSource.getBuffer(RenderType.entityTranslucent(sprite.atlasLocation())));
		} else {
			vertexConsumer = FILL_INDICATORS_TEXTURE.buffer(bufferSource, RenderType::entityCutoutNoCull);
		}
		PoseStack.Pose pose = poseStack.last();
		Vector3f normal = new Vector3f(0, 1, 0);
		pose.normal().transform(normal);
		float minU = large ? 0 : 3 / 128F;
		float maxV = large ? 68 / 128F : 28 / 128F;
		RenderHelper.renderQuad(vertexConsumer, pose.pose(), normal, packedOverlay, packedLight, translucentRender ? 0.5F : 1, minU, (1 - fillLevel) * maxV,
				minU + 3 / 128F, maxV);

		poseStack.popPose();
		poseStack.popPose();
	}

public static void renderLock(StorageBlockEntity blockEntity, PoseStack poseStack, MultiBufferSource bufferSource, int packedLight, int packedOverlay,
			float yOffset, BooleanSupplier holdsCorrectItem) {
		if (!blockEntity.isLocked() || (!holdsCorrectItem.getAsBoolean() && !blockEntity.shouldShowLock())) {
			return;
		}
		poseStack.pushPose();
		poseStack.translate(0.5 - 0.5 / 16D, yOffset, -0.001);
		poseStack.scale(1 / 16F, 1 / 16F, 1 / 16F);
		poseStack.pushPose();
		VertexConsumer vertexConsumer;
		boolean translucentRender = !blockEntity.shouldShowLock() && holdsCorrectItem.getAsBoolean();
		if (translucentRender) {
			TextureAtlasSprite sprite = LOCK_TEXTURE.sprite();
			vertexConsumer = sprite.wrap(bufferSource.getBuffer(RenderType.entityTranslucent(sprite.atlasLocation())));
		} else {
			vertexConsumer = LOCK_TEXTURE.buffer(bufferSource, RenderType::entityCutoutNoCull);
		}

		PoseStack.Pose pose = poseStack.last();
		Vector3f normal = new Vector3f(0, 1, 0);
		pose.normal().transform(normal);
		RenderHelper.renderQuad(vertexConsumer, pose.pose(), normal, packedOverlay, packedLight, translucentRender ? 0.5F : 1);

		poseStack.popPose();
		poseStack.popPose();
	}

public static TextureAtlasSprite getSprite(ResourceLocation blockName, @Nullable Direction direction, RandomSource rand) {
		return getSpriteData(blockName, direction, rand).sprite();
	}

public static SpriteData getSpriteData(ResourceLocation blockName, @Nullable Direction direction, RandomSource rand) {
		return getSpriteDataList(blockName, direction, rand).getFirst();
	}

public static List<SpriteData> getSpriteDataList(ResourceLocation blockName, @Nullable Direction direction, RandomSource rand) {
		int hash = blockName.hashCode();
		hash = hash * 31 + (direction == null ? 0 : direction.hashCode());

		List<SpriteData> spriteData = SPRITE_CACHE.getIfPresent(hash);
		if (spriteData == null) {
			spriteData = parseSpriteData(blockName, direction, rand);
			SPRITE_CACHE.put(hash, spriteData);
		}
		return spriteData;
	}

private static List<SpriteData> parseSpriteData(ResourceLocation blockName, @Nullable Direction direction, RandomSource rand) {
		BlockState blockState = getDefaultBlockState(blockName);

		List<SpriteData> spriteData = parseSpriteFromModel(blockState, direction, rand);

		if (spriteData.isEmpty()) {
			spriteData = List.of(new SpriteData(Minecraft.getInstance().getModelManager().getMissingModel().getParticleIcon(ModelData.EMPTY), -1, false));
		}

		return spriteData;
	}

@SuppressWarnings("java:S1874")
	// need to call deprecated getQuads here as well just in case it was overriden by mods instead of the main one
	private static List<SpriteData> parseSpriteFromModel(BlockState blockState, @Nullable Direction direction, RandomSource rand) {
		List<SpriteData> spriteData = new ArrayList<>();
		@Nullable
		SpriteData fallbackSpriteData = null;

		BakedModel blockModel = Minecraft.getInstance().getBlockRenderer().getBlockModel(blockState);
		try {
			for (RenderType layer : blockModel.getRenderTypes(blockState, rand, ModelData.EMPTY)) {
				boolean translucent = layer == RenderType.translucent();
				List<BakedQuad> culledQuads = blockModel.getQuads(blockState, direction, rand, ModelData.EMPTY, layer);
				if (!culledQuads.isEmpty()) {
					addSpriteData(spriteData, culledQuads, translucent);
					continue;
				}

				// noinspection deprecation
				for (BakedQuad bakedQuad : blockModel.getQuads(blockState, null, rand)) {
					if (fallbackSpriteData == null) {
						fallbackSpriteData = getSpriteData(bakedQuad, translucent);
					}

					if (bakedQuad.getDirection() == direction) {
						spriteData.add(getSpriteData(bakedQuad, translucent));
					}
				}
			}
		} catch (Exception e) {
			// NO OP
		}

		if (spriteData.isEmpty() && fallbackSpriteData != null) {
			spriteData.add(fallbackSpriteData);
		}

		if (spriteData.isEmpty()) {
			try {
				spriteData.add(new SpriteData(blockModel.getParticleIcon(ModelData.EMPTY), -1, false));
			} catch (Exception e) {
				// NO OP
			}
		}

		return List.copyOf(spriteData);
	}

private static void addSpriteData(List<SpriteData> spriteData, List<BakedQuad> quads, boolean translucent) {
		for (BakedQuad quad : quads) {
			spriteData.add(getSpriteData(quad, translucent));
		}
	}

private static SpriteData getSpriteData(BakedQuad quad, boolean translucent) {
		return new SpriteData(quad.getSprite(), quad.getTintIndex(), translucent);
	}

private static BlockState getDefaultBlockState(ResourceLocation blockName) {
		return BuiltInRegistries.BLOCK.getOptional(blockName).map(Block::defaultBlockState).orElse(Blocks.AIR.defaultBlockState());
