public void render(ShulkerBoxBlockEntity shulkerBoxEntity, float partialTick, PoseStack poseStack, MultiBufferSource bufferSource, int packedLight,
			int packedOverlay) {
		render(shulkerBoxEntity, partialTick, poseStack, bufferSource, packedLight, packedOverlay, false);
	}

public void render(ShulkerBoxBlockEntity shulkerBoxEntity, float partialTick, PoseStack poseStack, MultiBufferSource bufferSource, int packedLight,
			int packedOverlay, boolean forceClosedPreview) {
		BlockState blockState = shulkerBoxEntity.getBlockState();
		Direction direction = Direction.UP;
		if (shulkerBoxEntity.hasLevel()) {
			// noinspection ConstantConditions
			BlockState blockstate = shulkerBoxEntity.getLevel().getBlockState(shulkerBoxEntity.getBlockPos());
			if (blockstate.getBlock() instanceof ShulkerBoxBlock) {
				direction = blockstate.getValue(ShulkerBoxBlock.FACING);
			}
		} else if (forceClosedPreview && blockState.getBlock() instanceof ShulkerBoxBlock) {
			direction = blockState.getValue(ShulkerBoxBlock.FACING);
		}

		poseStack.pushPose();
		poseStack.translate(0.5D, 0.5D, 0.5D);
		poseStack.scale(0.9995F, 0.9995F, 0.9995F);
		poseStack.mulPose(direction.getRotation());
		poseStack.scale(1.0F, -1.0F, -1.0F);
		poseStack.translate(0.0D, -1.0D, 0.0D);
		ModelPart lidPart = model.getLid();
		float lidProgress = forceClosedPreview ? 0 : shulkerBoxEntity.getProgress(partialTick);
		lidPart.setPos(0.0F, 24.0F - lidProgress * 0.5F * 16.0F, 0.0F);
		lidPart.yRot = 270.0F * lidProgress * ((float) Math.PI / 180F);

		int mainColor = shulkerBoxEntity.getStorageWrapper().getMainColor();
		int accentColor = shulkerBoxEntity.getStorageWrapper().getAccentColor();

		if (mainColor == -1 || accentColor == -1) {
			VertexConsumer vertexconsumer = NO_TINT_MATERIAL.buffer(bufferSource, RenderType::entityCutoutNoCull);
			model.renderToBuffer(poseStack, vertexconsumer, packedLight, packedOverlay);
		}
		if (mainColor != -1) {
			renderTintedModel(poseStack, bufferSource, packedLight, packedOverlay, mainColor, TINTABLE_MAIN_MATERIAL);
		}
		if (accentColor != -1) {
			renderTintedModel(poseStack, bufferSource, packedLight, packedOverlay, accentColor, TINTABLE_ACCENT_MATERIAL);
		}
		if (shulkerBoxEntity.shouldShowTier()) {
			VertexConsumer vertexconsumer = getTierMaterial(blockState.getBlock()).buffer(bufferSource, RenderType::entityCutoutNoCull);
			model.renderToBuffer(poseStack, vertexconsumer, packedLight, packedOverlay);
		} else if (holdsItemThatShowsHiddenTiers()) {
			if (bufferSource instanceof MultiBufferSource.BufferSource multiBufferSource) {
				multiBufferSource.endBatch();
			}
			TextureAtlasSprite sprite = getTierMaterial(blockState.getBlock()).sprite();
			VertexConsumer vertexconsumer = sprite.wrap(bufferSource.getBuffer(RenderType.entityTranslucent(sprite.atlasLocation())));
			poseStack.pushPose();
			poseStack.translate(0, -0.01, 0);
			poseStack.scale(1.01f, 1.01f, 1.01f);
			int color = 0x7F_FFFFFF;
			model.renderToBuffer(poseStack, vertexconsumer, packedLight, packedOverlay, color);
			poseStack.popPose();
		}

		poseStack.popPose();

		poseStack.pushPose();

		poseStack.translate(0.5, 0.5, 0.5);
		poseStack.mulPose(getNorthBasedRotation(direction));

		float zOffset = 0;
		if (lidProgress > 0) {
			zOffset = lidProgress * 0.5f;
			poseStack.mulPose(Axis.ZP.rotationDegrees(270.0F * lidProgress));
		}

		poseStack.translate(-0.5D, -0.5D, -0.5D - zOffset);

		if (shulkerBoxEntity.shouldShowUpgrades() || holdsItemThatShowsUpgrades()) {
			displayItemRenderer.renderUpgradeItems(shulkerBoxEntity, poseStack, bufferSource, packedLight, packedOverlay, holdsItemThatShowsUpgrades(),
					shouldShowDisabledUpgradesDisplay(shulkerBoxEntity));
		}
		displayItemRenderer.renderDisplayItem(shulkerBoxEntity, poseStack, bufferSource, packedLight, packedOverlay);
		LockRenderer.renderLock(shulkerBoxEntity, poseStack, bufferSource, packedLight, packedOverlay, 15F / 16F, this::holdsToolInToggleLockOrLockDisplay);
		poseStack.popPose();
	}

private Material getTierMaterial(Block block) {
		if (block == ModBlocks.COPPER_SHULKER_BOX.get()) {
			return COPPER_TIER_MATERIAL;
		} else if (block == ModBlocks.IRON_SHULKER_BOX.get()) {
			return IRON_TIER_MATERIAL;
		} else if (block == ModBlocks.GOLD_SHULKER_BOX.get()) {
			return GOLD_TIER_MATERIAL;
		} else if (block == ModBlocks.DIAMOND_SHULKER_BOX.get()) {
			return DIAMOND_TIER_MATERIAL;
		} else if (block == ModBlocks.NETHERITE_SHULKER_BOX.get()) {
			return NETHERITE_TIER_MATERIAL;
		}
		return BASE_TIER_MATERIAL;
	}

private void renderTintedModel(PoseStack poseStack, MultiBufferSource bufferSource, int packedLight, int packedOverlay, int mainColor, Material material) {
		int color = 0xFF_000000 | mainColor;

		VertexConsumer vertexconsumer = material.buffer(bufferSource, RenderType::entityCutoutNoCull);
		model.renderToBuffer(poseStack, vertexconsumer, packedLight, packedOverlay, color);
	}

private SimpleCompositeModel(ImmutableMap<String, BlockModel> children) {
		this.children = children;
	}

@Override
	public BakedModel bake(IGeometryBakingContext context, ModelBaker baker, Function<Material, TextureAtlasSprite> spriteGetter, ModelState modelState,
			ItemOverrides overrides) {
		Material particleLocation = context.getMaterial(PARTICLE_MATERIAL);
		TextureAtlasSprite particle = spriteGetter.apply(particleLocation);

		var rootTransform = context.getRootTransform();
		if (!rootTransform.isIdentity()) {
			modelState = new SimpleModelState(modelState.getRotation().compose(rootTransform), modelState.isUvLocked());
		}

		var bakedPartsBuilder = ImmutableMap.<String, BakedModel>builder();
		for (var entry : children.entrySet()) {
			var name = entry.getKey();
			if (!context.isComponentVisible(name, true)) {
				continue;
			}
			var model = entry.getValue();
			bakedPartsBuilder.put(name, model.bake(baker, model, spriteGetter, modelState, true));
		}
		var bakedParts = bakedPartsBuilder.build();

		var itemPassesBuilder = ImmutableList.<BakedModel>builder();

		return new Baked(context.isGui3d(), context.useBlockLight(), context.useAmbientOcclusion(), particle, context.getTransforms(), overrides, bakedParts,
				itemPassesBuilder.build());
	}

@SuppressWarnings("java:S5803") // need to access textureMap here to get textures
	public Map<String, Either<Material, String>> getTextures() {
		HashMap<String, Either<Material, String>> textures = new HashMap<>();
		children.values().forEach(childModel -> {
			childModel.textureMap.forEach(textures::putIfAbsent);
			if (childModel.customData.hasCustomGeometry() && childModel.customData.getCustomGeometry() instanceof SimpleCompositeModel compositeModel) {
				compositeModel.getTextures().forEach(textures::putIfAbsent);
			} else if (childModel.parent != null) {
				childModel.parent.textureMap.forEach(textures::putIfAbsent);
			}
		});

		return textures;
	}

@Override
	public void resolveParents(Function<ResourceLocation, UnbakedModel> modelGetter, IGeometryBakingContext context) {
		children.values().forEach(childModel -> childModel.resolveParents(modelGetter));
	}

@SuppressWarnings("java:S1874") // need to get elements from the model so actually need to call getElements here
	public List<BlockElement> getElements() {
		List<BlockElement> elements = new ArrayList<>();

		children.forEach((name, model) -> {
