			if (!jsonObject.has("base")) {
				throw new JsonParseException("Simple material model requires a base model");
			}

			BlockModel baseModel = deserializationContext.deserialize(jsonObject.get("base"), BlockModel.class);
			BlockModel overlayModel = jsonObject.has("overlay") ? deserializationContext.deserialize(jsonObject.get("overlay"), BlockModel.class) : null;
			return new SimpleMaterialModel(baseModel, overlayModel);
		}

@Override
	public void render(T blockEntity, float partialTick, PoseStack poseStack, MultiBufferSource bufferSource, int packedLight, int packedOverlay) {
		renderHiddenOverlay(blockEntity, poseStack, bufferSource, packedLight, packedOverlay);
	}

public static void renderHiddenOverlay(BlockEntity blockEntity, PoseStack poseStack, MultiBufferSource bufferSource, int packedLight, int packedOverlay) {
		if (!(blockEntity instanceof ISimpleMaterialHolder simpleMaterialHolder) || !simpleMaterialHolder.isOverlayHidden()
				|| !holdsStorageToolThatShowsHiddenOverlay()) {
			return;
		}

		simpleMaterialHolder.getMaterial().ifPresent(material -> {
			ModelData overlayModelData = ModelData.builder().with(SimpleMaterialModel.MATERIAL, material).with(SimpleMaterialModel.OVERLAY_ONLY, true)
					.with(SimpleMaterialModel.OVERLAY_EXPANDED, true).build();
			poseStack.pushPose();
			poseStack.translate(-0.005, -0.005, -0.005);
			poseStack.scale(1.01f, 1.01f, 1.01f);
			renderOverlayOnly(blockEntity, poseStack, bufferSource, packedLight, packedOverlay, overlayModelData);
			if (blockEntity instanceof StorageLinkBlockEntity) {
				renderOverlayOnly(blockEntity, poseStack, bufferSource, packedLight, packedOverlay, overlayModelData);
			}
			poseStack.popPose();
		});
	}

private static void renderOverlayOnly(BlockEntity blockEntity, PoseStack poseStack, MultiBufferSource bufferSource, int packedLight, int packedOverlay,
			ModelData overlayModelData) {
		BlockState state = blockEntity.getBlockState();
		BakedModel blockModel = Minecraft.getInstance().getBlockRenderer().getBlockModel(state);
		VertexConsumer vertexConsumer = TranslucentVertexConsumer.getVertexConsumer(bufferSource, 255);
		RandomSource random = RandomSource.create(42L);
		for (Direction direction : Direction.values()) {
			renderQuads(blockModel.getQuads(state, direction, random, overlayModelData, RenderType.translucent()), poseStack, vertexConsumer, packedLight,
					packedOverlay);
			random.setSeed(42L);
		}
		renderQuads(blockModel.getQuads(state, null, random, overlayModelData, RenderType.translucent()), poseStack, vertexConsumer, packedLight,
				packedOverlay);
	}

private static void renderQuads(List<BakedQuad> quads, PoseStack poseStack, VertexConsumer vertexConsumer, int packedLight, int packedOverlay) {
		for (BakedQuad quad : quads) {
			vertexConsumer.putBulkData(poseStack.last(), quad, 1, 1, 1, 1, packedLight, packedOverlay, false);
		}
	}

private static boolean holdsStorageToolThatShowsHiddenOverlay() {
		refreshCache();
		return holdsStorageToolThatShowsHiddenOverlay;
	}

private static void refreshCache() {
		Minecraft minecraft = Minecraft.getInstance();
		if (minecraft.level == null || minecraft.level.getGameTime() == lastCacheTime) {
			return;
		}

		lastCacheTime = minecraft.level.getGameTime();
		LocalPlayer player = minecraft.player;
		if (player == null) {
			holdsStorageToolThatShowsHiddenOverlay = false;
			return;
		}

		holdsStorageToolThatShowsHiddenOverlay = InventoryHelper.getItemFromEitherHand(player, ModItems.STORAGE_TOOL.get())
				.map(storageTool -> StorageToolItem.getMode(storageTool) == StorageToolItem.Mode.TIER_DISPLAY).orElse(false);
	}

public static void render(StorageBlockEntity renderBlockEntity, float partialTicks, PoseStack poseStack, MultiBufferSource buffer, int packedLight,
			int packedOverlay) {
		renderInternal(renderBlockEntity, partialTicks, poseStack, buffer, packedLight, packedOverlay);
	}

private static void renderInternal(StorageBlockEntity renderBlockEntity, float partialTicks, PoseStack poseStack, MultiBufferSource buffer, int packedLight,
			int packedOverlay) {
		BlockState state = getClosedPreviewState(renderBlockEntity.getBlockState());
		Minecraft minecraft = Minecraft.getInstance();
		if (renderBlockEntity instanceof BarrelBlockEntity barrel && minecraft.level != null) {
			BlockRenderDispatcher blockRenderer = minecraft.getBlockRenderer();
			BakedModel bakedModel = blockRenderer.getBlockModel(state);
			ModelData modelData = BarrelBakedModelBase.getModelDataFromBlockEntity(barrel);
			BlockAndTintGetter wrappedLevel = new SingleBlockEntityTintGetter(minecraft.level, renderBlockEntity, state, packedLight);
			for (RenderType renderType : bakedModel.getRenderTypes(state, RandomSource.create(42L), modelData)) {
				VertexConsumer vertexConsumer = buffer.getBuffer(RenderTypeHelper.getEntityRenderType(renderType, false));
				RandomSource randomSource = RandomSource.create();
				randomSource.setSeed(42L);
				blockRenderer.getModelRenderer().tesselateWithoutAO(wrappedLevel, bakedModel, state, BlockPos.ZERO, poseStack, vertexConsumer, false,
						randomSource, state.getSeed(BlockPos.ZERO), packedOverlay, modelData, renderType);
			}
		}

		BlockEntityRenderer<?> renderer = minecraft.getBlockEntityRenderDispatcher().getRenderer(renderBlockEntity);
		if (renderer instanceof ChestRenderer chestRenderer && renderBlockEntity instanceof ChestBlockEntity chestBlockEntity) {
			chestRenderer.render(chestBlockEntity, partialTicks, poseStack, buffer, packedLight, OverlayTexture.NO_OVERLAY, true);
		} else if (renderer instanceof ShulkerBoxRenderer shulkerBoxRenderer && renderBlockEntity instanceof ShulkerBoxBlockEntity shulkerBoxBlockEntity) {
			shulkerBoxRenderer.render(shulkerBoxBlockEntity, partialTicks, poseStack, buffer, packedLight, OverlayTexture.NO_OVERLAY, true);
		} else if (renderer != null) {
			renderBlockEntity(renderer, renderBlockEntity, partialTicks, poseStack, buffer, packedLight);
		}
	}

@SuppressWarnings("unchecked")
	private static <T extends BlockEntity> void renderBlockEntity(BlockEntityRenderer<?> renderer, T blockEntity, float partialTicks, PoseStack poseStack,
			MultiBufferSource buffer, int packedLight) {
		((BlockEntityRenderer<T>) renderer).render(blockEntity, partialTicks, poseStack, buffer, packedLight, OverlayTexture.NO_OVERLAY);
	}

