private static ShulkerBoxFromChestRecipeDisplayRecipe createDisplayRecipe(RecipeHolder<ShulkerBoxFromChestRecipe> recipeHolder) {
		ShulkerBoxFromChestRecipe recipe = recipeHolder.value();
		int chestIngredientIndex = findChestIngredientIndex(recipe.getIngredients());
		NonNullList<Ingredient> ingredientsCopy = copyIngredients(recipe.getIngredients());
		List<CraftingDisplayVariant> variants = new ArrayList<>();
		List<CraftingDisplayVariant> globalVariants = new ArrayList<>();
		for (ItemStack chestItem : getChestItems(recipe)) {
			CraftingDisplayVariant variant = createVariant(recipe, chestIngredientIndex, chestItem);
			variants.add(variant);
			if (!isTinted(chestItem)) {
				globalVariants.add(variant);
			}
		}

		ResourceLocation id = recipeHolder.id().withPath(path -> "shulker_from_chest_grouped/" + path);
		RecipeHolder<CraftingRecipe> displayRecipeHolder = new RecipeHolder<>(recipeHolder.id(), new ShapedRecipe("", recipe.category(),
				new ShapedRecipePattern(recipe.getWidth(), recipe.getHeight(), ingredientsCopy, Optional.empty()), ClientRecipeHelper.getResultItem(recipe)));
		return new ShulkerBoxFromChestRecipeDisplayRecipe(id, displayRecipeHolder, recipe.getWidth(), recipe.getHeight(), ingredientsCopy, chestIngredientIndex,
				variants, globalVariants);
	}

private static CraftingDisplayVariant createVariant(ShulkerBoxFromChestRecipe recipe, int chestIngredientIndex, ItemStack chestItem) {
		CraftingContainer craftingInventory = createCraftingInventory();
		NonNullList<Ingredient> ingredients = recipe.getIngredients();
		List<ItemStack> inputs = new ArrayList<>(ingredients.size());
		for (int i = 0; i < ingredients.size(); i++) {
			if (i == chestIngredientIndex) {
				craftingInventory.setItem(i, chestItem.copy());
				inputs.add(chestItem.copy());
				continue;
			}
			Ingredient ingredient = ingredients.get(i);
			ItemStack[] ingredientItems = ingredient.getItems();
			craftingInventory.setItem(i, ingredient.isEmpty() ? ItemStack.EMPTY : ingredientItems[0]);
			inputs.add(ItemStack.EMPTY);
		}
		return new CraftingDisplayVariant(inputs, List.of(ClientRecipeHelper.assemble(recipe, craftingInventory.asCraftInput())));
	}

private static CraftingContainer createCraftingInventory() {
		return new TransientCraftingContainer(new AbstractContainerMenu(null, -1) {
			@Override
			public ItemStack quickMoveStack(Player player, int index) {
				return ItemStack.EMPTY;
			}

			public boolean stillValid(Player playerIn) {
				return false;
			}
		}, 3, 3);
	}

@Override
			public ItemStack quickMoveStack(Player player, int index) {
				return ItemStack.EMPTY;
			}

public boolean stillValid(Player playerIn) {
				return false;
			}

private static NonNullList<Ingredient> copyIngredients(NonNullList<Ingredient> ingredients) {
		NonNullList<Ingredient> ingredientsCopy = NonNullList.createWithCapacity(ingredients.size());
		ingredientsCopy.addAll(ingredients);
		return ingredientsCopy;
	}

private static int findChestIngredientIndex(NonNullList<Ingredient> ingredients) {
		for (int i = 0; i < ingredients.size(); i++) {
			for (ItemStack ingredientItem : ingredients.get(i).getItems()) {
				if (ingredientItem.getItem() instanceof ChestBlockItem) {
					return i;
				}
			}
		}
		throw new IllegalStateException("Shulker box from chest recipe missing chest ingredient");
	}

private static List<ItemStack> getChestItems(ShapedRecipe recipe) {
		NonNullList<ItemStack> chestItems = NonNullList.create();
		for (Ingredient ingredient : recipe.getIngredients()) {
			for (ItemStack ingredientItem : ingredient.getItems()) {
				Item item = ingredientItem.getItem();
				if (item instanceof ChestBlockItem chestBlockItem) {
					chestItems.add(new ItemStack(chestBlockItem));
					chestItems.addAll(DyeRecipesMaker.getWoodStorageStackList((StorageBlockBase) chestBlockItem.getBlock()));
					addTintedChestItems(chestItems, chestBlockItem);
				}
			}
		}
		return chestItems;
	}

private static void addTintedChestItems(List<ItemStack> chestItems, ChestBlockItem chestBlockItem) {
		for (DyeColor color : DyeColor.values()) {
			ItemStack chestStack = new ItemStack(chestBlockItem);
			chestBlockItem.setMainColor(chestStack, color.getTextureDiffuseColor());
			chestBlockItem.setAccentColor(chestStack, color.getTextureDiffuseColor());
			chestItems.add(chestStack);
		}
		ItemStack chestStack = new ItemStack(chestBlockItem);
		chestBlockItem.setMainColor(chestStack, DyeColor.YELLOW.getTextureDiffuseColor());
		chestBlockItem.setAccentColor(chestStack, DyeColor.LIME.getTextureDiffuseColor());
		chestItems.add(chestStack);
	}

private static boolean isTinted(ItemStack stack) {
		return StorageBlockItem.getMainColorFromComponentHolder(stack).isPresent() || StorageBlockItem.getAccentColorFromComponentHolder(stack).isPresent();
	}

private CraftingDisplaySpec toSpec() {
			return new CraftingDisplaySpec(id, false, width, height, ingredients, variants, globalVariants, Set.of(recipeHolder.id()),
					new ShulkerBoxFromChestFocusBehavior(chestIngredientIndex));
		}

private ShulkerBoxFromChestFocusBehavior(int chestIngredientIndex) {
			super(chestIngredientIndex, (variant, focusedInput) -> Optional.empty(), (variant, focusedOutput) -> Optional.empty());
			this.chestIngredientIndex = chestIngredientIndex;
		}

@Override
		public List<CraftingDisplayVariant> allDisplays(List<CraftingDisplayVariant> variants) {
			return variants;
		}

@Override
		public List<CraftingDisplayVariant> recipesFor(List<CraftingDisplayVariant> variants, ItemStack focusedOutput) {
			if (isTinted(focusedOutput)) {
				return variants.stream().filter(variant -> ItemStack.isSameItemSameComponents(variant.firstOutput(), focusedOutput)).toList();
			}
			return variants.stream().filter(variant -> ItemStack.isSameItem(variant.firstOutput(), focusedOutput) && !isTinted(variant.firstOutput())).toList();
		}

@Override
		public List<CraftingDisplayVariant> usagesFor(List<CraftingDisplayVariant> variants, ItemStack focusedInput) {
			if (focusedInput.getItem() instanceof ChestBlockItem) {
				return variants.stream().filter(variant -> chestIngredientIndex < variant.inputs().size()
						&& ItemStack.isSameItemSameComponents(variant.inputs().get(chestIngredientIndex), focusedInput)).toList();
			}
			return focusedInput.is(Items.SHULKER_SHELL) ? variants : List.of();
		}

public static void register(IRecipeViewerDisplayCatalog catalog, IRecipeViewerDisplayContext context) {
		registerDyeRecipes(catalog, context);
		catalog.addCraftingSpecExtensionRecipeClass(StorageTierUpgradeRecipe.class);
		catalog.addCraftingSpecExtensionRecipeClass(StorageTierUpgradeShapelessRecipe.class);
		catalog.addCraftingSpecExtensionRecipeClass(DoubleChestTierUpgradeRecipe.class);
		catalog.addCraftingSpecExtensionRecipeClass(DoubleChestTierUpgradeShapelessRecipe.class);
		catalog.addCraftingSpecExtensionRecipeClass(ShulkerBoxFromChestRecipe.class);
		TierUpgradeRecipesMaker.getGroupedShapedCraftingRecipes(context::getSubtypeInterpreter).stream().map(TierUpgradeDisplayRecipe::toSpec)
				.forEach(catalog::addCraftingSpec);
		TierUpgradeRecipesMaker.getGroupedShapelessCraftingRecipes(context::getSubtypeInterpreter).stream().map(TierUpgradeDisplayRecipe::toSpec)
				.forEach(catalog::addCraftingSpec);
		ShulkerBoxFromChestRecipesMaker.getShapedRecipeSpecs(context::getSubtypeInterpreter).forEach(catalog::addCraftingSpec);
		ClientRecipeHelper.transformAllRecipeHoldersOfType(RecipeType.CRAFTING, CraftingRecipe.class, (id, recipeHolder) -> recipeHolder).stream()
				.filter(StorageRecipeViewerDisplays::isBaseStorageRecipe).forEach(catalog::addCraftingRecipe);
		GenericWoodStorageRecipesMaker.getRecipes().forEach(catalog::addCraftingRecipe);
		FlatBarrelRecipesMaker.getShapelessRecipes().forEach(catalog::addCraftingRecipe);
		ClientRecipeHelper.transformAllRecipeHoldersOfType(RecipeType.CRAFTING, ShulkerBoxFromVanillaShapelessRecipe.class,
				(id, recipeHolder) -> new RecipeHolder<CraftingRecipe>(id, recipeHolder.value())).forEach(catalog::addCraftingRecipe);
	}

private static boolean isBaseStorageRecipe(RecipeHolder<CraftingRecipe> recipeHolder) {
		CraftingRecipe recipe = recipeHolder.value();
		ItemStack result = ClientRecipeHelper.getResultItem(recipe);
		return recipeHolder.id().getNamespace().equals("sophisticatedstorage") && result.getItem() instanceof StorageBlockItem
				&& WoodStorageBlockItem.getWoodType(result).isPresent() && !(recipe instanceof StorageTierUpgradeRecipe)
				&& !(recipe instanceof StorageTierUpgradeShapelessRecipe) && !(recipe instanceof DoubleChestTierUpgradeRecipe)
				&& !(recipe instanceof DoubleChestTierUpgradeShapelessRecipe) && !(recipe instanceof ShulkerBoxFromChestRecipe)
				&& !(recipe instanceof ShulkerBoxFromVanillaShapelessRecipe) && !(recipe instanceof GenericWoodStorageRecipe);
	}

public static void registerDyeRecipes(IRecipeViewerDisplayCatalog catalog, IRecipeViewerDisplayContext context) {
		DyeRecipesMaker.getSingleColorRecipeSpecs(context::getSubtypeInterpreter).stream()
				.map(spec -> new SingleColorDyeRecipeSpec(spec.id(), spec.sourceStacks(), spec.variantPairs(),
						(recipeResult, focusedOutput) -> context.getSubtypeInterpreter(focusedOutput)
								.map(interpreter -> recipeResult.is(focusedOutput.getItem())
										&& interpreter.getComparableData(recipeResult).equals(interpreter.getComparableData(focusedOutput)))
								.orElse(ItemStack.isSameItemSameComponents(recipeResult, focusedOutput))))
				.forEach(catalog::addGroupedCraftingSpec);
		DyeRecipesMaker.getMultipleColorsRecipes(context::getSubtypeInterpreter).forEach(catalog::addCraftingRecipe);
	}

public Optional<TierUpgradeVariantPair> findBySource(ItemStack stack) {
		return variantPairs.stream().filter(pair -> ItemStack.isSameItemSameComponents(pair.source(), stack)).findFirst();
	}

public Optional<TierUpgradeVariantPair> findBySourceItem(ItemStack stack) {
		return variantPairs.stream().filter(pair -> ItemStack.isSameItem(pair.source(), stack) && matchesStorageKind(pair.source(), stack)).findFirst();
	}

public Optional<TierUpgradeVariantPair> findByResult(ItemStack stack) {
		return variantPairs.stream().filter(pair -> ItemStack.isSameItemSameComponents(pair.result(), stack)).findFirst();
	}

public Optional<TierUpgradeVariantPair> findByResultItem(ItemStack stack) {
		return variantPairs.stream().filter(pair -> ItemStack.isSameItem(pair.result(), stack) && matchesStorageKind(pair.result(), stack)).findFirst();
	}

private static boolean matchesStorageKind(ItemStack recipeStack, ItemStack focusedStack) {
		return !(recipeStack.getItem() instanceof ChestBlockItem) || ChestBlockItem.isDoubleChest(recipeStack) == ChestBlockItem.isDoubleChest(focusedStack);
	}

private static TierUpgradeVariantPair withComponentsFromSource(TierUpgradeVariantPair pair, ItemStack sourceStack) {
		return new TierUpgradeVariantPair(sourceStack.copy(), sourceStack.transmuteCopy(pair.result().getItem(), 1));
	}

private static TierUpgradeVariantPair withComponentsFromResult(TierUpgradeVariantPair pair, ItemStack resultStack) {
		return new TierUpgradeVariantPair(resultStack.transmuteCopy(pair.source().getItem(), 1), resultStack.copy());
	}

public CraftingDisplaySpec toSpec() {
		VariantLookup lookup = new VariantLookup(variantPairs);
		return new CraftingDisplaySpec(id, shapeless, width, height, ingredients, variantPairs.stream().map(this::toVariant).toList(), getGlobalVariants(),
				Set.of(recipeHolder.id()),
				new SourceResultFocusBehavior(storageIngredientIndex, (variant, focusedInput) -> focusSource(variant, focusedInput, lookup),
						(variant, focusedOutput) -> focusResult(variant, focusedOutput, lookup)));
	}

private List<CraftingDisplayVariant> getGlobalVariants() {
		return variantPairs.stream()
				.filter(pair -> StorageBlockItem.getMainColorFromComponentHolder(pair.source()).isEmpty()
						&& StorageBlockItem.getAccentColorFromComponentHolder(pair.source()).isEmpty()
						&& StorageBlockItem.getMainColorFromComponentHolder(pair.result()).isEmpty()
						&& StorageBlockItem.getAccentColorFromComponentHolder(pair.result()).isEmpty())
				.map(this::toVariant).toList();
	}

private CraftingDisplayVariant toVariant(TierUpgradeVariantPair pair) {
		List<ItemStack> inputs = new ArrayList<>(ingredients.size());
		for (int i = 0; i < ingredients.size(); i++) {
			inputs.add(i == storageIngredientIndex ? pair.source() : ItemStack.EMPTY);
		}
		return new CraftingDisplayVariant(inputs, List.of(pair.result()));
	}

private Optional<CraftingDisplayVariant> focusSource(CraftingDisplayVariant variant, ItemStack focusedInput, VariantLookup lookup) {
		ItemStack source = getSource(variant);
		Optional<TierUpgradeVariantPair> exactPair = lookup.findBySource(focusedInput);
		if (exactPair.isPresent()) {
			return exactPair.filter(pair -> ItemStack.isSameItemSameComponents(source, pair.source())).map(this::toVariant);
		}
		return lookup.findBySourceItem(focusedInput).filter(pair -> ItemStack.isSameItemSameComponents(source, pair.source()))
				.map(pair -> withComponentsFromSource(pair, focusedInput)).map(this::toVariant);
	}

private Optional<CraftingDisplayVariant> focusResult(CraftingDisplayVariant variant, ItemStack focusedOutput, VariantLookup lookup) {
		Optional<TierUpgradeVariantPair> exactPair = lookup.findByResult(focusedOutput);
		if (exactPair.isPresent()) {
			return exactPair.filter(pair -> ItemStack.isSameItemSameComponents(variant.firstOutput(), pair.result())).map(this::toVariant);
		}
		return lookup.findByResultItem(focusedOutput).filter(pair -> ItemStack.isSameItemSameComponents(variant.firstOutput(), pair.result()))
				.map(pair -> withComponentsFromResult(pair, focusedOutput)).map(this::toVariant);
	}

private static ItemStack getSource(CraftingDisplayVariant variant) {
		return variant.inputs().stream().filter(stack -> !stack.isEmpty()).findFirst().orElse(ItemStack.EMPTY);
	}

private VariantLookup(List<TierUpgradeVariantPair> variantPairs) {
			for (TierUpgradeVariantPair pair : variantPairs) {
				addPair(sourcePairsByHash, pair.source(), pair);
				addPair(resultPairsByHash, pair.result(), pair);
				addFirstPair(sourcePairsByItem, doubleChestSourcePairsByItem, pair.source(), pair);
				addFirstPair(resultPairsByItem, doubleChestResultPairsByItem, pair.result(), pair);
			}
		}

private Optional<TierUpgradeVariantPair> findBySource(ItemStack stack) {
			List<TierUpgradeVariantPair> pairs = sourcePairsByHash.get(ItemStack.hashItemAndComponents(stack));
			if (pairs != null) {
				for (TierUpgradeVariantPair pair : pairs) {
					if (ItemStack.isSameItemSameComponents(pair.source(), stack)) {
						return Optional.of(pair);
					}
				}
			}
			return Optional.empty();
		}

private Optional<TierUpgradeVariantPair> findBySourceItem(ItemStack stack) {
			return Optional.ofNullable(getFirstPair(sourcePairsByItem, doubleChestSourcePairsByItem, stack));
		}

private Optional<TierUpgradeVariantPair> findByResult(ItemStack stack) {
			List<TierUpgradeVariantPair> pairs = resultPairsByHash.get(ItemStack.hashItemAndComponents(stack));
			if (pairs != null) {
				for (TierUpgradeVariantPair pair : pairs) {
					if (ItemStack.isSameItemSameComponents(pair.result(), stack)) {
						return Optional.of(pair);
					}
				}
			}
			return Optional.empty();
		}

private Optional<TierUpgradeVariantPair> findByResultItem(ItemStack stack) {
			return Optional.ofNullable(getFirstPair(resultPairsByItem, doubleChestResultPairsByItem, stack));
		}

private static void addPair(Map<Integer, List<TierUpgradeVariantPair>> pairsByHash, ItemStack stack, TierUpgradeVariantPair pair) {
			pairsByHash.computeIfAbsent(ItemStack.hashItemAndComponents(stack), ignored -> new ArrayList<>()).add(pair);
		}

private static void addFirstPair(Map<Item, TierUpgradeVariantPair> pairsByItem, Map<Item, TierUpgradeVariantPair> doubleChestPairsByItem,
				ItemStack stack, TierUpgradeVariantPair pair) {
			Map<Item, TierUpgradeVariantPair> pairs = stack.getItem() instanceof ChestBlockItem && ChestBlockItem.isDoubleChest(stack)
					? doubleChestPairsByItem
					: pairsByItem;
			pairs.putIfAbsent(stack.getItem(), pair);
		}

private static TierUpgradeVariantPair getFirstPair(Map<Item, TierUpgradeVariantPair> pairsByItem,
				Map<Item, TierUpgradeVariantPair> doubleChestPairsByItem, ItemStack stack) {
			return (stack.getItem() instanceof ChestBlockItem && ChestBlockItem.isDoubleChest(stack) ? doubleChestPairsByItem : pairsByItem)
					.get(stack.getItem());
		}

public static <T extends PropertyBasedSubtypeInterpreter> List<TierUpgradeDisplayRecipe> getGroupedShapedCraftingRecipes(
