@Override
		protected Iterable<Block> getKnownBlocks() {
			return BuiltInRegistries.BLOCK.entrySet().stream().filter(e -> e.getKey().location().getNamespace().equals(SophisticatedStorage.MOD_ID))
					.map(Map.Entry::getValue).toList();
		}

private static LootTable.Builder dropStorageWithContents(Item storageItem) {
			LootPool.Builder pool = LootPool.lootPool().name("main").setRolls(ConstantValue.exactly(1)).add(LootItem.lootTableItem(storageItem))
					.apply(CopyNameFunction.copyName(CopyNameFunction.NameSource.BLOCK_ENTITY)).apply(CopyStorageDataFunction.builder());
			return LootTable.lootTable().withPool(pool);
		}

public LootTable.Builder dropBlock(ItemLike item) {
			return LootTable.lootTable().withPool(
					applyExplosionCondition(item, LootPool.lootPool().name("main").setRolls(ConstantValue.exactly(1.0F)).add(LootItem.lootTableItem(item))));
		}

private LootTable.Builder dropSimpleMaterialBlock(ItemLike item) {
			return LootTable.lootTable().withPool(applyExplosionCondition(item, LootPool.lootPool().name("main").setRolls(ConstantValue.exactly(1.0F))
					.add(LootItem.lootTableItem(item).apply(CopyStorageDataFunction.builder()))));
		}

public StorageRecipeProvider(DataGenerator generator, CompletableFuture<HolderLookup.Provider> registries) {
		super(generator.getPackOutput(), registries);
	}

@Override
	protected void buildRecipes(RecipeOutput recipeOutput) {
		SpecialRecipeBuilder.special(StorageDyeRecipe::new).save(recipeOutput, SophisticatedStorage.getRegistryName("storage_dye"));
		SpecialRecipeBuilder.special(FlatTopBarrelToggleRecipe::new).save(recipeOutput, SophisticatedStorage.getRegistryName("flat_top_barrel_toggle"));
		SpecialRecipeBuilder.special(BarrelMaterialRecipe::new).save(recipeOutput, SophisticatedStorage.getRegistryName("barrel_material"));

		addBarrelRecipes(recipeOutput);
		addLimitedBarrelRecipes(recipeOutput);
		addChestRecipes(recipeOutput);
		addShulkerBoxRecipes(recipeOutput);
		addControllerRelatedRecipes(recipeOutput);
		addUpgradeRecipes(recipeOutput);
		addTierUpgradeItemRecipes(recipeOutput);
		addBackpackUpgradeConversionRecipes(recipeOutput);

		ShapelessRecipeBuilder.shapeless(RecipeCategory.MISC, ModItems.PACKING_TAPE.get()).requires(Tags.Items.SLIME_BALLS).requires(Items.PAPER)
				.unlockedBy("has_slime", has(Tags.Items.SLIME_BALLS)).save(recipeOutput.withConditions(new DropPackedDisabledCondition()));

		ShapelessRecipeBuilder.shapeless(RecipeCategory.MISC, ModItems.SUPER_PACKING_TAPE.get()).requires(ModItems.PACKING_TAPE.get())
				.requires(ModItems.PACKING_TAPE.get()).requires(ModItems.PACKING_TAPE.get()).requires(ModItems.PACKING_TAPE.get())
				.unlockedBy("has_packing_tape", has(ModItems.PACKING_TAPE.get())).save(recipeOutput.withConditions(new DropPackedDisabledCondition()));

		ShapedRecipeBuilder.shaped(RecipeCategory.MISC, ModBlocks.DECORATION_TABLE_ITEM.get()).pattern("LLL").pattern("PBP").pattern("P P")
				.define('L', ItemTags.LOGS).define('P', ItemTags.PLANKS).define('B', ModItems.UPGRADE_BASE.get())
				.unlockedBy("has_upgrade_base", has(ModItems.UPGRADE_BASE.get())).save(recipeOutput);

		ShapedRecipeBuilder.shaped(RecipeCategory.MISC, ModItems.PAINTBRUSH.get()).pattern(" W ").pattern(" SW").pattern("S  ")
				.define('S', Tags.Items.RODS_WOODEN).define('W', ItemTags.WOOL)
				.unlockedBy("has_base_tier_wooden_storage", has(ModBlocks.BASE_TIER_WOODEN_STORAGE_TAG)).save(recipeOutput);
	}

