private static void addCompatUpgradeRecipe(RecipeOutput recipeOutput, Item upgrade, Block workbench, Item backpackUpgrade, String modId) {
		RecipeOutput compatRecipeOutput = recipeOutput.withConditions(new ModLoadedCondition(modId));
		ShapeBasedRecipeBuilder.shaped(upgrade).pattern(" W ").pattern("IBI").pattern(" R ").define('B', ModItems.UPGRADE_BASE.get())
				.define('R', Tags.Items.DUSTS_REDSTONE).define('I', Tags.Items.INGOTS_IRON).define('W', workbench)
				.unlockedBy(HAS_UPGRADE_BASE_CRITERION_NAME, has(ModItems.UPGRADE_BASE.get())).save(compatRecipeOutput);

		RecipeOutput sbCompatRecipeOutput = compatRecipeOutput.withConditions(new ModLoadedCondition(SophisticatedBackpacks.MOD_ID));
		RecipeOutput sbCompatRecipeWithoutAdvancements = new RecipeOutputWithoutAdvancements(sbCompatRecipeOutput);

		// storage from backpack upgrade
		ShapeBasedRecipeBuilder.shaped(upgrade).pattern("PUP").pattern(" P ").pattern("P P").define('P', ItemTags.PLANKS).define('U', backpackUpgrade)
				.unlockedBy("has_backpack_upgrade", has(backpackUpgrade)).save(sbCompatRecipeWithoutAdvancements, ResourceLocation.fromNamespaceAndPath(
						SophisticatedStorage.MOD_ID, "storage_" + getCompatItemPath(upgrade) + "_from_backpack_" + getCompatItemPath(backpackUpgrade)));

		// backpack from storage upgrade
		ShapeBasedRecipeBuilder.shaped(backpackUpgrade).pattern("TUT").pattern(" L ").pattern("T T").define('T', Tags.Items.STRINGS)
				.define('L', Tags.Items.LEATHERS).define('U', upgrade).unlockedBy("has_storage_upgrade", has(upgrade))
				.save(sbCompatRecipeWithoutAdvancements, ResourceLocation.fromNamespaceAndPath(SophisticatedStorage.MOD_ID,
						"backpack_" + getCompatItemPath(backpackUpgrade) + "_from_storage_" + getCompatItemPath(upgrade)));
	}

