        WaystonesConfigData config = WaystonesConfig.getActive();
        if (config.compatibility.preferJourneyMapIntegration && Balm.isModLoaded("jmi")) {
            return false;
        }

        return config.compatibility.displayWaystonesOnJourneyMap;
